// 文法詳解 N1(老師口吻,scripts/gen-grammar-detail.mjs 產生、build-grammar-detail.mjs 合併;改風格改 scripts/grammar-detail-samples.js 再重產)。
// key=文法 id;value=HTML(渲染時 .gd-jp 日文過 furiganaHTML→furigana+即點即查;中文解說不動)。
window.GRAMMAR_DETAIL = window.GRAMMAR_DETAIL || {};
Object.assign(window.GRAMMAR_DETAIL, {
  "n1-14": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜なり」就是中文的<b>「一～就…」</b>，還帶點「欸，這麼快？」的驚訝。像你在跟朋友講：「他一進門，鞋都沒脫就衝進房間。」通常是在描述<b>別人</b>剛做完一個動作，馬上又做了下一個讓人有點意外的動作。</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>動詞的辭書形（就是字典裡查得到的原形）直接加「なり」，不用變化。<br><span class='gd-pair'><span class='gd-jp'>帰る</span> → <span class='gd-jp'>帰るなり</span></span><span class='gd-pair'><span class='gd-jp'>聞く</span> → <span class='gd-jp'>聞くなり</span></span><span class='gd-pair'><span class='gd-jp'>見る</span> → <span class='gd-jp'>見るなり</span></span></div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>描述別人的反應</span>前一個動作才剛做完，同一個人馬上有了下一個動作，而且這個動作有點突然。</div><div class='gd-ex-line'>・<span class='gd-jp'>彼は家に帰るなり、部屋にこもってしまった。</span>（他一回到家，就把自己關進房間）</div><div class='gd-ex-line'>・<span class='gd-jp'>その知らせを聞くなり、彼女は泣き出した。</span>（一聽到那個消息，她就哭了出來）</div><div class='gd-ex-line'>・<span class='gd-jp'>息子は私の顔を見るなり、走って逃げた。</span>（兒子一看到我，拔腿就跑）</div><div class='gd-sec'><span class='gd-tag'>講故事的口吻</span>多半出現在小說、文章，或把一件事「說給別人聽」的時候。平常聊天講「一～就」，比較常用 N3 學過的「〜たとたん」。</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・<b>前後要是同一個人</b>。「他一回家，<b>他</b>就關進房間」可以；「鈴一響，學生就衝出去」主角換人了，用なり會怪。<br>・<b>通常不拿來講自己</b>。なり有種旁觀者在描述的感覺，講自己「我一回家就睡了」，說<span class='gd-jp'>家に帰ってすぐ寝た。</span>比較自然。<br>・後面接的是<b>已經發生的事</b>，不能接命令、邀約、打算：<br>×<span class='gd-jp'>家に帰るなり、宿題をしなさい。</span>（不能用來叫人做事）<br>・前面一定是辭書形。換成た形的「<span class='gd-jp'>〜たなり</span>」是另一個意思：「～之後就一直那樣」，例如<span class='gd-jp'>出かけたなり、帰ってこない。</span>（出門之後就一直沒回來）<br>・「<span class='gd-jp'>〜なり〜なり</span>」（～或～都行）、「<span class='gd-jp'>私なりに</span>」（用我自己的方式）長得一樣，是完全不同的文法，不要混在一起。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>N1 有好幾個「一～就」，同樣接辭書形，後面也都是已經發生的事，差別在<b>誰做的、強調什麼、用在哪</b>。<br><br><b>なり</b>：同一個人，做出有點意外的動作。<br><span class='gd-jp'>部長は会議室に入るなり、大声で怒鳴り始めた。</span>（部長一走進會議室，就開始大吼）<br><br><b>や否や</b>：很書面，<b>前後可以是不同的人或事</b>。<br><span class='gd-jp'>ベルが鳴るや否や、学生たちは教室を飛び出した。</span>（鈴一響，學生們就衝出教室）<br><br><b>が早いか</b>：重點在<b>快</b>，前面剛做完，後面幾乎同時就做了。<br><span class='gd-jp'>子どもたちは「いただきます」と言うが早いか、料理に手を伸ばした。</span>（孩子們「我開動了」才剛說完，手就伸向菜了）<br><br><b>たとたん</b>（N3）：日常口語，<b>講自己也可以</b>，後面常是自己控制不了的事。<br><span class='gd-jp'>立ち上がったとたん、めまいがした。</span>（一站起來就頭暈）</div><div class='gd-warn'>判斷小訣竅：同一個人突然做了什麼 → なり；兩件不同的事緊接著發生、又是寫文章 → や否や；想強調手腳超快 → が早いか；講自己、平常聊天 → たとたん。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>接著看同一組的「<span class='gd-jp'>〜が早いか</span>」「<span class='gd-jp'>〜や否や</span>」，再對照「<span class='gd-jp'>〜そばから</span>」（才剛～馬上又～，講一再重複的事），這幾個一起記最不會搞混。</div>",
  "n1-15": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜が早いか」就是中文的<b>「一～就立刻…」</b>，而且是快到<b>分不清哪件事先發生</b>的那種。字面意思是「（前面那件事）比較快嗎？」：前一個動作才剛開始，後一個動作已經發生了。就像下課鐘才剛響，學生已經衝到走廊上。</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>描寫看到的場面</span>用來講<b>已經發生</b>的事，句尾大多是過去式。小說、文章、新聞描寫很常見，日常聊天幾乎不會講。</div><div class='gd-ex-line'>・<span class='gd-jp'>チャイムが鳴るが早いか、子供たちは教室を飛び出した。</span>（鐘聲一響，孩子們就衝出教室）</div><div class='gd-ex-line'>・<span class='gd-jp'>彼は家に帰るが早いか、ベッドに倒れ込んだ。</span>（他一回到家就倒在床上）</div><div class='gd-ex-line'>・<span class='gd-jp'>新商品は発売されるが早いか、売り切れてしまった。</span>（新商品一開賣就賣光了）</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>動詞的辭書形（字典上查到的原形）直接加「が早いか」，不用改形。<br><span class='gd-pair'><span class='gd-jp'>鳴る</span> → <span class='gd-jp'>鳴るが早いか</span></span><span class='gd-pair'><span class='gd-jp'>帰る</span> → <span class='gd-jp'>帰るが早いか</span></span><span class='gd-pair'><span class='gd-jp'>発売される</span> → <span class='gd-jp'>発売されるが早いか</span></span><br>就算整句是過去的事，前面也還是用辭書形，時態交給句尾。偶爾也會看到た形，例如<span class='gd-jp'>言ったが早いか</span>，不過先記辭書形就夠用。</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・後面<b>不能接命令、拜託、自己的打算</b>：×<span class='gd-jp'>家に着くが早いか、電話してください。</span>想說「到家馬上打給我」，要說<span class='gd-jp'>家に着いたら、すぐ電話してください。</span><br>・中文的「一～就～」用途很廣，像「一到春天花就開」這種<b>規律、條件</b>不能用が早いか，那是<span class='gd-jp'>春になると、花が咲く。</span><br>・語氣很硬。跟朋友講「我一到家就睡了」，說<span class='gd-jp'>家に帰って、すぐ寝ちゃった。</span>就好，用が早いか會像在念小說。<br>・前面不要加ます：×<span class='gd-jp'>鳴りますが早いか</span>。<br>・「早い」念<b>はやい</b>。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>同一個場面，三種說法都對：<br><span class='gd-jp'>息子は帰ってくるが早いか、かばんを置いて遊びに行った。</span><br><span class='gd-jp'>息子は帰ってくるなり、かばんを置いて遊びに行った。</span><br><span class='gd-jp'>息子は帰ってくるや否や、かばんを置いて遊びに行った。</span><br>（兒子一回來，就放下書包跑去玩了）</div><div class='gd-sec'><b>なり</b>：前後一定是<b>同一個人</b>做的動作，後面常是讓人有點意外的舉動。所以「鐘一響，學生就衝出去」不能用なり：×<span class='gd-jp'>チャイムが鳴るなり、生徒が飛び出した。</span><br><b>や否や</b>：前後可以是不同的人或事，語氣<b>最書面、最正式</b>，新聞報導很愛用：<span class='gd-jp'>ドアが開くや否や、客が店内になだれ込んだ。</span>（門一開，客人就湧進店裡）<br><b>が早いか</b>：前後也可以不同主詞，重點放在<b>快到分不出先後</b>，常帶有迫不及待、搶著做的畫面。</div><div class='gd-warn'>判斷小訣竅：同一個人、後面的舉動有點出人意料，用なり；想強調「快到幾乎同時」，用が早いか；正式的書面報導，用や否や。三個後面都不能接命令、拜託或自己的打算。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>「〜そばから」看起來也像「一～就～」，但它是<b>一再重複</b>的「才剛～就又…」：<span class='gd-jp'>覚えるそばから忘れてしまう。</span>（才剛背好就又忘了）。要講的是「每次都這樣」，不是單一次的「快」。</div>",
  "n1-16": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜や否や」就是中文的<b>「一～就～」</b>，而且是<b>剛做完、下一件事馬上就發生</b>的那種快。它是很正式的<b>書面說法</b>，常出現在小說、新聞、文章裡。你可以把它想成<span class='gd-jp'>〜たとたん</span>的書面版。</div><div class='gd-h'>先搞懂這個字</div><div class='gd-sec'>念<b>やいなや</b>。「否」就是「不」。整句原本的意思是「到底做了沒，都還分不清楚」，也就是<b>前一個動作才剛發生，後面就接著來了</b>。記住這個畫面，就知道它強調的是「快」。</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>動詞辭書形＋や否や<br><span class='gd-pair'><span class='gd-jp'>目を覚ます</span> → <span class='gd-jp'>目を覚ますや否や</span></span>（一睜開眼就～）<br><span class='gd-pair'><span class='gd-jp'>ドアが開く</span> → <span class='gd-jp'>ドアが開くや否や</span></span>（門一開就～）<br>文章裡有時只寫一個「や」，意思一樣：<span class='gd-jp'>家に着くや</span>（一到家就～）。</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>描述已經發生的事</span>講故事、報導一件事「A 一發生，B 馬上就發生了」。後面通常是過去式。</div><div class='gd-ex-line'>・<span class='gd-jp'>ドアが開くや否や、子どもたちが飛び出してきた。</span>（門一開，孩子們就衝了出來）</div><div class='gd-ex-line'>・<span class='gd-jp'>新商品は発売されるや否や、売り切れた。</span>（新商品一開賣就賣光了）</div><div class='gd-ex-line'>・<span class='gd-jp'>社長が現れるや否や、会場は静まり返った。</span>（社長一出現，會場立刻安靜下來）</div><div class='gd-sec'>前後可以是<b>不同的人或東西</b>：上面「門開」跟「孩子衝出來」就是兩個不同的主角，這樣用沒問題。</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・前面要用<b>辭書形</b>，不是た形：是<span class='gd-jp'>帰るや否や</span>，不是「帰ったや否や」。中文說「一回來就」，很多人會順手寫成過去式。<br>・「否」念<b>いな</b>，不是ひ。<br>・後面不能放「我要～」「請～」「～吧」這種請求或打算。<br>　× 駅に着くや否や、電話してください。<br>　○ <span class='gd-jp'>駅に着いたら、すぐ電話してください。</span>（到了車站請馬上打給我）<br>・它很硬、很文章，跟朋友聊天說「我一到家就睡了」，講<span class='gd-jp'>家に着いたとたん、寝ちゃった</span>或<span class='gd-jp'>帰ってすぐ寝た</span>就好。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>同一個情境「他一進房間就哭了」：<br><span class='gd-tag'>や否や</span><span class='gd-jp'>彼は部屋に入るや否や、泣き出した。</span><br>最正式、最書面，前後可以不同主角。<br><span class='gd-tag'>なり</span><span class='gd-jp'>彼は部屋に入るなり、泣き出した。</span><br>前後一定是<b>同一個人</b>，常帶「怎麼突然這樣」的意外感。<br><span class='gd-tag'>が早いか</span><span class='gd-jp'>彼は部屋に入るが早いか、泣き出した。</span><br>更強調「快到幾乎同時」，小說味很重；前面也可以用た形。<br><span class='gd-tag'>たとたん</span><span class='gd-jp'>彼は部屋に入ったとたん、泣き出した。</span><br>日常版，講話寫字都能用，前面是た形。</div><div class='gd-sec'>另外兩個也常被拿來混：<br><b>次第</b>可以接請求、打算：<span class='gd-jp'>着き次第、連絡します。</span>（一到就跟你聯絡）這句換成や否や就不行。<br><b>そばから</b>是「做了馬上又被抵消，而且一直重複」：<span class='gd-jp'>覚えるそばから忘れてしまう。</span>（剛記住馬上又忘，一直這樣）。這不是單一次的「一～就～」。</div><div class='gd-warn'>判斷小訣竅：要請對方做事用「次第」；一直重複的白做工用「そばから」；描述一次已經發生的事，聊天用「たとたん」，寫文章用「や否や」。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>把<span class='gd-jp'>〜なり</span>、<span class='gd-jp'>〜が早いか</span>、<span class='gd-jp'>〜そばから</span>一起看，這組「一～就～」在 N1 考試很常一起出來比。</div>",
  "n1-8": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜ならでは」就是中文的<b>「只有～才有的」「不愧是～才做得到」</b>。比如說「京都才有的風景」「手工才有的溫度」，你要強調<b>這個東西別的地方沒有、只有它有</b>，而且通常是在稱讚。</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>前面直接接<b>名詞</b>，後面最常再接「の＋名詞」。<br><span class='gd-pair'><span class='gd-jp'>職人</span> → <span class='gd-jp'>職人ならではの技術</span></span>（只有工匠才有的技術）<br><span class='gd-pair'><span class='gd-jp'>地元</span> → <span class='gd-jp'>地元ならではの料理</span></span>（只有當地才吃得到的料理）<br>前面放的通常是<b>人、地方、店、某種做法</b>這類有自己特色的東西。</div><div class='gd-h'>最常看到的樣子</div><div class='gd-sec'><span class='gd-tag'>ならではの＋名詞</span>最常用，九成都是這個樣子。</div><div class='gd-ex-line'>・<span class='gd-jp'>子どもならではの自由な発想に驚いた。</span>（小孩子才有的自由想法讓我很驚訝）</div><div class='gd-ex-line'>・<span class='gd-jp'>旅館ならではのおもてなしを楽しんだ。</span>（享受了只有日式旅館才有的款待）</div><div class='gd-sec'><span class='gd-tag'>ならではだ</span>放在句尾，等於「這正是～才做得到的」。</div><div class='gd-ex-line'>・<span class='gd-jp'>この味は、老舗ならではだ。</span>（這個味道，只有老店才做得出來）</div><div class='gd-sec'><span class='gd-tag'>ならでは〜ない</span>比較書面、老派的說法，意思是「不是～就沒辦法～」。看得懂就好。</div><div class='gd-ex-line'>・<span class='gd-jp'>この味は、この店ならでは味わえない。</span>（這個味道，不是這家店就吃不到）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・這裡的「なら」<b>不是「如果」</b>，不要翻成「如果是～的話」。<br>・「では」的「は」念<b>わ</b>，整個念ならでわ。<br>・前面直接接名詞，<b>不要多加の</b>：是<span class='gd-jp'>日本ならではの</span>，不是日本のならではの。<br>・它的重點是「<b>只有它有</b>」。大家都有的普通特徵不能用，例如說「東京才有的便利商店」就很怪，因為到處都有便利商店。<br>・大多用在稱讚。偶爾會看到「<span class='gd-jp'>都会ならではの悩み</span>」（都市才有的煩惱）這種中性說法，但拿來講單純的缺點、失敗，聽起來會很奇怪。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'><b>らしい</b>＝很有～的感覺、很像～（別的地方也可能有類似的）：<br><span class='gd-jp'>京都らしい景色だ。</span>（很有京都味的景色）<br><b>ならでは</b>＝只有那裡才有，別處找不到：<br><span class='gd-jp'>京都ならではの景色だ。</span>（只有在京都才看得到的景色）</div><div class='gd-sec'><b>をおいて</b>＝講<b>人選</b>，除了他沒有別人可以選：<br><span class='gd-jp'>この役ができるのは、彼をおいてほかにいない。</span>（能演這個角色的，除了他沒有別人）<br><b>ならでは</b>＝講<b>特色</b>，這種東西只有他做得出來：<br><span class='gd-jp'>この演技は彼ならではだ。</span>（這種演技只有他演得出來）</div><div class='gd-warn'>判斷小訣竅：「很像～」用らしい；「只有～才有的特色」用ならでは；「要選的話只有他」用をおいてほかにない。</div>",
  "n1-33": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜とはいうものの」就是中文的<b>「說是這樣說沒錯啦，可是…」</b>。前面先承認一件事是真的，後面再補一句：實際情況沒有照那樣走。像「雖說已經是春天了，但還是好冷」就是這個感覺。<br>拆開就好記：<span class='gd-jp'>と</span>（這樣）＋<span class='gd-jp'>いう</span>（說）＋<span class='gd-jp'>ものの</span>（雖然），合起來是「雖然說是～」。</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>放在句子中間</span>A とはいうものの、B。A 是事實，或大家都這麼說；B 是「照理說應該這樣，結果卻不是」。</div><div class='gd-ex-line'>・<span class='gd-jp'>春とはいうものの、まだ寒い日が続いている。</span>（雖說已經是春天了，還是一直很冷）</div><div class='gd-ex-line'>・<span class='gd-jp'>日本に十年住んでいるとはいうものの、敬語はまだ苦手だ。</span>（雖說在日本住了十年，敬語還是不太行）</div><div class='gd-ex-line'>・<span class='gd-jp'>便利になったとはいうものの、失われたものも少なくない。</span>（雖然變方便了，但失去的東西也不少）</div><div class='gd-sec'><span class='gd-tag'>放在句子開頭</span>前一句已經講完，下一句用「<span class='gd-jp'>とはいうものの</span>、」開頭，就是「話雖如此，…」。</div><div class='gd-ex-line'>・<span class='gd-jp'>今月から節約すると決めた。とはいうものの、コンビニに行くとつい買ってしまう。</span>（我決定這個月開始省錢。話雖如此，一進便利商店還是忍不住買）</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>前面用普通形，也就是不加です・ます的說法。<br>動詞：<span class='gd-pair'><span class='gd-jp'>習った</span> → <span class='gd-jp'>習ったとはいうものの</span></span><br>い形容詞：<span class='gd-pair'><span class='gd-jp'>安い</span> → <span class='gd-jp'>安いとはいうものの</span></span><br>な形容詞：<span class='gd-pair'><span class='gd-jp'>便利だ</span> → <span class='gd-jp'>便利だとはいうものの</span></span>，だ也可以拿掉：<span class='gd-jp'>便利とはいうものの</span><br>名詞：<span class='gd-pair'><span class='gd-jp'>春だ</span> → <span class='gd-jp'>春とはいうものの</span></span>，留著だ說<span class='gd-jp'>春だとはいうものの</span>也可以</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・後面一定要接「跟預期不一樣」的事。<span class='gd-jp'>春とはいうものの、暖かい。</span>就很怪，春天本來就暖和，根本沒有轉折。<br>・語氣偏書面、正式，文章、新聞、演講常見。跟朋友聊天說「<span class='gd-jp'>けど</span>」或「<span class='gd-jp'>とはいっても</span>」比較自然，講「とはいうものの」會像在念稿。<br>・後面通常是在描述現實狀況或自己的感受，很少接「請～」「～吧」這種拜託、邀約的話。<br>・<span class='gd-jp'>いう</span>實際念起來是「ゆう」，但寫的時候還是寫いう，不要寫成ゆう。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>同一個情境「雖說是春天，但還是冷」：<br><b>とはいえ</b>（N2）：<span class='gd-jp'>春とはいえ、まだ寒い。</span>意思幾乎一樣，比較短，也一樣偏書面，也能放句首。<br><b>とはいうものの</b>：<span class='gd-jp'>春とはいうものの、まだ寒い。</span>意思跟とはいえ一樣，只是比較長。<br><b>とはいっても</b>：<span class='gd-jp'>春とはいっても、まだ寒いね。</span>嘴巴講話最常用的版本。<br><b>ものの</b>（N2）：<span class='gd-jp'>春になったものの、まだ寒い。</span>直接接一個事實，少了「說是～」那一層。<br><b>とは言い条</b>（N1）：<span class='gd-jp'>春とは言い条、まだ寒い。</span>意思一樣，但非常古典，現在幾乎只在文章裡看到。</div><div class='gd-warn'>判斷小訣竅：講話用「とはいっても」，寫文章用「とはいえ」「とはいうものの」，「とは言い条」看得懂就好，自己不太需要用。</div>",
  "n1-40": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜にひきかえ」很像中文的<b>「反觀～」「相較之下」</b>。先講一邊，再講完全相反的另一邊，而且通常一邊好、一邊不好，說話的人心裡有感覺。比如「人家哥哥那麼認真，<b>反觀</b>弟弟……」。</div><div class='gd-h'>怎麼接</div><div class='gd-sec'><b>名詞</b>直接接：<span class='gd-pair'><span class='gd-jp'>去年</span> → <span class='gd-jp'>去年にひきかえ</span></span><br><b>一句話</b>要先加「の」把它變成名詞，再接にひきかえ：<br><span class='gd-pair'><span class='gd-jp'>兄はよく勉強する</span> → <span class='gd-jp'>兄がよく勉強するのにひきかえ</span></span><br><span class='gd-pair'><span class='gd-jp'>姉は明るい</span> → <span class='gd-jp'>姉が明るいのにひきかえ</span></span><br>「社交的」這種要加な才能接の：<span class='gd-pair'><span class='gd-jp'>社交的</span> → <span class='gd-jp'>社交的なのにひきかえ</span></span></div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>兩邊落差很大</span>拿兩個人、兩個時期、兩個地方來對照，強調差很多。</div><div class='gd-ex-line'>・<span class='gd-jp'>去年の猛暑にひきかえ、今年の夏は過ごしやすい。</span>（跟去年的酷暑比起來，今年夏天舒服多了）</div><div class='gd-ex-line'>・<span class='gd-jp'>前の部長にひきかえ、今度の部長はとても話しやすい。</span>（跟之前的部長比起來，這次的部長好溝通多了）</div><div class='gd-ex-line'>・<span class='gd-jp'>兄が社交的なのにひきかえ、弟は人見知りだ。</span>（哥哥很外向，反觀弟弟卻很怕生）</div><div class='gd-sec'><span class='gd-tag'>それにひきかえ</span>放在句子開頭，意思是「反觀～」。前面先講別人多好，後面接自己或自家人，常帶抱怨或自嘲。</div><div class='gd-ex-line'>・<span class='gd-jp'>隣の子は毎日勉強している。それにひきかえ、うちの子はゲームばかりだ。</span>（隔壁的小孩每天都在念書。反觀我家小孩，整天只會打電動）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・接句子時中間的「の」不能少：要說<span class='gd-jp'>社交的なのにひきかえ</span>，不能說社交的にひきかえ。這裡的「のに」是「の＋に」，不是「明明～卻」的のに。<br>・它帶著說話者的評價，<b>不適合拿來比純數據</b>。像「男性占三成，女性占五成」這種只是陳述數字的句子，用にひきかえ會很怪。<br>・語氣偏書面、偏正式。日常聊天比較常聽到的是句首的<span class='gd-jp'>それにひきかえ</span>。<br>・別跟<span class='gd-jp'>〜と引き換えに</span>搞混，那是「用～交換」：<span class='gd-jp'>代金と引き換えに商品を渡す。</span>（一手交錢一手交貨）。意思完全不同。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>同樣講哥哥外向、弟弟內向：<br><b>に対して</b>＝客觀列出兩邊不一樣，沒有情緒：<span class='gd-jp'>兄は社交的なのに対して、弟は内向的だ。</span>（哥哥外向，弟弟則內向）<br><b>にひきかえ</b>＝帶著「怎麼差這麼多」的感慨或不滿：<span class='gd-jp'>兄が社交的なのにひきかえ、弟は内向的だ。</span>（哥哥那麼外向，反觀弟弟卻這麼內向）<br><b>に比べて</b>＝單純比程度高低：<span class='gd-jp'>去年に比べて、今年は暑い。</span>（今年比去年熱）</div><div class='gd-warn'>判斷小訣竅：心裡有「反觀～」「人家都…你卻…」的感覺，用にひきかえ；只是客觀說兩邊不同，用に対して；只是比誰多誰少，用に比べて。</div>",
  "n1-2": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜をもって」就是中文公文裡的<b>「以～」</b>。一個意思是<b>「用～來做」</b>（以書面通知、以誠意處理），另一個意思是<b>「以～為界線」</b>（以本日為限、到今天為止）。你在公告、通知信、典禮主持人嘴裡最常看到它，平常聊天幾乎不會用。</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>名詞直接放在前面，再加をもって：<span class='gd-pair'><span class='gd-jp'>書面</span> → <span class='gd-jp'>書面をもって</span></span><br>前面接的多半是正式或抽象的名詞，例如書面、誠意、拍手，或是本日、3月這種時間。<br>講話時想更客氣，會說成<span class='gd-jp'>をもちまして</span>，意思一樣。</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>用什麼方式</span>「用～來做某件事」，像正式場合裡的「で」。</div><div class='gd-ex-line'>・<span class='gd-jp'>合否は書面をもってお知らせします。</span>（錄取與否會以書面通知）</div><div class='gd-ex-line'>・<span class='gd-jp'>誠意をもって対応いたします。</span>（我們會誠心誠意處理）</div><div class='gd-ex-line'>・<span class='gd-jp'>盛大な拍手をもってお迎えください。</span>（請以熱烈的掌聲歡迎）</div><div class='gd-sec'><span class='gd-tag'>時間的界線</span>以某個時間點為分界，多半是「到這天為止、結束」，也可以是「從這天起生效」。</div><div class='gd-ex-line'>・<span class='gd-jp'>本日をもって、閉店いたします。</span>（本店營業到今天為止）</div><div class='gd-ex-line'>・<span class='gd-jp'>以上をもちまして、本日の会議を終了いたします。</span>（以上，今天的會議到此結束）</div><div class='gd-ex-line'>・<span class='gd-jp'>4月1日をもって、社名を変更いたします。</span>（自 4 月 1 日起更改公司名稱）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・<span class='gd-jp'>本日をもって閉店</span>是說<b>今天還有開，今天是最後一天</b>，不是今天已經不開了。翻成「自本日起結束營業」很容易讓人誤會。<br>・這是很硬的書面說法，日常生活別亂用。跟朋友說「用筆寫」就講<span class='gd-jp'>ペンで書く</span>，講成ペンをもって書く會很怪。<br>・它跟「拿著」的<span class='gd-jp'>持って</span>是不同用法。<span class='gd-jp'>傘を持って出かける</span>是真的手上拿著傘出門；<span class='gd-jp'>書面をもって</span>則是「以書面的方式」，沒有人拿著東西。所以文法用法常寫成平假名。<br>・<span class='gd-jp'>以上をもちまして</span>是活動、典禮收尾的固定說法，聽到這句就知道要結束了。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'><b>で</b>＝日常說法的「用～」：<span class='gd-jp'>結果はメールで知らせるね。</span>（結果我再用 email 跟你說）<br><b>をもって</b>＝正式公告的「以～」：<span class='gd-jp'>結果は書面をもってお知らせします。</span>（結果將以書面通知）<br>兩句意思差不多，差別在場合：一個是跟人隨口說，一個是公司或學校發的正式通知。</div><div class='gd-sec'><b>を限りに</b>也能講「到～為止」，但它強調<b>「這是最後一次，之後不再做」</b>，常帶著個人下定決心的感覺：<span class='gd-jp'>今日を限りにタバコをやめる。</span>（從今天起我不再抽菸了）<br><b>をもって</b>比較像機關、公司發的<b>正式公告</b>，而且也能講「從這天起開始生效」，這是を限りに沒有的用法：<span class='gd-jp'>本日をもって受付を締め切ります。</span>（受理到今天截止）</div><div class='gd-warn'>判斷小訣竅：平常講「用～」用で；公告、通知、典禮上的「以～」用をもって；自己下決心「到今天為止不再～」用を限りに。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'><span class='gd-jp'>をもってしても</span>＝「就算用上～也…」，後面接做不到的事：<span class='gd-jp'>最新の技術をもってしても、完全には防げない。</span>（就算用上最新技術，也無法完全防止）</div>",
  "n1-3": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜をものともせず」就是中文的<b>「不畏～」「不把～放在眼裡」</b>。前面放困難、危險、阻礙，後面接「結果還是做到了」，用來稱讚一個人很勇敢、很拚。新聞報導「不畏風雨，堅守崗位」那種語氣，就是它。</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>名詞＋<span class='gd-jp'>をものともせず</span>（後面也可以多一個に：<span class='gd-jp'>をものともせずに</span>，意思一樣）<br><span class='gd-pair'><span class='gd-jp'>病気</span> → <span class='gd-jp'>病気をものともせず</span></span>（不畏疾病）<br><span class='gd-pair'><span class='gd-jp'>周囲の反対</span> → <span class='gd-jp'>周囲の反対をものともせず</span></span>（不畏周遭反對）<br>拆開來看，<span class='gd-jp'>もの</span>是「東西」，<span class='gd-jp'>せず</span>是「不做」，字面上就是「連當成一回事都不當」。</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>前面放困難</span>病痛、受傷、壞天氣、危險、失敗、反對、壓力這類「擋在前面的東西」。</div><div class='gd-ex-line'>・<span class='gd-jp'>彼は度重なる失敗をものともせず、挑戦し続けた。</span>（他不畏一再的失敗，持續挑戰）</div><div class='gd-ex-line'>・<span class='gd-jp'>救助隊は激しい雨をものともせず、山へ向かった。</span>（救難隊不畏大雨，朝山上出發）</div><div class='gd-sec'><span class='gd-tag'>後面放做到的事</span>通常是已經發生的事實，帶有佩服、讚賞的口氣。</div><div class='gd-ex-line'>・<span class='gd-jp'>彼女は周囲の反対をものともせず、自分の店を開いた。</span>（她不顧周遭反對，開了自己的店）</div><div class='gd-ex-line'>・<span class='gd-jp'>その選手は怪我をものともせず、最後まで走り抜いた。</span>（那位選手不畏傷痛，跑完全程）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・它是在<b>稱讚別人</b>，一般不拿來講自己。<span class='gd-jp'>私は寒さをものともせず</span>聽起來像在自誇，很怪。<br>・後面不接「請你～」「我們～吧」。像「不畏困難，加油吧」這種話，不要用它來講，它是拿來<b>描述已經做到的事</b>。<br>・前面一定要是<b>阻礙</b>。「應援」「機會」這種好東西不能放，因為沒有東西可以「不畏」。<br>・助詞是<b>を</b>，不是が。<br>・這是書面、新聞、演講用的硬詞，跟朋友聊天幾乎不會講。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'><b>をよそに</b>＝<b>不管別人的擔心或期待</b>，自顧自去做。前面常放<span class='gd-jp'>心配</span>、<span class='gd-jp'>期待</span>，帶點「不聽勸」的感覺。<br>・<span class='gd-jp'>親の心配をよそに、彼は一人で海外へ行った。</span>（他不管父母的擔心，自己一個人出國了）<br><b>をものともせず</b>＝<b>不怕困難</b>，勇敢撐過去，是稱讚。<br>・<span class='gd-jp'>言葉の壁をものともせず、彼は海外で成功した。</span>（他不畏語言障礙，在國外成功了）<br>「父母的擔心」不是要克服的難關，所以說成<span class='gd-jp'>親の心配をものともせず</span>就不自然。</div><div class='gd-sec'><b>にもかかわらず</b>＝單純的「儘管～還是～」，不帶褒貶，好事壞事都能用。<br>・<span class='gd-jp'>雨にもかかわらず、たくさんの人が来た。</span>（儘管下雨，還是來了很多人）<br>如果想強調「這些人很了不起」，才換成<span class='gd-jp'>雨をものともせず</span>。</div><div class='gd-warn'>判斷小訣竅：前面是「難關」，而且你想誇對方勇敢，就用をものともせず；前面是「別人的心情」，對方不理會，就用をよそに；只是單純說「儘管」，用にもかかわらず。</div>",
  "n1-9": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「AはおろかB」就是中文的<b>「別說A了，連B都～」</b>。A 是「本來就理所當然」的那件事，提都懶得提；B 是更出乎意料的那件事，用來強調「狀況誇張到這種地步」。而且順序跟中文一樣，直接照中文的語序套就好。</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>基本是<b>名詞＋はおろか</b>：<span class='gd-pair'><span class='gd-jp'>漢字</span> → <span class='gd-jp'>漢字はおろか</span></span><br>如果 A 是動作，先在動詞後面加「こと」把它變成名詞：<span class='gd-pair'><span class='gd-jp'>走る</span> → <span class='gd-jp'>走ることはおろか</span></span><br>後半句通常會配<b>も、さえ、すら、まで</b>，這些字就是中文的「連～都」。</div><div class='gd-h'>A 和 B 怎麼排</div><div class='gd-sec'>判斷方法：A 放「這件事本來就理所當然」的，B 放更極端、更讓人意外的。</div><div class='gd-sec'><span class='gd-tag'>否定句（最常見）</span>A 是比較難的，B 是比較基本的。「難的不會很正常，但連簡單的都不會」才有強調效果。</div><div class='gd-ex-line'>・<span class='gd-jp'>漢字はおろか、ひらがなさえまだ読めない。</span>（別說漢字了，連平假名都還不會讀）</div><div class='gd-ex-line'>・<span class='gd-jp'>忙しくて、休みはおろか、昼ご飯を食べる時間もない。</span>（忙到別說休假了，連吃午餐的時間都沒有）</div><div class='gd-ex-line'>・<span class='gd-jp'>足をけがして、走ることはおろか、歩くこともできない。</span>（腳受傷了，別說跑步，連走路都沒辦法）</div><div class='gd-sec'><span class='gd-tag'>正面句</span>反過來，A 是比較普通的，B 是範圍更大、更厲害的。</div><div class='gd-ex-line'>・<span class='gd-jp'>この歌は国内はおろか、海外でも人気がある。</span>（這首歌別說國內了，連國外都很紅）</div><div class='gd-warn'>順序不要放反：<span class='gd-jp'>ひらがなはおろか、漢字も読めない。</span>就不合邏輯了。連平假名都不會的人，不會漢字本來就很正常，根本不用拿出來強調。<br>不管是否定句還是正面句都一樣：A 是「本來就這樣」，B 是「連這個都這樣」。</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・後半句<b>不能放命令、請求、自己的打算</b>。<span class='gd-jp'>漢字はおろか、ひらがなも覚えなさい。</span>是錯的，這時要改用<span class='gd-jp'>はもちろん</span>。<br>・は已經在裡面了，前面不要再多加を或が。也不能直接接動詞，要記得先加「こと」。<br>・這裡的おろか跟「愚か」（愚蠢）沒有關係，不要理解成「笨」。<br>・語氣偏硬，常帶「真是誇張」「太慘了」的不滿或驚訝，多用在書面或比較正式的場合。跟朋友聊天，日本人比較常講<span class='gd-jp'>どころか</span>。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>同一個情境比較看看：<br><b>はおろか</b>＝帶著感嘆或不滿強調「連B都」，後半句只能是陳述：<span class='gd-jp'>漢字はおろか、ひらがなも書けない。</span>（別說漢字，連平假名都不會寫）<br><b>はもちろん</b>＝單純的「A當然，B也」，語氣中性，後面可以接請求：<span class='gd-jp'>漢字はもちろん、ひらがなもちゃんと書いてください。</span>（漢字當然要寫好，平假名也請好好寫）<br><b>どころか</b>＝意思跟はおろか接近，比較口語。它另外還能表示「不但不A，反而B」：<span class='gd-jp'>安いどころか、すごく高かった。</span>（不但不便宜，反而貴得要命）。はおろか沒有這個「反而」的用法。</div><div class='gd-warn'>判斷小訣竅：要叫別人做事就用はもちろん；跟朋友講話就用どころか；寫文章、想加強「誇張到連這個都」的感嘆，就用はおろか。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>後半句常搭配的<span class='gd-jp'>すら</span>（連～都），可以接著學。</div>",
  "n1-10": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜ないまでも」就是中文的<b>「就算沒到～那麼好，起碼也要～」</b>。先把高標準放下（滿分、每天、像母語者那樣），再說一個<b>退一步、最低限度</b>的目標。就像你跟自己說「不求每天運動，至少一週動一次」，就是這種口氣。</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>動詞ない形＋までも。前半段放「高標準」，後半段放「至少要做到的程度」。<br><span class='gd-pair'><span class='gd-jp'>取れない</span> → <span class='gd-jp'>取れないまでも</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>ネイティブのようには話せないまでも、日常会話はこなしたい。</span>（就算沒辦法講得像母語者，至少想應付得了日常會話）</div><div class='gd-sec'>實際上更常見的是下面兩個固定組合，前面直接放名詞，建議整組背起來：</div><div class='gd-sec'><span class='gd-tag'>とは言わないまでも</span>「不要求到～的程度」，常用來講希望、要求。</div><div class='gd-ex-line'>・<span class='gd-jp'>毎日とは言わないまでも、週に一度は運動したい。</span>（不說每天，至少想一週運動一次）</div><div class='gd-sec'><span class='gd-tag'>とはいかないまでも</span>「雖然沒達到～」，常拿來講已經有的結果。</div><div class='gd-ex-line'>・<span class='gd-jp'>満点とはいかないまでも、合格点は取れた。</span>（雖然沒拿到滿分，至少有及格）</div><div class='gd-h'>後半段長什麼樣子</div><div class='gd-sec'>後半段通常是「想～」「應該～」「希望對方～」，或是已經做到的結果。而且常搭配<b>「は」「くらいは」「せめて」</b>，強調「至少這個」。</div><div class='gd-ex-line'>・<span class='gd-jp'>謝罪とは言わないまでも、せめて一言説明してほしい。</span>（不要求道歉，至少也解釋一句吧）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・前後要是<b>同一把尺上的高低</b>：滿分對及格、每天對一週一次。前面高、後面低。後面比前面還高，或兩件事根本不相關，就不能用。<br>・後半段是<b>肯定</b>的「至少有做到／想做到」。如果要說「連低標都沒做到」，要換別的句型（看下面的はおろか）。<br>・別跟「〜までもない」搞混：<span class='gd-jp'>言うまでもない</span>是「不用說也知道」，前面接辭書形，意思是「沒必要做」；<span class='gd-jp'>言わないまでも</span>是「雖然不說到那個地步」。差一個ない，意思完全不一樣。<br>・整體偏書面、正式的感覺，不過「とは言わないまでも」在日常對話裡也蠻常聽到。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>最容易混的是<b>〜はおろか</b>，兩個都是「高標準沒做到」，但後面的方向相反。同樣講考試：<br><span class='gd-jp'>満点とはいかないまでも、合格点は取れた。</span>（雖然不到滿分，至少有及格）→ 低標<b>有做到</b>，往好的方向收尾。<br><span class='gd-jp'>満点はおろか、合格点も取れなかった。</span>（別說滿分了，連及格都沒拿到）→ 連低標都<b>沒做到</b>，往壞的方向強調。</div><div class='gd-warn'>判斷小訣竅：「高的沒有，<b>但低的有</b>」用ないまでも；「高的沒有，<b>連低的也沒有</b>」用はおろか。</div>",
  "n1-22": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜べく」就是<b>「為了～」</b>，但它是書面、正式的說法，感覺很像中文新聞或公文裡的「為求～」「以期～」。意思跟「ために」差不多，只是更硬、更正式，平常聊天幾乎不會講。</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>新聞・報導</span>交代某人為了什麼目的採取了行動。</div><div class='gd-ex-line'>・<span class='gd-jp'>真相を確かめるべく、記者は現地へ向かった。</span>（為了查明真相，記者前往當地）</div><div class='gd-ex-line'>・<span class='gd-jp'>試験に合格すべく、毎日10時間勉強した。</span>（為了考上，每天唸 10 小時書）</div><div class='gd-sec'><span class='gd-tag'>正式場合表決心</span>致詞、記者會、公司公告裡說「為了～我們會努力」。</div><div class='gd-ex-line'>・<span class='gd-jp'>皆様のご期待に応えるべく、全力を尽くします。</span>（為了不辜負各位的期待，我們會全力以赴）</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>動詞的<b>辭書形</b>（字典上查到的原形）直接加「べく」：<br><span class='gd-pair'><span class='gd-jp'>確かめる</span> → <span class='gd-jp'>確かめるべく</span></span><br><span class='gd-pair'><span class='gd-jp'>なる</span> → <span class='gd-jp'>なるべく</span></span><br><span class='gd-pair'><span class='gd-jp'>応える</span> → <span class='gd-jp'>応えるべく</span></span></div><div class='gd-sec'><b>する</b>比較特別，兩種都可以，<b>すべく</b>更常見：<br><span class='gd-pair'><span class='gd-jp'>達成する</span> → <span class='gd-jp'>達成すべく</span></span>（也可以說<span class='gd-jp'>達成するべく</span>）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・前面<b>不能接否定</b>：沒有「遅刻しないべく」這種說法。要說「為了不～」請用<span class='gd-jp'>遅刻しないように</span>。<br>・後面<b>不能接請對方做事</b>（請求、命令、邀約）：<span class='gd-jp'>合格すべく、毎日勉強してください</span>是錯的，要改成<span class='gd-jp'>合格するために、毎日勉強してください</span>。<br>・<b>名詞不能直接接</b>：可以說<span class='gd-jp'>健康のために</span>，但沒有「健康のべく」。要用べく就得接動詞：<span class='gd-jp'>健康を維持すべく</span>。<br>・前後通常是<b>同一個人</b>、而且是<b>有意圖去做</b>的事。像「下雨」這種人控制不了的事，不能放在べく前面。<br>・小心跟副詞<span class='gd-jp'>なるべく</span>（盡量）撞字：<span class='gd-jp'>なるべく早く来てください</span>是「請盡量早點來」；<span class='gd-jp'>医者になるべく</span>才是「為了成為醫生」。看前面有沒有接東西就分得出來。<br>・跟朋友聊天說「〜べく」會很像在念公文，口語請用ために。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>同樣是「為了考上而努力」：<br><b>ために</b>＝一般說法，講話寫字都能用：<span class='gd-jp'>合格するために、毎日勉強している。</span>（為了考上，每天都在唸書）<br><b>べく</b>＝書面、正式：<span class='gd-jp'>合格すべく、毎日勉強した。</span>（為求考上，每天苦讀）<br><b>んがため（に）</b>＝更古、更硬，帶有「拚了命也要」的強烈感覺，接法也不同（<span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>せんがため</span></span>）：<span class='gd-jp'>合格せんがため、寝る間も惜しんで勉強した。</span>（為了考上，連睡覺時間都捨不得，拚命唸書）</div><div class='gd-warn'>判斷小訣竅：平常用ために；新聞、演講、正式文章用べく；要強調「無論如何都要達成」才用んがため。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>・<span class='gd-jp'>べくして</span>：「本來就注定會～」，意思跟「為了」不同。<span class='gd-jp'>起こるべくして起こった事故だ。</span>（這是遲早會發生的事故）<br>・同一家族的<span class='gd-jp'>べき</span>（應該）、<span class='gd-jp'>べからず</span>（不可以），意思都不是「為了」，不要混在一起。</div>",
  "n1-23": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜ゆえ（に）」就是中文書面語的<b>「由於～」「因～之故」</b>。意思跟「から」「ので」一樣是「因為」，只是穿上了西裝、說話文謅謅。新聞評論、小說、演講稿裡常看到，朋友聊天幾乎不會講。</div><div class='gd-h'>怎麼接</div><div class='gd-sec'><span class='gd-tag'>名詞</span>最常見的是直接接，中間也可以加「の」。<br><span class='gd-pair'><span class='gd-jp'>若さ</span> → <span class='gd-jp'>若さゆえ</span></span><span class='gd-pair'><span class='gd-jp'>貧しさ</span> → <span class='gd-jp'>貧しさのゆえに</span></span></div><div class='gd-sec'><span class='gd-tag'>動詞・い形容詞</span>用一般的普通形（就是字典上那種不加ます的說法），後面接「がゆえ」或「ゆえ」都可以，「がゆえ」語氣更硬。<br><span class='gd-pair'><span class='gd-jp'>人気がある</span> → <span class='gd-jp'>人気があるがゆえに</span></span><span class='gd-pair'><span class='gd-jp'>若い</span> → <span class='gd-jp'>若いがゆえに</span></span></div><div class='gd-sec'><span class='gd-tag'>な形容詞・名詞當句子</span>把「だ」換成<b>である</b>再接。<br><span class='gd-pair'><span class='gd-jp'>真面目だ</span> → <span class='gd-jp'>真面目であるがゆえに</span></span><span class='gd-pair'><span class='gd-jp'>学生だ</span> → <span class='gd-jp'>学生であるがゆえに</span></span></div><div class='gd-h'>最常看到的樣子</div><div class='gd-sec'><span class='gd-tag'>ゆえに、〜</span>後面接一整句結果。</div><div class='gd-ex-line'>・<span class='gd-jp'>人気があるがゆえに、予約がなかなか取れない。</span>（由於太受歡迎，一直訂不到位）</div><div class='gd-ex-line'>・<span class='gd-jp'>責任ある立場ゆえに、軽率な発言は許されない。</span>（因為身居要職，不能隨便發言）</div><div class='gd-sec'><span class='gd-tag'>ゆえの＋名詞</span>直接修飾後面的名詞，「因～而來的…」。</div><div class='gd-ex-line'>・<span class='gd-jp'>経験不足ゆえの失敗だった。</span>（那是經驗不足造成的失敗）</div><div class='gd-ex-line'>・<span class='gd-jp'>優しさゆえの嘘もある。</span>（也有出於溫柔而說的謊）</div><div class='gd-sec'><span class='gd-tag'>句首的ゆえに</span>單獨放在句子開頭，就是「所以、因此」，數學證明、哲學論述很常見。</div><div class='gd-ex-line'>・<span class='gd-jp'>我思う、ゆえに我あり。</span>（我思，故我在）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・名詞和な形容詞<b>不能接「だ」</b>：不是「学生だがゆえに」，要說<span class='gd-jp'>学生であるがゆえに</span>。<br>・日常對話用它會很像在演古裝劇或念台詞。跟朋友講「因為很忙」，說<span class='gd-jp'>忙しいから</span>就好，說「忙しいがゆえに」會讓人笑出來。<br>・漢字寫成「故」，看到<span class='gd-jp'>若さ故に</span>不要以為是別的文法，一樣念ゆえに。<br>・後面常接比較負面、或「反而～」的結果，帶點「就是因為這個特點才會這樣」的感慨，例如<span class='gd-jp'>真面目であるがゆえに、かえって批判されることもある。</span>（正因為認真，有時反而被批評）</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'><b>から／ので</b>＝一般的「因為」，口語書面都能用：<span class='gd-jp'>子どもを愛しているから、厳しくする。</span>（因為愛孩子，所以嚴格）<br><b>がゆえに</b>＝同樣的意思，換成文章腔，客觀陳述原因：<span class='gd-jp'>子どもを愛するがゆえに、厳しくする。</span>（由於愛孩子，所以對他嚴格）<br><b>ばこそ</b>＝強烈強調「<b>正是</b>因為這個，不是別的」，常是說話者在替自己的作法辯護，句尾常接のだ：<span class='gd-jp'>子どもを愛すればこそ、厳しくするのだ。</span>（正是因為愛孩子，才會對他嚴格）</div><div class='gd-warn'>判斷小訣竅：只是換個正式說法講「因為」就用ゆえに；想強調「就是這個理由，你要懂我」就用ばこそ。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>同樣講原因的N1文法還有<span class='gd-jp'>〜とあって</span>（因為是～這種特殊情況），可以跟ゆえに一起比較著記。</div>",
  "n1-27": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜たところで」就是中文的<b>「就算～也沒用」「～了又怎樣」</b>。像台灣人講「現在哭有什麼用」「你再怎麼解釋他也不會信」，語氣有點看破、有點潑冷水：前面那件事做了也白做。</div><div class='gd-ex-line'>・<span class='gd-jp'>今さら謝ったところで、関係は戻らないだろう。</span>（事到如今就算道歉，關係也回不去了吧）</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>先把動詞變成た形（過去式那個形），後面直接加「ところで」。<br><b>第一類（五段動詞）</b>：<br><span class='gd-pair'><span class='gd-jp'>急ぐ</span> → <span class='gd-jp'>急いだ</span> → <span class='gd-jp'>急いだところで</span></span><br><span class='gd-pair'><span class='gd-jp'>言う</span> → <span class='gd-jp'>言った</span> → <span class='gd-jp'>言ったところで</span></span><br><b>第二類（一段動詞）</b>：<br><span class='gd-pair'><span class='gd-jp'>慌てる</span> → <span class='gd-jp'>慌てた</span> → <span class='gd-jp'>慌てたところで</span></span><br><b>第三類（する・来る）</b>：<br><span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>した</span> → <span class='gd-jp'>したところで</span></span><br><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来た</span> → <span class='gd-jp'>来たところで</span></span></div><div class='gd-h'>最常聽到的樣子</div><div class='gd-sec'><span class='gd-tag'>做了也白搭</span>最常見的用法。前面常配「<span class='gd-jp'>いくら</span>」「<span class='gd-jp'>どんなに</span>」「<span class='gd-jp'>今さら</span>」，後面接「～ない」「無駄だ」「仕方がない」這類沒用的結果。</div><div class='gd-ex-line'>・<span class='gd-jp'>どんなに急いだところで、最終便には間に合わない。</span>（再怎麼趕也趕不上末班了）</div><div class='gd-ex-line'>・<span class='gd-jp'>いくら説明したところで、わかってもらえないだろう。</span>（再怎麼解釋，他大概也不會懂）</div><div class='gd-sec'><span class='gd-tag'>頂多也只是～</span>後面接「<span class='gd-jp'>せいぜい</span>」，意思是「就算做了，結果也大不到哪去」。</div><div class='gd-ex-line'>・<span class='gd-jp'>今から急いだところで、せいぜい5分早く着くくらいだ。</span>（現在趕，頂多也只早到 5 分鐘）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・雖然用た形，講的是<b>假設</b>，不是已經發生的事。「謝ったところで」是「就算（去）道歉」，不是「道歉了」。<br>・後面要接沒用、不怎麼樣的結果。想說「努力的話就考得上」這種好結果，不能說頑張ったところで合格できる，要用<span class='gd-jp'>頑張れば合格できる</span>。<br>・後面是你自己的判斷或推測，常以「～だろう」「～わけではない」收尾，不會接「～てください」這種請別人做事的話。<br>・同樣的「たところで」還有一個意思是「在～的時候、剛好告一段落時」，後面接下一個動作：<span class='gd-jp'>話が一段落したところで、休憩しましょう。</span>（話題告一段落，休息一下吧）。看後面：是「沒用」就是本篇的意思，是「接著做某事」就是時間點。<br>・語氣帶點冷淡、放棄感，直接對人說「你做了也沒用」會很潑冷水，要看場合。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'><b>ても</b>＝一般的「即使」，中性，後面好結果、壞結果都可以：<span class='gd-jp'>彼に説明しても、わかってもらえないだろう。</span>（跟他解釋，他大概也不會懂）<br><b>たところで</b>＝特別強調「做了也白費」，比ても更死心：<span class='gd-jp'>彼に説明したところで、わかってもらえないだろう。</span>（就算跟他解釋也沒用，他不會懂的）<br><b>ようと</b>＝「不管～，我照樣～」，重點在後面不受影響，可以接自己的決心：<span class='gd-jp'>みんなが反対しようと、私はこの計画を進める。</span>（不管大家怎麼反對，我都要推動這個計畫）<br>同樣講反對，用たところで就變成：<span class='gd-jp'>みんなが反対したところで、社長の考えは変わらない。</span>（大家就算反對也沒用，社長的想法不會變）</div><div class='gd-warn'>判斷小訣竅：想說「做了也白搭」用たところで；想說「不管怎樣我都要做」用ようと；只是一般的「即使」就用ても。</div>",
  "n1-28": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜ようが／〜ようと」就是<b>「管他～，我照樣…」</b>。前面不管發生什麼、別人怎麼樣，後面的結論都不會變。語氣比一般的「〜ても」<b>硬、強烈</b>，有一種「我說了算、沒在怕」的態度。</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>配疑問詞</span>前面放「何・どこ・誰・どんなに・いくら」，意思是「不管什麼／哪裡／誰／多麼～」。</div><div class='gd-ex-line'>・<span class='gd-jp'>何を言われようが、気にしない。</span>（不管被說什麼，我都不在意）</div><div class='gd-ex-line'>・<span class='gd-jp'>どこへ行こうと、あなたの自由です。</span>（你要去哪裡，都是你的自由）</div><div class='gd-ex-line'>・<span class='gd-jp'>誰が反対しようと、私はやる。</span>（不管誰反對，我都要做）</div><div class='gd-sec'><span class='gd-tag'>單獨用</span>沒有疑問詞時，就是「就算～也照樣…」。</div><div class='gd-ex-line'>・<span class='gd-jp'>雨が降ろうが行く。</span>（就算下雨，我也照樣要去）</div><div class='gd-sec'><span class='gd-tag'>兩個並排</span>「AようがBようが」＝不管A還是B；「Aようが Aまいが」＝不管做不做。這裡的「まい」是「不～」的意思，第一類（五段動詞）接辭書形：<span class='gd-jp'>行くまい</span>；<span class='gd-jp'>する</span>常說成<span class='gd-jp'>しまい</span>。</div><div class='gd-ex-line'>・<span class='gd-jp'>雨が降ろうが風が吹こうが、試合は行われる。</span>（不管颳風下雨，比賽都照常舉行）</div><div class='gd-ex-line'>・<span class='gd-jp'>参加しようがしまいが、あなたの自由だ。</span>（要不要參加，隨你）</div><div class='gd-sec'>後面很常接「<span class='gd-jp'>自由だ</span>」「<span class='gd-jp'>関係ない</span>」「<span class='gd-jp'>構わない</span>」「<span class='gd-jp'>気にしない</span>」，或是「我就是要做」的決心。</div><div class='gd-h'>怎麼接</div><div class='gd-sec'><b>動詞</b>：先變成意向形（就是「行こう」「食べよう」那個形），再加が或と。<br>第一類（五段動詞）：<span class='gd-pair'><span class='gd-jp'>行く</span> → く換成こ → <span class='gd-jp'>行こうが</span></span><span class='gd-pair'><span class='gd-jp'>言う</span> → <span class='gd-jp'>言おうが</span></span><br>第二類（一段動詞）：把る拿掉加よう　<span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べようが</span></span>，被動的<span class='gd-pair'><span class='gd-jp'>言われる</span> → <span class='gd-jp'>言われようが</span></span>也是這樣變<br>第三類（する・来る）：<span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>しようが</span></span><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来ようが</span></span></div><div class='gd-sec'><b>い形容詞</b>：把最後的「い」拿掉，加「かろう」。<br><span class='gd-pair'><span class='gd-jp'>暑い</span> → <span class='gd-jp'>暑かろうが</span></span><span class='gd-pair'><span class='gd-jp'>高い</span> → <span class='gd-jp'>高かろうと</span></span><br>「いい」要用「よい」來變化：<span class='gd-pair'><span class='gd-jp'>いい</span> → <span class='gd-jp'>よかろうが</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>どんなに暑かろうと、毎朝のランニングは欠かさない。</span>（不管多熱，每天早上的慢跑都不會停）</div><div class='gd-sec'><b>な形容詞・名詞</b>：加「だろう」或比較正式的「であろう」。<br><span class='gd-pair'><span class='gd-jp'>不便だ</span> → <span class='gd-jp'>不便だろうが</span></span><span class='gd-pair'><span class='gd-jp'>子ども</span> → <span class='gd-jp'>子どもであろうと</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>相手が子どもだろうが、ルールはルールだ。</span>（就算對方是小孩，規則就是規則）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・這裡的意向形<b>沒有</b>「～吧」「揪人」的意思，只是借它的樣子來表示「不管」。<br>・第一類不能直接接：是<span class='gd-jp'>行こうが</span>，不是「行くようが」。<br>・<span class='gd-jp'>来ようが</span>要念「こようが」，不是「きようが」。<br>・<span class='gd-jp'>降ろうが</span>只是「就算下雨」；要講「下不下雨都…」得說<span class='gd-jp'>降ろうが降るまいが</span>。<br>・「ようが」和「ようと」意思基本上一樣，可以互換。<br>・語氣很硬、很強勢，平常聊天說「<span class='gd-jp'>暑くても</span>」比較自然；「<span class='gd-jp'>暑かろうが</span>」這種かろう形偏書面或強調時用。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>同一個情境：再怎麼趕。<br><b>ても</b>＝一般的「就算～也」，最中性：<span class='gd-jp'>いくら急いでも、間に合わない。</span>（再怎麼趕也來不及）<br><b>ようが</b>＝後面是「我照樣／都沒差」，帶強烈態度：<span class='gd-jp'>いくら急がされようが、手は抜かない。</span>（不管怎麼被催，我都不會偷工減料）<br><b>たところで</b>＝後面是「也沒用、結果不會好」：<span class='gd-jp'>いくら急いだところで、もう間に合わない。</span>（就算再怎麼趕，也已經來不及了）</div><div class='gd-sec'>另外，名詞也可以用「<b>であれ</b>」表達一樣的「不管是～」：<span class='gd-jp'>理由が何であれ、遅刻はだめだ。</span>和<span class='gd-jp'>理由が何であろうと、遅刻はだめだ。</span>意思幾乎一樣（不管理由是什麼，遲到就是不行）。</div><div class='gd-warn'>判斷小訣竅：後面是「我照樣做／隨便你／沒關係」就用ようが；後面是「做了也沒用」就用たところで；日常口語、不想講得那麼衝，就用ても。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>同樣是「不管A還是B」，可以接著看「<span class='gd-jp'>〜にせよ〜にせよ</span>」：<span class='gd-jp'>行くにせよ行かないにせよ、連絡してください。</span>（不管去不去，都請聯絡我）</div>",
  "n1-29": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「AにせよBにせよ」就是中文的<b>「不管是A還是B，都～」</b>。先丟出兩種可能，再告訴你：哪一種都一樣，結論不會變。語氣比較正式，常出現在文章、新聞、開會發言裡。</div><div class='gd-h'>怎麼接</div><div class='gd-sec'><b>動詞、い形容詞</b>：直接接普通形（就是不加ます、です的說法）。<br><span class='gd-pair'><span class='gd-jp'>行く</span> → <span class='gd-jp'>行くにせよ行かないにせよ</span></span><br><span class='gd-pair'><span class='gd-jp'>高い</span> → <span class='gd-jp'>高いにせよ安いにせよ</span></span></div><div class='gd-sec'><b>名詞、な形容詞</b>：直接接，現在式<b>不要加だ</b>。正式一點可以加「である」。<br><span class='gd-pair'><span class='gd-jp'>大人</span> → <span class='gd-jp'>大人にせよ子どもにせよ</span></span><br><span class='gd-pair'><span class='gd-jp'>好き</span> → <span class='gd-jp'>好きにせよ嫌いにせよ</span></span><br><span class='gd-pair'><span class='gd-jp'>学生</span> → <span class='gd-jp'>学生であるにせよ</span></span></div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>一組相反的</span>去／不去、贊成／反對，哪邊都一樣。</div><div class='gd-ex-line'>・<span class='gd-jp'>行くにせよ行かないにせよ、早めに連絡してください。</span>（不管去不去，都請早點聯絡）</div><div class='gd-ex-line'>・<span class='gd-jp'>好きにせよ嫌いにせよ、この仕事は誰かがやらなければならない。</span>（不管喜不喜歡，這份工作總得有人做）</div><div class='gd-sec'><span class='gd-tag'>兩個同類的</span>舉兩個例子，代表「這一類都一樣」。</div><div class='gd-ex-line'>・<span class='gd-jp'>大人にせよ子どもにせよ、ルールは守らなければならない。</span>（不管大人還是小孩，都得遵守規則）</div><div class='gd-sec'>後半句通常是「應該～」「都得～」「沒有差別」這種<b>兩邊都成立</b>的判斷。</div><div class='gd-h'>最常聽到的樣子</div><div class='gd-sec'><span class='gd-tag'>固定說法</span>不舉例，直接用一個詞包山包海，口語、書面都超常見。</div><div class='gd-ex-line'>・<span class='gd-jp'>いずれにせよ、結果が出たら連絡します。</span>（不管怎樣，結果出來我再通知你）</div><div class='gd-ex-line'>・<span class='gd-jp'>何にせよ、無事でよかった。</span>（總之，平安就好）</div><div class='gd-sec'><span class='gd-tag'>只用一次</span>單獨一個「にせよ」＝「就算～」。</div><div class='gd-ex-line'>・<span class='gd-jp'>冗談にせよ、そんなことを言ってはいけない。</span>（就算是開玩笑，也不能說那種話）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・名詞、な形容詞現在式不加だ：不是学生だにせよ，是<span class='gd-jp'>学生にせよ</span>或<span class='gd-jp'>学生であるにせよ</span>。<br>・「せよ」長得像命令（「去做！」），但在這裡只是固定說法，<b>沒有命令的意思</b>。<br>・後半句一定要對兩種情況都成立。如果結論只適用其中一邊，就不能用。<br>・很書面。跟朋友聊天說<span class='gd-jp'>行っても行かなくても</span>比較自然，講にせよ會有點像在念公文。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'><b>にしろ…にしろ</b>：意思完全一樣，語氣稍微軟一點，口語也還能用。<br><span class='gd-jp'>行くにしろ行かないにしろ、連絡してください。</span>（不管去不去，都請聯絡）<br><b>であれ…であれ</b>：主要接名詞，比にせよ更硬、更正式。<br><span class='gd-jp'>大人であれ子どもであれ、ルールは守るべきだ。</span>（不管大人小孩，都應該守規則）<br><b>ようが…まいが</b>：帶著「隨便你、反正都一樣」的強烈情緒。<br><span class='gd-jp'>行こうが行くまいが、私には関係ない。</span>（你去不去都跟我無關）</div><div class='gd-warn'>判斷小訣竅：平靜地說「不管A還是B」用にせよ／にしろ；只接名詞、要更正式用であれ；帶著「隨便啦、反正不會變」的情緒用ようが。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>「不管內容如何都～」可以學<span class='gd-jp'>いかんにかかわらず</span>：<span class='gd-jp'>理由のいかんにかかわらず、遅刻は認めません。</span>（不管理由是什麼，遲到一律不接受）</div>",
  "n1-30": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜と思いきや」就是中文的<b>「本來以為～，結果竟然…」</b>。前面寫你原本的預期，後面寫實際發生的事，而且結果跟預期<b>完全相反</b>，有一種「被打臉」的意外感。</div><div class='gd-ex-line'>・<span class='gd-jp'>晴れると思いきや、午後から急に雨が降り出した。</span>（本來以為會放晴，結果下午突然下起雨來）</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>前面放<b>普通形</b>（就是沒有ます、です的說法），後面直接加「と思いきや」。<br><span class='gd-pair'><span class='gd-jp'>合格した</span> → <span class='gd-jp'>合格したと思いきや</span></span><br><span class='gd-pair'><span class='gd-jp'>簡単だ</span> → <span class='gd-jp'>簡単だと思いきや</span></span></div><div class='gd-sec'><span class='gd-tag'>かと思いきや</span>中間常常多一個「か」，口氣像「我還以為是不是～」，非常常見。加「か」的時候要注意：<br><b>動詞、い形容詞</b>：直接加か。<br><span class='gd-pair'><span class='gd-jp'>終わった</span> → <span class='gd-jp'>終わったかと思いきや</span></span><span class='gd-pair'><span class='gd-jp'>高い</span> → <span class='gd-jp'>高いかと思いきや</span></span><br><b>名詞、な形容詞</b>：先把「だ」拿掉，再加か。<br><span class='gd-pair'><span class='gd-jp'>簡単だ</span> → だ拿掉 → <span class='gd-jp'>簡単かと思いきや</span></span><span class='gd-pair'><span class='gd-jp'>雨だ</span> → だ拿掉 → <span class='gd-jp'>雨かと思いきや</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>もう帰ったかと思いきや、まだ会社にいた。</span>（還以為他已經回去了，結果還在公司）</div><div class='gd-ex-line'>・<span class='gd-jp'>高いかと思いきや、意外と安かった。</span>（還以為很貴，沒想到挺便宜的）</div><div class='gd-ex-line'>・<span class='gd-jp'>彼は怒るかと思いきや、笑って許してくれた。</span>（本來以為他會生氣，結果他笑著原諒我了）</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'>多半出現在文章、新聞、電視旁白、社群貼文這種「講故事」的場合，帶一點驚訝或好笑的感覺。網路上甚至會只寫「〜と思いきや…」就停住，故意吊胃口，等下一句揭曉。</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・名詞、な形容詞加か時，<b>不能留著だ</b>：是<span class='gd-jp'>簡単かと思いきや</span>，不是「簡単だかと思いきや」。<br>・「思いきや」是固定的一整塊，<b>不能變形</b>，不會有「思いましたきや」這種說法。<br>・念<b>おもいきや</b>，別跟<span class='gd-jp'>思い切り</span>（用力地、盡情地）、<span class='gd-jp'>思い切って</span>（下定決心）搞混，長得像但意思完全無關。<br>・後半句是<b>已經發生的事實</b>，通常用過去式。不能接「要做什麼」或命令、邀約：「雨だと思いきや、傘を持っていこう」是錯的。<br>・結果一定要跟預期<b>相反</b>。如果結果跟你想的一樣，就不能用。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>日常聊天比較常講的是<b>と思ったら</b>。它也能表示「本來以為～，結果…」，這時候跟と思いきや可以互換，只是口氣比較口語：<br><span class='gd-jp'>簡単かと思ったら、意外と難しかった。</span>（還以為很簡單，結果意外地難）<br>但と思ったら還有另一個意思：<b>「才剛～，馬上就…」</b>，講事情接得很快。這個意思と思いきや沒有：<br><span class='gd-jp'>子どもは泣いたと思ったら、もう笑っている。</span>（小孩才剛哭，馬上又在笑了）<br>這句換成と思いきや就不對，因為重點是「變化很快」，不是「預期落空」。</div><div class='gd-warn'>判斷小訣竅：只要是「預期被打臉」，兩個都能用，寫文章用と思いきや，聊天用と思ったら；如果是「才剛～就…」，只能用と思ったら。</div>",
  "n1-31": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜ものを」就是中文的<b>「你早說不就好了嘛！」</b>那種口氣。本來只要那樣做就沒事，偏偏沒做，結果變糟了。話裡帶著<b>可惜、埋怨、怪人</b>的情緒，有時是怪別人，有時是怪自己。</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>前面放一般的普通形（就是字典上那種不加ます的說法），最常見的是接在「〜ばいい」「〜ばよかった」後面：<br><span class='gd-pair'><span class='gd-jp'>言えばいい</span> → <span class='gd-jp'>言えばいいものを</span></span><br><span class='gd-pair'><span class='gd-jp'>聞けばよかった</span> → <span class='gd-jp'>聞けばよかったものを</span></span><br>な形容詞要用「な」來接：<span class='gd-pair'><span class='gd-jp'>便利だ</span> → <span class='gd-jp'>便利なものを</span></span>，不會說「便利だものを」。</div><div class='gd-h'>最常聽到的三種樣子</div><div class='gd-sec'><span class='gd-tag'>〜ばいいものを</span>明明那樣做就好了，偏偏不做。最常拿來念別人。</div><div class='gd-ex-line'>・<span class='gd-jp'>謝ればすむものを、意地を張るから話がややこしくなる。</span>（明明道個歉就沒事了，偏要逞強，事情才搞得這麼麻煩）</div><div class='gd-ex-line'>・<span class='gd-jp'>黙っていればいいものを、余計な一言で彼を怒らせてしまった。</span>（明明閉嘴就沒事，偏偏多講一句惹他生氣）</div><div class='gd-sec'><span class='gd-tag'>〜ば〜たものを</span>「要是～的話，本來就會～了」，但實際上沒有發生，很可惜。</div><div class='gd-ex-line'>・<span class='gd-jp'>言ってくれれば手伝ったものを。</span>（你早點說的話，我就會幫你了啊）</div><div class='gd-ex-line'>・<span class='gd-jp'>もう少し早く家を出ていれば間に合ったものを。</span>（要是再早一點出門就趕上了）</div><div class='gd-sec'><span class='gd-tag'>停在句尾</span>後面那句「你卻沒做」直接吞回去不講，只留下嘆氣的感覺。上面第三句就是這種，日劇、小說很常見。</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・別跟「東西＋を」搞混：<span class='gd-jp'>おいしいものを食べた</span>的もの是「東西」，後面直接接動詞；「〜ものを」的後面通常有逗號，接的是「結果卻…」，或乾脆不講。<br>・它是在講<b>已經發生、改不了</b>的事，後面不能接請求或命令：不會說「早く言えばいいものを、言ってください」。<br>・語氣偏書面、有點文學味，帶著責怪。日常聊天多半說「〜ばよかったのに」，對上司、客人用「ものを」去念，會顯得很不客氣。<br>・後半句是在嘆氣、抱怨，不是單純陳述事實，所以前面幾乎都是「本來那樣就好」這種假設的說法。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'><b>のに</b>：意思最接近，日常口語最常用。<br><span class='gd-jp'>早く言えばよかったのに。</span>（早說就好了嘛）<br><b>ものを</b>：同樣是抱怨，但比較書面，情緒也更重。<br><span class='gd-jp'>早く言えばよかったものを。</span>（早說不就好了，唉）<br>另外，のに也能單純講「明明～卻～」的事實（<span class='gd-jp'>雨なのに出かけた。</span>下雨還是出門了），ものを很少這樣用。</div><div class='gd-sec'><b>ものの</b>（N2）：只差一個字，意思是「雖然～但是～」，冷靜交代事實，沒有怪誰的意思。<br><span class='gd-jp'>先生に相談しようと思ったものの、言い出せなかった。</span>（雖然想找老師商量，卻開不了口）<br><span class='gd-jp'>先生に相談すればよかったものを、一人で悩んでいた。</span>（明明找老師商量就好了，卻一個人煩惱）</div><div class='gd-warn'>判斷小訣竅：前面有「〜ばいい／〜ばよかった」，又帶著「早知道就…」的嘆氣，就是ものを；只是平平地說「雖然…但是…」，就是ものの。</div>",
  "n1-43": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜とは」就是中文的<b>「竟然～」「沒想到～」</b>。遇到一件完全沒料到的事，你嚇一跳、很感慨，甚至有點傻眼或失望，就把那件事放在とは前面。很像台灣人說「蛤？他竟然是犯人喔！」的那種反應。</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>驚訝・意外</span>事情的發展跟你想的完全不一樣。</div><div class='gd-ex-line'>・<span class='gd-jp'>こんな所で君に会うとは。</span>（竟然會在這種地方碰到你）</div><div class='gd-ex-line'>・<span class='gd-jp'>まさか一回で合格するとは思わなかった。</span>（沒想到竟然一次就考過）</div><div class='gd-sec'><span class='gd-tag'>傻眼・失望</span>不只驚訝，還帶著「怎麼會這樣」的不滿。</div><div class='gd-ex-line'>・<span class='gd-jp'>大人がこんな簡単なルールも守れないとは、情けない。</span>（大人竟然連這麼簡單的規定都做不到，真丟臉）</div><div class='gd-sec'><span class='gd-tag'>話說一半</span>後面的「驚いた」「思わなかった」常常直接省掉，只留下「竟然……」的餘韻。</div><div class='gd-ex-line'>・<span class='gd-jp'>彼が犯人だったとは……。</span>（他竟然是犯人……）</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>前面用<b>普通形</b>，也就是不加です・ます的說法，然後加とは。<br>動詞：<span class='gd-pair'><span class='gd-jp'>会う</span> → <span class='gd-jp'>会うとは</span></span><span class='gd-pair'><span class='gd-jp'>負けた</span> → <span class='gd-jp'>負けたとは</span></span><br>い形容詞：<span class='gd-pair'><span class='gd-jp'>高い</span> → <span class='gd-jp'>こんなに高いとは</span></span><br>な形容詞：<span class='gd-pair'><span class='gd-jp'>簡単</span> → <span class='gd-jp'>こんなに簡単だとは</span></span><br>名詞：<span class='gd-pair'><span class='gd-jp'>犯人</span> → <span class='gd-jp'>犯人だとは</span></span>，這個だ有時會省略，說成<span class='gd-jp'>犯人とは</span>。</div><div class='gd-h'>最常聽到的樣子</div><div class='gd-sec'>前面常搭配<span class='gd-jp'>まさか</span>（萬萬沒想到），後面常接<span class='gd-jp'>思わなかった</span>、<span class='gd-jp'>思いもよらなかった</span>、<span class='gd-jp'>夢にも思わなかった</span>、<span class='gd-jp'>信じられない</span>、<span class='gd-jp'>驚きだ</span>。</div><div class='gd-ex-line'>・<span class='gd-jp'>自分が日本で働くことになるとは、夢にも思わなかった。</span>（做夢也沒想到，自己竟然會在日本工作）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・とは的は念「わ」，整個念とわ。<br>・前面要用普通形，不能接ます形，<span class='gd-jp'>会いますとは</span>是錯的。<br>・只是假設、還不確定的事，不能用とは（例如「もし合格するとは」是錯的）。不過還沒發生、但已經確定的消息可以用：<span class='gd-jp'>彼女が来月結婚するとは、驚いた。</span>（她下個月竟然要結婚了，好驚訝）<br>・とは聽起來比較正式、偏書面。跟朋友聊天時，日本人比較常說なんて。用とは也可以，只是聽起來會比較誇張、有點戲劇感。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'><b>なんて</b>：意思一樣是「竟然」，只是比較口語。<br><span class='gd-jp'>こんな所で会うなんて！</span>（竟然在這裡碰到！朋友間）<br><span class='gd-jp'>こんな所でお会いするとは。</span>（竟然在此相遇，較正式）</div><div class='gd-sec'><b>表示「所謂～」的とは</b>：同樣寫作とは，但這是在替一個詞下定義，後面接說明或問句，完全沒有驚訝的意思。<br><span class='gd-jp'>幸せとは何だろう。</span>（所謂幸福是什麼呢）<br><span class='gd-jp'>彼が幸せだったとは。</span>（他竟然是幸福的）</div><div class='gd-sec'><b>と思いきや</b>：「本來以為～，結果卻……」，後面要把<b>真正的結果</b>說出來。<br><span class='gd-jp'>晴れると思いきや、雨が降ってきた。</span>（本來以為會放晴，結果下起雨來）<br><span class='gd-jp'>こんなに雨が降るとは。</span>（竟然下這麼大的雨）</div><div class='gd-warn'>判斷小訣竅：とは前面是一整件讓你驚訝的事、後面接感想就是「竟然」；前面只有一個名詞、後面在解釋它，就是「所謂」；先寫原本的預想、再寫真正結果的，是と思いきや。</div>",
  "n1-47": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜ともなると」就是中文的<b>「都到了～這個份上，當然就～」</b>。身分升上去了、年紀到了、某個特別的時期到了，情況自然跟平常不一樣。台灣人說「都當到部長了，責任當然重」，日文就是<span class='gd-jp'>部長ともなると、責任も重くなる。</span></div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>身分・地位</span>當上某個比較高的位子，就會碰到相應的狀況。</div><div class='gd-ex-line'>・<span class='gd-jp'>部長ともなると、毎日会議ばかりだ。</span>（都當到部長了，每天都在開會）</div><div class='gd-sec'><span class='gd-tag'>年紀・階段</span>人長到某個階段，自然會變得不一樣。</div><div class='gd-ex-line'>・<span class='gd-jp'>高校生ともなると、親とあまり話さなくなる。</span>（上了高中，就不太跟爸媽講話了）</div><div class='gd-sec'><span class='gd-tag'>時期</span>一到某個特別的時期，每次都會這樣。</div><div class='gd-ex-line'>・<span class='gd-jp'>年末ともなると、どこの店も人でいっぱいだ。</span>（一到年底，每家店都擠滿了人）</div><div class='gd-sec'><span class='gd-tag'>事情的規模</span>要做一件有份量的大事，接下來的狀況也跟著變大。</div><div class='gd-ex-line'>・<span class='gd-jp'>家を建てるともなると、決めることが山ほどある。</span>（真要蓋房子的話，要決定的事多到不行）</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>名詞＋ともなると：<span class='gd-pair'><span class='gd-jp'>社長</span> → <span class='gd-jp'>社長ともなると</span></span><br>動詞辭書形（字典上查到的原形）＋ともなると：<span class='gd-pair'><span class='gd-jp'>留学する</span> → <span class='gd-jp'>留学するともなると</span></span><br>前面放的通常是<b>比一般高一級、有份量</b>的身分、年紀、時期或事情；後面接到了那個階段<b>理所當然</b>會出現的狀況或判斷。</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・它帶著「都到這種程度了」的語感。如果只是單純講一般的變化，像「一到春天就開花」，用<span class='gd-jp'>春になると</span>比較自然。<br>・後面通常接一般情況或判斷，例如責任重、很擠、要準備很多。很少接「我要～」「請～」這種自己的打算或對別人的要求。<br>・這裡的「とも」不是「都」的意思，跟<span class='gd-jp'>ともなく</span>（不經意地～）也完全是兩回事，不要看到とも就混在一起。<br>・它偏正式、偏書面。跟朋友聊天時，講<span class='gd-jp'>部長になると</span>或<span class='gd-jp'>部長にもなると</span>比較輕鬆。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'><b>ともなれば</b>：意思幾乎一樣，大部分情況可以直接互換。<br><span class='gd-jp'>部長ともなれば、責任も重くなる。</span>（都當上部長了，責任當然變重）</div><div class='gd-sec'><b>とあって</b>：講「因為碰上這次特別的情況，所以眼前就發生了～」，說的是一件已經看到、實際發生的事。<b>ともなると</b>講的是「一到這個份上，向來都會～」的一般傾向。</div><div class='gd-ex-line'>・<span class='gd-jp'>連休とあって、高速道路はどこも渋滞している。</span>（因為是連假，高速公路現在到處都在塞）</div><div class='gd-ex-line'>・<span class='gd-jp'>連休ともなると、高速道路はどこも渋滞する。</span>（每次一到連假，高速公路就到處塞）</div><div class='gd-warn'>判斷小訣竅：講「這次因為～，所以～」用とあって；講「一到～這個份上，自然都會～」用ともなると。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'><span class='gd-jp'>〜たる</span>也常跟身分一起出現，但它講的是「既然是這個身分，就應該要有的樣子」：<span class='gd-jp'>教師たる者、生徒の手本でなければならない。</span>（身為老師，就必須當學生的榜樣）。ともなると講身分帶來的<b>自然結果</b>，たる講身分該有的<b>應有表現</b>，可以對照著記。</div>",
  "n1-67": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜をよそに」就是中文的<b>「不顧～」「把～當耳邊風」</b>。<span class='gd-jp'>よそ</span>是「別人家、別的地方」，<span class='gd-jp'>〜をよそに</span>就是把旁人的擔心、反對，或周圍的狀況，當成<b>別人家的事</b>，自己照樣我行我素。</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>不管別人的心情</span>最常見的用法。前面放別人的擔心、反對、期待、批評，後面講主角照樣做自己的事。很多時候帶一點「怎麼這樣」的感覺，但不一定是罵人，也可以只是客觀描述。</div><div class='gd-ex-line'>・<span class='gd-jp'>親の心配をよそに、息子は毎晩遅くまで遊んでいる。</span>（爸媽那麼擔心，兒子還是每天晚上玩到很晚）</div><div class='gd-ex-line'>・<span class='gd-jp'>周囲の反対をよそに、彼女は会社を辞めて留学した。</span>（不顧身邊的人反對，她辭掉工作去留學了）</div><div class='gd-sec'><span class='gd-tag'>不受周圍狀況影響</span>前面放景氣、社會上的騷動這類「照理說應該會受影響」的狀況，後面講主角卻完全沒被影響。</div><div class='gd-ex-line'>・<span class='gd-jp'>不景気をよそに、この店はいつも行列ができている。</span>（景氣這麼差，這家店卻照樣大排長龍）</div><div class='gd-ex-line'>・<span class='gd-jp'>世間の騒ぎをよそに、本人はのんびり旅行を楽しんでいた。</span>（外面吵翻天，當事人卻悠哉地在旅行）</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>直接接在<b>名詞</b>後面：名詞＋をよそに<br><span class='gd-pair'><span class='gd-jp'>家族の心配</span> → <span class='gd-jp'>家族の心配をよそに</span></span><span class='gd-pair'><span class='gd-jp'>ファンの期待</span> → <span class='gd-jp'>ファンの期待をよそに</span></span><br>最常搭配的名詞：<span class='gd-jp'>心配</span>、<span class='gd-jp'>反対</span>、<span class='gd-jp'>期待</span>、<span class='gd-jp'>批判</span>、<span class='gd-jp'>不安</span>、<span class='gd-jp'>騒ぎ</span>。</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・前面要放名詞。不要寫成「心配するをよそに」，要先換成名詞<span class='gd-jp'>心配</span>。<br>・前面放的是<b>旁人的反應或周圍的狀況</b>，不是自己該做的事。「不寫功課跑去玩」不要說「宿題をよそに」，用<span class='gd-jp'>宿題そっちのけで遊ぶ</span>比較自然。<br>・多半用來描述<b>別人</b>的行為，是新聞、文章常見的書面說法，跟朋友聊天很少這樣講。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'><b>をものともせず</b>＝不把<b>困難、危險</b>放在眼裡，帶有稱讚的意思：<br><span class='gd-jp'>けがをものともせず、彼は最後まで走った。</span>（他不顧受傷，跑完了全程：佩服他）<br><b>をよそに</b>＝不管<b>旁人的心情或周圍狀況</b>，照自己的意思做：<br><span class='gd-jp'>家族の心配をよそに、彼は最後まで走った。</span>（家人那麼擔心，他還是跑完了全程：重點在他沒理家人）</div><div class='gd-sec'><b>にもかかわらず</b>＝單純的「雖然～，但是～」：<br><span class='gd-jp'>雨にもかかわらず、たくさんの人が来た。</span>（雖然下雨，還是來了很多人）<br>這句只是單純陳述「雖然下雨，還是來了很多人」，用にもかかわらず最自然。をよそに的重點是「主角對本來該在意、該受影響的事不當一回事，照樣我行我素」，所以多用在別人的擔心、反對，或景氣這類理應造成影響的周圍狀況。</div><div class='gd-warn'>判斷小訣竅：克服困難、值得佩服，用をものともせず；不管別人怎麼想、不受周圍影響，用をよそに；只是單純的「雖然～但是」，用にもかかわらず。</div>",
  "n1-70": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜ずにはおかない」就是中文的<b>「一定會讓人～」「不～絕不罷休」</b>。它有兩種用法：一種是某個東西力量太強，<b>一定會</b>讓人產生某種感覺；另一種是人下定決心，<b>不做到不罷休</b>。這是 N1 的硬派說法，多半出現在影評、書評、新聞、小說裡。</div><div class='gd-sec'>拆開來看比較好記：<span class='gd-jp'>おく</span>有「擱著不管」的意思。「不做～就不會擱著不管」，也就是「一定會做～」。</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>事物必然引發反應</span>最常見的用法。主語是電影、作品、一句話、一件事，說它<b>一定會</b>讓人感動、驚訝、思考。<br>被影響的人用<b>を</b>或<b>に</b>標示（<span class='gd-jp'>人を～させる</span>／<span class='gd-jp'>人に～させる</span>），所以動詞多半是<b>使役形</b>，也就是「讓某人～」的形：<span class='gd-pair'><span class='gd-jp'>感動する</span> → <span class='gd-jp'>感動させる</span></span>（讓人感動）。</div><div class='gd-ex-line'>・<span class='gd-jp'>この映画は、観客を感動させずにはおかない。</span>（這部電影一定會讓觀眾感動）</div><div class='gd-ex-line'>・<span class='gd-jp'>この小説の結末は、読者を驚かせずにはおかないだろう。</span>（這本小說的結局一定會讓讀者大吃一驚）</div><div class='gd-ex-line'>・<span class='gd-jp'>彼の言葉は、聞く人の心を動かさずにはおかない。</span>（他的話一定會打動聽的人）</div><div class='gd-sec'><span class='gd-tag'>不做到不罷休</span>主語是人，表示很強的決心，帶有「我一定要讓它發生」的狠勁。</div><div class='gd-ex-line'>・<span class='gd-jp'>今度こそ、真相を明らかにせずにはおかない。</span>（這次不查清真相，我絕不罷休）</div><div class='gd-ex-line'>・<span class='gd-jp'>あんな失礼なことを言われたんだ。必ず謝らせずにはおかない。</span>（被講了那麼沒禮貌的話，我一定要讓他道歉）</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>先把動詞變成ない形，再<b>把ない拿掉</b>，加上<b>ずにはおかない</b>。<br><span class='gd-pair'><span class='gd-jp'>感動させる</span> → <span class='gd-jp'>感動させない</span> → <span class='gd-jp'>感動させずにはおかない</span></span><br><span class='gd-pair'><span class='gd-jp'>動かす</span> → <span class='gd-jp'>動かさない</span> → <span class='gd-jp'>動かさずにはおかない</span></span><br>第三類要特別記：<span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>せずにはおかない</span></span><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来ずにはおかない</span>（こず）</span></div><div class='gd-sec'>另一個寫法是ない形<b>直接</b>加<b>ではおかない</b>，ない不用拿掉，意思一樣：<br><span class='gd-pair'><span class='gd-jp'>感動させない</span> → <span class='gd-jp'>感動させないではおかない</span></span><br>「ずには」比較常見，也比較書面。</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・する要變<b>せず</b>，不是しず：<span class='gd-jp'>明らかにせずにはおかない</span>。<br>・第一種用法裡，被影響的人是用を／に標示的對象，不是主語。<span class='gd-jp'>観客は感動せずにはおかない</span>是錯的；要說「電影讓觀眾感動」：<span class='gd-jp'>映画は観客を感動させずにはおかない</span>。<br>・語氣很重、很書面，日常聊天說「一定會讓人哭」講<span class='gd-jp'>絶対泣けるよ</span>就好，用ずにはおかない會像在念評論稿。<br>・第二種用法是「拚了命也要做到」的決心，像「吃完這碗拉麵」這種小事不要用。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'><b>ずにはいられない</b>（N2）＝<b>人自己忍不住</b>：<span class='gd-jp'>この映画を見て、泣かずにはいられなかった。</span>（看了這部電影，我忍不住哭了）<br><b>ずにはおかない</b>＝<b>事物一定會讓人</b>那樣：<span class='gd-jp'>この映画は、見る人を泣かせずにはおかない。</span>（這部電影一定會讓看的人掉淚）</div><div class='gd-sec'><b>ずにはすまない</b>（n1-71）＝照道理、照情況，<b>不做說不過去</b>：<span class='gd-jp'>失礼なことを言ってしまったから、謝らずにはすまない。</span>（我說了失禮的話，不道歉說不過去）<br><b>ずにはおかない</b>＝我<b>非要讓它發生</b>：<span class='gd-jp'>失礼なことを言われたから、謝らせずにはおかない。</span>（被說了失禮的話，我一定要讓他道歉）</div><div class='gd-warn'>判斷小訣竅：「自己忍不住」是ずにはいられない；「東西一定會讓人～」或「我非做到不可」是ずにはおかない；「不做說不過去」是ずにはすまない。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>接著看<span class='gd-jp'>〜ずにはすまない・ないではすまない</span>（n1-71），兩個常被一起考，對照著學最清楚。</div>",
  "n1-72": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜を余儀なくされる」就是新聞常講的<b>「被迫～」</b>。像「受颱風影響，活動被迫取消」這種，不是自己想這樣做，是<b>情勢、大環境逼得你沒別的路可走</b>。<span class='gd-jp'>余儀</span>是「別的辦法」，<span class='gd-jp'>余儀ない</span>就是「沒有別的辦法」。</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>新聞・報導</span>天災、疫情、經濟這類大事件，造成某個人或某個單位只好怎樣。</div><div class='gd-ex-line'>・<span class='gd-jp'>大雨で、試合は中止を余儀なくされた。</span>（因為大雨，比賽被迫取消）</div><div class='gd-ex-line'>・<span class='gd-jp'>地震で、多くの住民が避難生活を余儀なくされている。</span>（因為地震，很多居民被迫過著避難生活）</div><div class='gd-sec'><span class='gd-tag'>正式場合講自己的遭遇</span>寫報告、面試說明經歷時也會用。</div><div class='gd-ex-line'>・<span class='gd-jp'>会社の倒産で、退職を余儀なくされました。</span>（因為公司倒閉，我不得不離職）</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>前面放<b>名詞</b>，而且是表示「一個動作」的名詞，最常見的是<span class='gd-jp'>中止</span>、<span class='gd-jp'>延期</span>、<span class='gd-jp'>変更</span>、<span class='gd-jp'>撤退</span>、<span class='gd-jp'>入院</span>、<span class='gd-jp'>移転</span>這種後面可以加する的詞。<br>手上是動詞的話，把する拿掉，留下名詞：<span class='gd-pair'><span class='gd-jp'>延期する</span> → <span class='gd-jp'>延期を余儀なくされた</span></span><br>句子的主角（は／が前面那個）是<b>受影響、被逼的那一方</b>：比賽、老店、居民、我。</div><div class='gd-h'>最常聽到的樣子</div><div class='gd-sec'><span class='gd-tag'>余儀なくされた</span>已經發生的事，最常見。<br><span class='gd-tag'>余儀なくされている</span>現在還持續被迫這樣，像上面的避難生活。<br><span class='gd-tag'>余儀なくさせる</span>反過來站在「造成原因」那邊說，主角常是事件本身：</div><div class='gd-ex-line'>・<span class='gd-jp'>円安が、計画の見直しを余儀なくさせた。</span>（日圓貶值迫使計畫重新檢討）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・念<b>よぎなく</b>，不是よぎむなく。<br>・前面不能直接放動詞：說<span class='gd-jp'>中止を余儀なくされた</span>，不說「中止するを余儀なくされた」。<br>・自己選的、自己想做的事不能用。換工作是因為想挑戰新東西，就不是「被迫」。<br>・口氣很重、很正式，雞毛蒜皮的小事用了會很誇張。「宿題を余儀なくされた」聽起來像在開玩笑。<br>・中文說「被迫」，很多人直覺寫成させられる，但兩個意思不一樣，看下面。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>同樣是「離職」：<br><b>を余儀なくされる</b>＝<b>情勢</b>逼的，沒人指名道姓逼你，正式、偏書面：<br><span class='gd-jp'>会社の倒産で、退職を余儀なくされた。</span>（因為公司倒閉，被迫離職）<br><b>させられる</b>＝<b>某個人</b>逼你做，常帶點不甘願，口語也常用：<br><span class='gd-jp'>上司に無理やり退職させられた。</span>（被主管硬逼著離職）<br><b>ざるを得ない</b>＝<b>自己</b>衡量過後只好這樣，重點在自己的判斷：<br><span class='gd-jp'>体調が悪くて、退職せざるを得なかった。</span>（身體不好，我只好離職）</div><div class='gd-warn'>判斷小訣竅：有一個「人」在逼你，用させられる；自己想過之後只好做，用ざるを得ない；天災、景氣、時局這種大環境逼得沒路走，又是正式場合，用を余儀なくされる。</div>",
  "n1-77": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜んばかりに」就是中文的<b>「簡直就要～了」「一副要～的樣子」</b>。用誇張的方式形容某個樣子到了什麼程度：<b>差一點就</b>做出那個動作，但通常<b>還沒真的做</b>。像中文說「她急得快哭出來了」，重點是在形容她有多急，不是說她真的哭了。</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>先把動詞變成ない形，把「ない」拿掉，再加「んばかり」。<br><span class='gd-pair'><span class='gd-jp'>泣く</span> → <span class='gd-jp'>泣かない</span> → <span class='gd-jp'>泣かんばかり</span></span><br><span class='gd-pair'><span class='gd-jp'>言う</span> → <span class='gd-jp'>言わない</span> → <span class='gd-jp'>言わんばかり</span></span><br><span class='gd-pair'><span class='gd-jp'>あふれる</span> → <span class='gd-jp'>あふれない</span> → <span class='gd-jp'>あふれんばかり</span></span><br><b>する是例外</b>：不是しんばかり，要用古文的說法 <span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>せんばかり</span></span></div><div class='gd-h'>最常聽到的樣子</div><div class='gd-sec'><span class='gd-tag'>んばかりに＋動作</span>形容「怎麼做」某個動作。</div><div class='gd-ex-line'>・<span class='gd-jp'>彼女は泣かんばかりに頼んできた。</span>（她幾乎要哭出來似地拜託我）</div><div class='gd-ex-line'>・<span class='gd-jp'>犬が飛びつかんばかりに喜んで走ってきた。</span>（狗高興得簡直要撲上來，衝了過來）</div><div class='gd-sec'><span class='gd-tag'>んばかりの＋名詞</span>直接修飾後面的東西。</div><div class='gd-ex-line'>・<span class='gd-jp'>会場は割れんばかりの拍手に包まれた。</span>（全場響起震耳欲聾的掌聲）</div><div class='gd-ex-line'>・<span class='gd-jp'>彼は「お前のせいだ」と言わんばかりの顔で私を見た。</span>（他一副「都是你害的」的表情看著我）</div><div class='gd-sec'><span class='gd-tag'>んばかりだ</span>放在句尾。</div><div class='gd-ex-line'>・<span class='gd-jp'>彼の喜びようは、今にも踊り出さんばかりだった。</span>（他高興得簡直要跳起舞來了）</div><div class='gd-sec'>其中<span class='gd-jp'>言わんばかり</span>、<span class='gd-jp'>割れんばかり</span>、<span class='gd-jp'>あふれんばかり</span>、<span class='gd-jp'>泣かんばかり</span>出現得特別多，可以整組記。整體偏書面、小說的語感，不過「<span class='gd-jp'>〜と言わんばかりの顔</span>」在平常講話也常聽到。</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・這裡的「ん」<b>不是「不」</b>。<span class='gd-jp'>泣かん</span>看起來很像關西腔的「不哭」，但在這個文法裡，它是古文裡表示「就要～」的ん。<span class='gd-jp'>泣かんばかり</span>是「快哭了」，不是「不哭」。<br>・する要變<b>せんばかり</b>，寫成しんばかり是錯的。<br>・它是誇張的形容，用來描寫<b>樣子、程度</b>。如果只是單純說「看起來快哭了」，日常會話用<span class='gd-jp'>泣きそうな顔</span>就好，用<span class='gd-jp'>泣かんばかり</span>會顯得很戲劇化。<br>・通常指「差一點就」，不是真的發生了。<span class='gd-jp'>あふれんばかり</span>是「滿到快溢出來」，水還沒有真的溢出來。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'><b>とばかりに</b>前面接的是一句「台詞」，意思是「一副在說～的樣子」。它跟<span class='gd-jp'>と言わんばかりに</span>意思幾乎一樣：</div><div class='gd-ex-line'>・<span class='gd-jp'>店長は「早く帰れ」と言わんばかりに時計を見た。</span>（店長一副「快回去」的樣子看了看時鐘）</div><div class='gd-ex-line'>・<span class='gd-jp'>店長は「早く帰れ」とばかりに時計を見た。</span>（同上）</div><div class='gd-sec'>差別在前面能放什麼。<b>んばかりに</b>前面放的是<b>差點做出來的動作</b>，像是哭、溢出來、跳起來；<b>とばかりに</b>前面放的是<b>心裡的話</b>。所以「快哭出來似地」只能說<span class='gd-jp'>泣かんばかりに</span>，不能說泣くとばかりに。</div><div class='gd-warn'>判斷小訣竅：前面是「一句話」，用とばかりに或と言わんばかりに都可以；前面是「快做出來的動作」，只能用ない形加んばかりに。</div>",
  "n1-89": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>這組文法就是中文的<b>「沒～就～」</b>，分成兩種講法：<br><span class='gd-jp'>なしに</span>：「沒打招呼<b>就</b>拿走了」，描述某人<b>沒做該做的事就直接做了</b>。<br><span class='gd-jp'>なしには</span>：「沒有你，<b>就不可能</b>成功」，說的是<b>少了A，B根本辦不到</b>。<br>兩個只差一個「は」，用法差很多。</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>なしに</span>本來應該有的東西沒有，就直接做了。常帶一點「這樣不對吧」的不滿。</div><div class='gd-ex-line'>・<span class='gd-jp'>彼は連絡なしに会社を休んだ。</span>（他沒說一聲就沒來上班）</div><div class='gd-ex-line'>・<span class='gd-jp'>断りなしに、人の物を使ってはいけない。</span>（沒經過同意，不可以用別人的東西）</div><div class='gd-ex-line'>・<span class='gd-jp'>彼は一言の断りもなしに帰ってしまった。</span>（他連一聲招呼都沒打就回去了）</div><div class='gd-sec'>中間加「も」變成<span class='gd-jp'>もなしに</span>，語氣更強，有「連～都沒有」的感覺。</div><div class='gd-sec'><span class='gd-tag'>なしには</span>A是不可少的條件，沒有A，B就辦不到。</div><div class='gd-ex-line'>・<span class='gd-jp'>この映画は、涙なしには見られない。</span>（這部電影看了一定會哭）</div><div class='gd-ex-line'>・<span class='gd-jp'>皆さんの協力なしには、成功できなかった。</span>（沒有大家幫忙，我不可能成功）</div><div class='gd-ex-line'>・<span class='gd-jp'>皆さんの協力なしには、成功しなかったでしょう。</span>（要是沒有大家幫忙，應該不會成功吧）</div><div class='gd-h'>怎麼接</div><div class='gd-sec'><b>名詞</b>直接接：<span class='gd-pair'><span class='gd-jp'>許可</span> → <span class='gd-jp'>許可なしに</span></span><span class='gd-pair'><span class='gd-jp'>努力</span> → <span class='gd-jp'>努力なしには</span></span><br><b>動詞</b>要先加「こと」，變成「辭書形＋ことなしに（は）」，這是比較書面的說法：</div><div class='gd-ex-line'>・<span class='gd-jp'>彼は休むことなしに働き続けた。</span>（他一刻也沒休息，一直工作）</div><div class='gd-ex-line'>・<span class='gd-jp'>努力することなしには、夢はかなわない。</span>（不努力的話，夢想不會實現）</div><div class='gd-sec'><b>なしには的後半句一定是否定</b>。常見<span class='gd-jp'>〜できない</span>、<span class='gd-jp'>〜られない</span>、<span class='gd-jp'>〜ありえない</span>，也可以用<span class='gd-jp'>〜ない</span>、<span class='gd-jp'>〜なかった（でしょう）</span>。</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・<b>なしに後面不一定是否定</b>：<span class='gd-jp'>連絡なしに休んだ</span>就是肯定句。後面一定要否定的是<b>なしには</b>。<br>・なしには後面不能接肯定句：×<span class='gd-jp'>協力なしには成功した</span>，這樣意思兜不起來。<br>・動詞不能直接接：×<span class='gd-jp'>連絡しなしに</span>。要寫<span class='gd-jp'>連絡なしに</span>（用名詞），或是<span class='gd-jp'>連絡することなしに</span>。<br>・這是偏正式、書面的說法。平常講話多半說<b>なしで</b>：<span class='gd-jp'>予約なしで入れますか。</span>（沒預約可以進去嗎）</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>同樣講「沒預約」：<br><span class='gd-jp'>予約なしに店に入った。</span>（沒預約就進店了：交代他是<b>怎麼做的</b>）<br><span class='gd-jp'>予約なしには入れない。</span>（沒預約就進不去：講<b>必要條件</b>）</div><div class='gd-sec'><b>なくして（は）</b>：意思跟なしには幾乎一樣，但更硬，多用在演講、文章。<br><span class='gd-jp'>皆さんの協力なくしては、成功はありえなかった。</span>（沒有各位的協助，就不可能成功）</div><div class='gd-sec'><b>あっての</b>：同一件事從反方向講，「有A才有B」。<br><span class='gd-jp'>お客様あっての店だ。</span>（有客人才有這家店）<br>＝<span class='gd-jp'>お客様なしには、店は成り立たない。</span>（沒有客人，店就開不下去）</div><div class='gd-warn'>判斷小訣竅：「沒～就做了」用なしに；「沒～就不可能」用なしには（後面一定否定）；想講得更正式就換なくしては；想從「有A才有B」的角度講就用あっての。</div>",
  "n1-91": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜に足る」就是中文的<b>「足以～」「值得～」</b>，意思是這個人或這件事<b>夠格</b>讓人去信賴、尊敬、滿意。反過來的「〜に足りない」就像<b>「不足為懼」「不足掛齒」</b>，也就是不值得、沒必要。「足る」念<b>たる</b>，是很硬的書面說法，常出現在新聞、評論、小說裡。</div><div class='gd-h'>怎麼接</div><div class='gd-sec'><b>動詞辭書形＋に足る</b>：<span class='gd-pair'><span class='gd-jp'>信頼する</span> → <span class='gd-jp'>信頼するに足る</span></span><span class='gd-pair'><span class='gd-jp'>満足する</span> → <span class='gd-jp'>満足するに足る</span></span><br><b>「〜する」動詞把する拿掉，用前面的名詞直接接</b>：<span class='gd-pair'><span class='gd-jp'>信頼</span> → <span class='gd-jp'>信頼に足る</span></span><span class='gd-pair'><span class='gd-jp'>尊敬</span> → <span class='gd-jp'>尊敬に足る</span></span><br>大多放在名詞前面當形容，像「<span class='gd-jp'>信頼に足る人物</span>」，也可以放句尾當結論。</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>に足る</span>正式地評價人、資料、理由、結果「夠格、達到標準」。常搭配<span class='gd-jp'>信頼する・尊敬する・満足する・納得する・信じる</span>這類「評價」的動詞。</div><div class='gd-ex-line'>・<span class='gd-jp'>彼女は尊敬に足る先輩だ。</span>（她是值得尊敬的前輩）</div><div class='gd-ex-line'>・<span class='gd-jp'>彼の説明は、納得するに足るものだった。</span>（他的說明足以讓人信服）</div><div class='gd-ex-line'>・<span class='gd-jp'>この報告書には、信頼に足るデータがない。</span>（這份報告裡沒有可以信賴的數據）</div><div class='gd-sec'><span class='gd-tag'>に足りない</span>說某件事根本不重要、不用怕。多半用在幾個固定說法，<span class='gd-jp'>に足らない</span>也常見，意思一樣。</div><div class='gd-ex-line'>・<span class='gd-jp'>そんなのは取るに足りない問題だ。</span>（那只是不足掛齒的小問題）</div><div class='gd-ex-line'>・<span class='gd-jp'>相手は新人ばかりだ。恐れるに足りない。</span>（對手都是新人，不足為懼）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・<span class='gd-jp'>取るに足りない</span>不是「不夠拿」，是一整組背起來的「微不足道」。跟<span class='gd-jp'>お金が足りない</span>（錢不夠）的「不夠」是兩回事。<br>・前面只能接<b>辭書形</b>或「する動詞的名詞」，不能接た形、ます形：<span class='gd-jp'>信頼したに足る</span>是錯的。也不能隨便接一般名詞，像<span class='gd-jp'>彼に足る</span>就不通。<br>・否定的<span class='gd-jp'>に足りない</span>主要用在<span class='gd-jp'>取るに足りない</span>、<span class='gd-jp'>恐れるに足りない</span>這類固定說法。一般想說「不值得信任」，用<span class='gd-jp'>信頼できない</span>或<span class='gd-jp'>信頼に値しない</span>比較自然。<br>・這是書面語，跟朋友聊天說「那個人很可靠」，講<span class='gd-jp'>あの人は信頼できる</span>就好，講に足る會很像在念公文。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>同樣是在評價一本書：<br><b>に足る</b>＝夠格、達到標準：<span class='gd-jp'>これは読むに足る本だ。</span>（這是一本值得讀的書）<br><b>に値する</b>＝有那個價值，意思很接近，很多時候可以互換。差別是它的否定<span class='gd-jp'>に値しない</span>可以自由使用：<span class='gd-jp'>この本は一読に値しない。</span>（這本書不值得一讀）<br><b>に堪えない</b>（n1-36）＝爛到讓人<b>受不了</b>，帶有強烈的情緒：<span class='gd-jp'>読むに堪えない文章だ。</span>（是讓人看不下去的文章）<br>所以「<span class='gd-jp'>取るに足りない</span>」是「不重要、不用在意」，「<span class='gd-jp'>見るに堪えない</span>」是「太糟了，看不下去」，兩者方向完全不同。</div><div class='gd-warn'>判斷小訣竅：「足以～／不足掛齒」用に足る・に足りない；想自由地說「不值得～」用に値しない；「糟到受不了」用に堪えない。</div>",
  "n1-93": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜たが最後」就是中文的<b>「一旦～就完了」「一沾上就回不去」</b>。只要做了前面那件事，後面就一定會變成很糟、收不回來、停不下來的狀況。像是「洋芋片一打開就完了，一定整包吃光」，就是這種感覺。</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>動詞先變成た形（就是「〜た」過去的樣子），後面直接加「が最後」。<br><span class='gd-pair'><span class='gd-jp'>言う</span> → <span class='gd-jp'>言った</span> → <span class='gd-jp'>言ったが最後</span></span><br><span class='gd-pair'><span class='gd-jp'>寝る</span> → <span class='gd-jp'>寝た</span> → <span class='gd-jp'>寝たが最後</span></span><br><span class='gd-pair'><span class='gd-jp'>見つかる</span> → <span class='gd-jp'>見つかった</span> → <span class='gd-jp'>見つかったが最後</span></span><br>「最後」念<b>さいご</b>。</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>說某人的習性</span>某個人只要一做某件事，就一定會怎樣。</div><div class='gd-ex-line'>・<span class='gd-jp'>彼は一度寝たが最後、朝まで何をしても起きない。</span>（他一旦睡著就完了，到早上前怎麼弄都叫不醒）</div><div class='gd-sec'><span class='gd-tag'>停不下來</span>開了頭就收不了手。</div><div class='gd-ex-line'>・<span class='gd-jp'>このドラマは見始めたが最後、止まらなくなる。</span>（這部劇一開始看就停不下來）</div><div class='gd-sec'><span class='gd-tag'>警告後果</span>提醒「千萬別這樣，不然下場很慘」。</div><div class='gd-ex-line'>・<span class='gd-jp'>部長に見つかったが最後、一時間は説教される。</span>（被部長發現就完了，至少被唸一個小時）</div><div class='gd-sec'>講話時常換成<b>「〜たら最後」</b>，意思一樣，口氣比較口語：</div><div class='gd-ex-line'>・<span class='gd-jp'>そんなこと言ったら最後、絶交されるよ。</span>（那種話一說出口就完了，會被絕交喔）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・後面<b>只能放壞結果</b>。「一中樂透就過上好日子」這種好事不能用が最後。<br>・前面一定是た形，就算講的是還沒發生的事也一樣。不能說「食べるが最後」。<br>・這裡的「最後」不是中文的「最後、終於」，而是「到此為止、完蛋了」的意思。不要翻成「吃了之後最後……」。<br>・後面通常是「一定會這樣」的描述或判斷，很少接「請～」「我要～」這種請求或決心。<br>・後面常搭配<span class='gd-jp'>二度と〜ない</span>、<span class='gd-jp'>止まらない</span>、<span class='gd-jp'>終わりだ</span>這類「回不去」的說法。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'><b>〜が早いか</b>：也常翻成「一～就」，但它只是在說<b>時間很快</b>，不管好壞。<br>・<span class='gd-jp'>彼は布団に入るが早いか、眠ってしまった。</span>（他一鑽進被窩，馬上就睡著了）<br>・<span class='gd-jp'>彼は布団に入ったが最後、昼まで出てこない。</span>（他一鑽進被窩就完了，不到中午不會出來）<br>前一句是「速度快」，後一句是「之後就收不回來」。</div><div class='gd-sec'><b>〜たところで</b>：一樣接在た形後面，但意思是<b>「就算做了也沒用」</b>。<br>・<span class='gd-jp'>彼に話したが最後、みんなに知られてしまう。</span>（一跟他說就完了，大家都會知道）<br>・<span class='gd-jp'>今さら彼に話したところで、何も変わらない。</span>（現在才跟他說，也改變不了什麼）</div><div class='gd-warn'>判斷小訣竅：「做了就回不去、後果很慘」是が最後；「一～馬上就」是が早いか；「做了也沒用」是たところで。</div>",
  "n1-18": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜に至る」就像新聞裡常說的<b>「演變成～」「最後走到～這一步」</b>。事情經過一段時間、一連串的發展，最後到了某個結果。這個結果通常是有分量的事，例如打官司、倒閉、和解、做出結論。它很書面、很正式，新聞、報告、記者會、公司說明最常出現。</div><div class='gd-h'>怎麼接</div><div class='gd-sec'><b>名詞</b>：直接加に至る，中間不加の。<br><span class='gd-pair'><span class='gd-jp'>訴訟</span> → <span class='gd-jp'>訴訟に至る</span></span><span class='gd-pair'><span class='gd-jp'>和解</span> → <span class='gd-jp'>和解に至る</span></span><br><b>動詞</b>：用辭書形（字典上那個原本的樣子）加に至る。<br><span class='gd-pair'><span class='gd-jp'>中止する</span> → <span class='gd-jp'>中止するに至る</span></span><span class='gd-pair'><span class='gd-jp'>考える</span> → <span class='gd-jp'>考えるに至る</span></span></div><div class='gd-sec'><span class='gd-jp'>至る</span>本身是<b>第一類（五段動詞）</b>，變化跟<span class='gd-jp'>帰る</span>一樣：<br><span class='gd-pair'><span class='gd-jp'>至る</span> → <span class='gd-jp'>至った</span></span><span class='gd-pair'><span class='gd-jp'>至る</span> → <span class='gd-jp'>至っていない</span></span><span class='gd-pair'><span class='gd-jp'>至る</span> → <span class='gd-jp'>至らなかった</span></span></div><div class='gd-h'>最常聽到的樣子</div><div class='gd-sec'><span class='gd-tag'>最後走到某個結果</span>最常用過去式「〜に至った」，前面常有<span class='gd-jp'>ついに</span>、<span class='gd-jp'>〜の末</span>、<span class='gd-jp'>〜結果</span>，交代「經過了一段過程」。</div><div class='gd-ex-line'>・<span class='gd-jp'>長い話し合いの末、両社は合併に至った。</span>（經過長時間協商，兩家公司最後決定合併）</div><div class='gd-ex-line'>・<span class='gd-jp'>留学を通して、日本で働きたいと考えるに至った。</span>（透過留學，我漸漸有了想在日本工作的念頭）</div><div class='gd-sec'><span class='gd-tag'>還沒到那一步</span>否定常寫成「〜には至っていない」，說事情還沒發展到那個階段。</div><div class='gd-ex-line'>・<span class='gd-jp'>この技術は、まだ実用化には至っていない。</span>（這項技術還沒到能實際應用的階段）</div><div class='gd-sec'><span class='gd-tag'>固定說法</span>下面三個很常見，可以整句記。</div><div class='gd-ex-line'>・<span class='gd-jp'>幸い、大事には至らなかった。</span>（還好沒有釀成大禍）</div><div class='gd-ex-line'>・<span class='gd-jp'>中止に至った経緯をご説明します。</span>（向各位說明決定停辦的來龍去脈）</div><div class='gd-ex-line'>・<span class='gd-jp'>1990年に創業し、現在に至る。</span>（1990年創立，一直經營到現在）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・動詞要用辭書形，不要用た形：是<span class='gd-jp'>中止するに至った</span>，不是「中止したに至った」。過去的意思放在<span class='gd-jp'>至った</span>上就好。<br>・它很書面。跟朋友聊天說「我們最後分手了」，講<span class='gd-jp'>結局別れることになった</span>就好。講成「別れるに至った」，聽起來像在念新聞稿。<br>・結果要有分量，前面通常是一段過程。肚子餓去買麵包這種小事不能用「パンを買うに至った」。<br>・雖然字面是「到達」，日常的「到了某個地方」要用<span class='gd-jp'>着く</span>。<br>・<span class='gd-jp'>至らない</span>單獨用的時候，常是另一個意思「不周到」：<span class='gd-jp'>至らない点もありますが、よろしくお願いします。</span>（可能有不周到的地方，還請多多指教）</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>N1 有三個長得很像的「至る」家族，用同一個情境「公司狀況很差」來比：<br><b>に至る</b>＝事情<b>最後演變成</b>某個結果：<br><span class='gd-jp'>赤字が続き、ついに倒産に至った。</span>（持續虧損，最後走到倒閉）<br><b>に至るまで</b>＝說範圍<b>從A一直到B，連B都</b>：<br><span class='gd-jp'>社長から新入社員に至るまで、全員が毎日残業している。</span>（從社長到新進員工，全部的人每天都在加班）<br><b>に至っては</b>＝<b>至於B，更是誇張</b>，挑出最極端的例子：<br><span class='gd-jp'>どの部署も業績が悪いが、営業部に至っては目標の半分にも届いていない。</span>（每個部門業績都很差，營業部更慘，連目標的一半都不到）</div><div class='gd-warn'>判斷小訣竅：放在句尾講「最後變成怎樣」的是に至る；前面有「AからB」、在講範圍的是に至るまで；放在句子中間當話題、帶出「更誇張的那個」的是に至っては。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>接著學<span class='gd-jp'>〜に至るまで</span>和<span class='gd-jp'>〜に至っては</span>，三個一起記最不會混。也可以學<span class='gd-jp'>〜を経て</span>（經過～），它常跟に至る一起出現：<span class='gd-jp'>何度もの議論を経て、合意に至った。</span>（經過好幾次討論，最後達成了共識）</div>",
  "n1-19": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜に至るまで」就是中文的<b>「上至～下至～」「大到～小到～，通通都～」</b>。說「從老闆到工讀生，全部都參加了」，重點不在「到哪裡停」，而是在強調<b>連那麼遠、那麼細的地方都包含在內</b>，範圍很廣。</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>名詞＋に至るまで，最常見的是跟「から」搭配：<br><b>Aから Bに至るまで</b>＝從 A 一直到（連）B（都）<br><span class='gd-pair'><span class='gd-jp'>子供から高齢者</span> → <span class='gd-jp'>子供から高齢者に至るまで</span></span>（從小孩到老人）<br>B 通常放範圍的<b>另一端</b>，而且常常是「沒想到連這個也算進去」的那一端。後面常接<span class='gd-jp'>全員</span>、<span class='gd-jp'>すべて</span>、<span class='gd-jp'>誰もが</span>、<span class='gd-jp'>細かく</span>這類「全部」的字。</div><div class='gd-h'>最常聽到的樣子</div><div class='gd-sec'><span class='gd-tag'>人的範圍</span>從上到下、從老到小，所有人都包括。</div><div class='gd-ex-line'>・<span class='gd-jp'>社長から新入社員に至るまで、全員が会議に参加した。</span>（從社長到新進員工，全員都參加了會議）</div><div class='gd-ex-line'>・<span class='gd-jp'>子供から高齢者に至るまで、誰もが楽しめるイベントだ。</span>（從小孩到老人，每個人都能玩得開心的活動）</div><div class='gd-sec'><span class='gd-tag'>細節的範圍</span>從大方向到小細節，全部顧到。</div><div class='gd-ex-line'>・<span class='gd-jp'>服装から髪型に至るまで、細かく決められている。</span>（從服裝到髮型，連細節都有規定）</div><div class='gd-ex-line'>・<span class='gd-jp'>部屋の隅々に至るまで、きれいに掃除した。</span>（連房間的每個角落都打掃得乾乾淨淨）</div><div class='gd-sec'><span class='gd-tag'>時間的範圍</span>從很久以前一路到現在，強調時間拉得很長。</div><div class='gd-ex-line'>・<span class='gd-jp'>創業から現在に至るまで、この味を守り続けている。</span>（從創業到現在，一直守著這個味道）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・中文的「直到～為止」很容易讓人以為它是在<b>劃界線、設上限</b>，其實剛好相反：它不是「只到這裡」，而是「<b>連這裡都包含了</b>」，重點是範圍廣。<br>・A 跟 B 要是<b>同一類東西</b>的兩端：人對人、東西對東西、時間對時間。<br>・單純講「等到幾點」「走到車站」這種普通的終點，用<span class='gd-jp'>まで</span>就好，用に至るまで會很怪。<br>・這是<b>正式、書面</b>的說法，常出現在新聞、公告、公司介紹。跟朋友聊天說<span class='gd-jp'>おじいちゃんまでみんなスマホ持ってるよ</span>（連阿公都有手機耶）這樣就夠了。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>同樣是「至る」，N1 有三個很容易混。用同一個情境「家人跟智慧型手機」來比：<br><b>に至るまで</b>＝範圍很廣，<b>全部都包括</b>：<br><span class='gd-jp'>祖父母から孫に至るまで、家族全員がスマホを持っている。</span>（從爺爺奶奶到孫子，全家人都有智慧型手機）<br><b>に至っては</b>＝從一群裡<b>挑出最誇張的那一個</b>來講，多半帶點批評：<br><span class='gd-jp'>うちの家族は機械に弱い。祖母に至っては、電話のかけ方も知らない。</span>（我家人都不太會用機器，至於奶奶，她連電話都不會打）<br><b>に至る</b>＝事情一路發展，<b>終於走到某個結果</b>：<br><span class='gd-jp'>何度も話し合って、ようやく祖母もスマホを買うに至った。</span>（討論了好幾次，奶奶終於買了智慧型手機）</div><div class='gd-warn'>判斷小訣竅：講「從～到～，全部都」用に至るまで；講「其中最誇張的是～」用に至っては；講「最後演變成～」用に至る。</div>",
  "n1-20": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜を経て」就是中文的<b>「歷經～」「經過～」「經由～」</b>。重點是中間<b>走過一段過程、一個階段，或路過某個地方</b>，然後才到後面的結果。語氣正式，新聞、報告、人物簡介、演講裡很常見，跟朋友聊天比較少用。</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>名詞＋を経て　<span class='gd-pair'><span class='gd-jp'>長い議論</span> → <span class='gd-jp'>長い議論を経て</span>（經過漫長的討論）</span><br>前面只接<b>名詞</b>，不能直接接動詞。要講「準備」這件事，就寫<span class='gd-jp'>準備を経て</span>，不能寫成「準備するを経て」。<br>「経て」念<b>へて</b>，原形是<span class='gd-jp'>経る</span>（へる），意思就是「經過」。</div><div class='gd-sec'>後面要接名詞時，改成<b>を経た＋名詞</b>：<br><span class='gd-pair'><span class='gd-jp'>厳しい訓練</span> → <span class='gd-jp'>厳しい訓練を経た選手</span>（經過嚴格訓練的選手）</span></div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>經過一段過程</span>討論、審查、談判、準備這類要花時間、花力氣的事，做完之後才有結果。</div><div class='gd-ex-line'>・<span class='gd-jp'>長い議論を経て、ようやく結論が出た。</span>（經過漫長的討論，終於有了結論）</div><div class='gd-ex-line'>・<span class='gd-jp'>厳しい審査を経て、新しい薬が発売された。</span>（經過嚴格審查，新藥上市了）</div><div class='gd-sec'><span class='gd-tag'>經過一段時間</span>常跟「歳月」「年月」一起用，有「歷經多少年」的感覺。</div><div class='gd-ex-line'>・<span class='gd-jp'>10年の歳月を経て、橋が完成した。</span>（歷經十年歲月，橋終於完成了）</div><div class='gd-sec'><span class='gd-tag'>經歷某個身分</span>人物簡介超常見，講一個人走過哪些階段。</div><div class='gd-ex-line'>・<span class='gd-jp'>彼は会社員を経て、作家になった。</span>（他當過上班族之後，成為作家）</div><div class='gd-sec'><span class='gd-tag'>經由某個地方</span>移動路線中間路過的地點。</div><div class='gd-ex-line'>・<span class='gd-jp'>香港を経て、日本に着いた。</span>（經由香港，抵達日本）</div><div class='gd-ex-line'>・<span class='gd-jp'>台北から台中を経て、高雄へ向かう。</span>（從台北經台中，前往高雄）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・「経て」念<b>へて</b>，不是けいて，也不是たって。<br>・同一個「経」還有<span class='gd-jp'>経つ</span>（たつ），意思是「時間過去」：<span class='gd-jp'>3年経って</span>念さんねんたって，是一般口語的「過了三年」。兩個長得很像，念法和語氣都不一樣。<br>・這是正式的說法。跟朋友說「轉機經過香港」，講<span class='gd-jp'>香港経由で</span>或<span class='gd-jp'>香港で乗り換えて</span>比較自然；日常小事用「を経て」會很像在念新聞稿。<br>・前面要放<b>值得一提的過程</b>。吃個飯、洗個澡這種小事，用「〜てから」就好，不會用「を経て」。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'><b>を経て vs 経って</b>：都能講「過了一段時間」。<br><span class='gd-jp'>3年経って、やっと仕事に慣れた。</span>（過了三年，終於習慣工作了）：口語，時間後面直接接「経って」，不加を。<br><span class='gd-jp'>3年の歳月を経て、作品が完成した。</span>（歷經三年歲月，作品完成了）：正式，多半帶出「花了很多工夫才有成果」的感覺。</div><div class='gd-sec'><b>を経て vs に至る</b>：常常一起出現，但位置不一樣。<br><span class='gd-jp'>何度もの交渉を経て、合意に至った。</span>（經過多次談判，最後達成協議）<br>「を経て」講<b>中間走過的路</b>，「に至る」講<b>最後抵達的終點</b>。</div><div class='gd-warn'>判斷小訣竅：講中間經過了什麼，用「を経て」；講最後走到哪裡，用「に至る」；只是隨口說「過了幾年」，用「経って」。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>同一級的<span class='gd-jp'>〜に至る</span>、<span class='gd-jp'>〜に至るまで</span>，可以跟「を経て」一起記，寫「過程到結果」的文章時很好用。</div>",
  "n1-38": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜に難くない」就是中文的<b>「不難想像」「不難理解」「可想而知」</b>。用法是用一點點線索，就能推想出背後的情況或心情。讀音是<b>かたくない</b>，偏書面、正式，新聞、評論、文章裡很常見。</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>前面幾乎都是「在腦中推想」的詞，固定那幾個，直接整組背最快：<br><span class='gd-jp'>想像に難くない</span>（不難想像）<br><span class='gd-jp'>理解に難くない</span>（不難理解）<br><span class='gd-jp'>予想に難くない</span>（不難預料）<br><span class='gd-jp'>推測に難くない</span>（不難推測）<br><span class='gd-jp'>察するに難くない</span>（不難察覺、猜到）<br>想像、理解這類詞通常直接用名詞接「に」。<span class='gd-jp'>察する</span>本身是動詞，就用原形（辭書形）接。</div><div class='gd-sec'>你推想出來的內容放前面，常見三種樣子：「〜は」「〜ことは」「〜のは」。</div><div class='gd-ex-line'>・<span class='gd-jp'>親を亡くした彼の悲しみは想像に難くない。</span>（失去父母的他有多悲傷，不難想像）</div><div class='gd-ex-line'>・<span class='gd-jp'>この計画に反対の声が上がることは予想に難くない。</span>（不難預料這個計畫會引來反對聲浪）</div><div class='gd-ex-line'>・<span class='gd-jp'>物価がこれだけ上がれば、生活が苦しくなるのは想像に難くない。</span>（物價漲成這樣，生活會變辛苦是可想而知的）</div><div class='gd-ex-line'>・<span class='gd-jp'>彼女の表情から、何があったかは察するに難くない。</span>（從她的表情，不難猜到發生了什麼事）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・「難くない」念<b>かたくない</b>，不要念成むずかしくない。<br>・它講的是「腦中<b>推想</b>起來不難」，不是「<b>做</b>起來簡單」。想說「這題很好解」，要說<span class='gd-jp'>この問題は簡単だ</span>，不能用に難くない。<br>・前面別亂套動詞，用想像、理解、予想、推測、察する這幾個就好。<br>・它很硬，日常聊天不會這樣講。跟朋友說「可想而知」，用<span class='gd-jp'>想像できる</span>或<span class='gd-jp'>想像がつく</span>就自然了。<br>・看到「ない」不要以為是否定的意思。「難くない」＝不難＝<b>很容易</b>，整句是肯定的語氣。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>N1 有好幾個「〜に＋否定」的句型，長得很像，意思卻差很多。用同一個情境比比看：朋友被公司裁員了。<br><b>に難くない</b>＝不難推想：<span class='gd-jp'>彼のショックは想像に難くない。</span>（不難想像他受到多大的打擊）<br><b>には当たらない</b>＝沒必要那樣反應：<span class='gd-jp'>この不景気だから、リストラされても驚くには当たらない。</span>（景氣這麼差，被裁員也不必驚訝）<br><b>に堪えない</b>＝糟到看不下去、聽不下去：<span class='gd-jp'>会社の説明は聞くに堪えない言い訳ばかりだった。</span>（公司的說明全是讓人聽不下去的藉口）</div><div class='gd-warn'>判斷小訣竅：「可想而知」是に難くない；「犯不著～」是には当たらない；「慘到受不了」是に堪えない。</div>",
  "n1-37": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜を禁じ得ない」就是中文的<b>「不禁～」「忍不住感到～」</b>。看到、聽到某件事，同情、驚訝、憤怒這類情緒自己湧上來，想壓也壓不住。它很正式，多半出現在新聞評論、文章、演講裡，平常聊天幾乎不會講。</div><div class='gd-h'>拆開來看就懂了</div><div class='gd-sec'><span class='gd-jp'>禁じる</span>是「禁止」，<span class='gd-jp'>得ない</span>是「無法～」。合起來就是「想禁止也禁止不了」，也就是那個情緒擋不住、自己冒出來了。<br>念法是<b>きんじえない</b>，「得」在這裡念「え」。</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>前面放<b>表示情緒的名詞</b>，加「を禁じ得ない」。講過去的事就變成「を禁じ得なかった」。<br><span class='gd-pair'><span class='gd-jp'>同情</span> → <span class='gd-jp'>同情を禁じ得ない</span></span>（不禁同情）<br><span class='gd-pair'><span class='gd-jp'>驚き</span> → <span class='gd-jp'>驚きを禁じ得なかった</span></span>（當時不禁大吃一驚）<br>常搭配的名詞：<span class='gd-jp'>同情</span>、<span class='gd-jp'>驚き</span>、<span class='gd-jp'>怒り</span>、<span class='gd-jp'>憤り</span>、<span class='gd-jp'>涙</span>、<span class='gd-jp'>戸惑い</span>、<span class='gd-jp'>疑問</span>。</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>被事情觸動</span>前面通常會先交代「看到什麼、聽到什麼、想到什麼」，後面再說情緒壓不住。</div><div class='gd-ex-line'>・<span class='gd-jp'>その知らせを聞いて、驚きを禁じ得なかった。</span>（聽到那個消息，我不禁大吃一驚）</div><div class='gd-ex-line'>・<span class='gd-jp'>被害者の話を聞き、涙を禁じ得なかった。</span>（聽了受害者的敘述，我忍不住流下眼淚）</div><div class='gd-sec'><span class='gd-tag'>正式表態</span>評論、社論裡用來表達強烈的看法，很常見。</div><div class='gd-ex-line'>・<span class='gd-jp'>政府の対応には、怒りを禁じ得ない。</span>（對政府的處理方式，我不禁感到憤怒）</div><div class='gd-ex-line'>・<span class='gd-jp'>この計画には疑問を禁じ得ない。</span>（對這個計畫，我不禁抱持疑問）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・前面要放<b>名詞</b>，不能直接放動詞：要說<span class='gd-jp'>涙を禁じ得ない</span>、<span class='gd-jp'>驚きを禁じ得ない</span>，不能說「泣くを禁じ得ない」「驚くを禁じ得ない」。<br>・它講的是<b>自己</b>湧上來的情緒，不是用來描述別人的心情。<br>・語氣非常硬。跟朋友聊天說「感動を禁じ得なかった」會像在念稿，口語講<span class='gd-jp'>思わず泣いちゃった</span>（我忍不住哭了）就好。<br>・「得ない」念<b>えない</b>，不要念成うない。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>同一個情境：聽了他的遭遇，覺得很同情。<br><b>を禁じ得ない</b>＝情緒<b>湧上來、壓不住</b>，很正式，前面接名詞：<br><span class='gd-jp'>彼の話を聞いて、同情を禁じ得なかった。</span>（聽了他的話，我不禁同情起他）<br><b>ずにはいられない</b>（N2）＝「忍不住會～」，前面接動詞，也可以講動作，比較常用、沒那麼硬：<br><span class='gd-jp'>彼の話を聞いて、同情せずにはいられなかった。</span>（聽了他的話，我忍不住同情他）<br><span class='gd-jp'>あまりにおかしくて、笑わずにはいられなかった。</span>（實在太好笑，我忍不住笑出來）<br><b>に堪えない</b>放情緒名詞時是「～到了極點、非常～」，常見的有<span class='gd-jp'>感謝に堪えない</span>（感激不盡）、<span class='gd-jp'>遺憾に堪えない</span>、<span class='gd-jp'>同情に堪えない</span>、<span class='gd-jp'>憤慨に堪えない</span>，多用在正式致詞或文章。語感偏向「情緒強烈到承受不住」：<br><span class='gd-jp'>被災された方々のことを思うと、同情に堪えない。</span>（想到受災的各位，實在令人同情不已）<br>另外，に堪えない接動詞時是另一種意思：<span class='gd-jp'>見るに堪えない</span>是「慘到看不下去」，跟を禁じ得ない無關，別混在一起。</div><div class='gd-warn'>判斷小訣竅：情緒「冒出來壓不住」用を禁じ得ない；情緒「強烈到承受不住、～到極點」用に堪えない；一般講「忍不住去做」用ずにはいられない。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>同一組講強烈情緒的N1文法還有<span class='gd-jp'>〜て止まない</span>（打從心底一直～），例如<span class='gd-jp'>皆様のご健康を願って止みません。</span>（衷心祝福各位身體健康），常出現在致詞和信件結尾。</div>",
  "n1-36": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜に堪えない」有兩個方向剛好相反的意思，中文都能找到對應：<br>①<b>「不堪入目、不堪入耳」</b>：東西糟到、慘到讓人看不下去、聽不下去。<br>②<b>「不勝感激、不勝感慨」</b>：心裡的情緒滿到裝不下，也就是「非常～」。<br>兩種都很書面、很正式，日常聊天幾乎不會講。</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>①<b>動詞辭書形＋に堪えない</b>：前面幾乎只放「看、聽、讀」這三個動作。<br><span class='gd-pair'><span class='gd-jp'>見る</span> → <span class='gd-jp'>見るに堪えない</span></span><span class='gd-pair'><span class='gd-jp'>聞く</span> → <span class='gd-jp'>聞くに堪えない</span></span><span class='gd-pair'><span class='gd-jp'>読む</span> → <span class='gd-jp'>読むに堪えない</span></span><br>②<b>感情名詞＋に堪えない</b>：最常見的是<span class='gd-jp'>感謝</span>、<span class='gd-jp'>感激</span>、<span class='gd-jp'>感慨</span>、<span class='gd-jp'>遺憾</span>、<span class='gd-jp'>痛恨</span>這幾個詞。<br><span class='gd-pair'><span class='gd-jp'>感謝</span> → <span class='gd-jp'>感謝に堪えません</span></span><span class='gd-pair'><span class='gd-jp'>遺憾</span> → <span class='gd-jp'>遺憾に堪えない</span></span><br>「堪えない」念<b>たえない</b>，也常直接寫成平假名「たえない」。</div><div class='gd-h'>用法①：糟到看不下去</div><div class='gd-sec'><span class='gd-tag'>批評、嫌棄</span>說的是內容太差、太難聽、太慘，不值得看、聽、讀。後面常直接接名詞，例如「聞くに堪えない悪口」。</div><div class='gd-ex-line'>・<span class='gd-jp'>聞くに堪えない悪口だった。</span>（那些壞話難聽到不堪入耳）</div><div class='gd-ex-line'>・<span class='gd-jp'>この翻訳はひどくて、読むに堪えない。</span>（這份翻譯爛到讀不下去）</div><div class='gd-ex-line'>・<span class='gd-jp'>事故の現場は見るに堪えない状態だった。</span>（事故現場慘不忍睹）</div><div class='gd-h'>用法②：情緒滿到裝不下</div><div class='gd-sec'><span class='gd-tag'>正式致詞</span>常出現在致詞、感謝信、道歉聲明、悼詞，講的是<b>自己</b>的強烈感受。當面對人講通常說「〜に堪えません」。</div><div class='gd-ex-line'>・<span class='gd-jp'>皆様の温かいご支援に、感謝の念に堪えません。</span>（對各位溫暖的支持，不勝感激）</div><div class='gd-ex-line'>・<span class='gd-jp'>このような事態となり、誠に遺憾に堪えません。</span>（演變成這樣的局面，我們深感遺憾）</div><div class='gd-ex-line'>・<span class='gd-jp'>二十年ぶりに母校を訪れ、感慨に堪えない。</span>（睽違二十年回到母校，不勝感慨）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・②<b>不是負面意思</b>。「<span class='gd-jp'>感謝に堪えない</span>」不是「感謝到受不了、很煩」，而是「感謝到心裡裝不下」，等於「非常感謝」。<br>・不能拿來講身體上的忍耐。熱到受不了要說<span class='gd-jp'>暑くてたまらない</span>或<span class='gd-jp'>暑さに耐えられない</span>，不能說暑さに堪えない。<br>・①是在批評東西本身太糟或太慘，不是「我沒空看」「我不想看」。<br>・②非常正式，跟朋友講「感謝に堪えない」會像在發表演講，平常說<span class='gd-jp'>本当にありがとう</span>就好。<br>・②前面要放「感謝、遺憾」這類漢字感情名詞，不能直接接形容詞，例如不能說悲しいに堪えない。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>同樣是「一場事故」，三種說法的感覺不一樣：<br><b>に堪えない</b>＝正式場合表達自己<b>極深的感受</b>，像官方聲明：<br><span class='gd-jp'>このような事故が起きたことは、誠に遺憾に堪えません。</span>（發生這樣的事故，我們深感遺憾）<br><b>を禁じ得ない</b>＝某件事讓人<b>忍不住湧出</b>某種情緒，重點在「控制不住」：<br><span class='gd-jp'>遺族の話を聞いて、涙を禁じ得なかった。</span>（聽了遺族的話，我忍不住落淚）<br><b>てたまらない</b>＝口語的「～得不得了」，講個人的感覺或生理感受：<br><span class='gd-jp'>あの映像を思い出すと、つらくてたまらない。</span>（一想到那個畫面就難過得不得了）</div><div class='gd-warn'>判斷小訣竅：發表聲明、致詞說「不勝～」用に堪えない；「忍不住～」用を禁じ得ない；跟朋友講「～得要命」用てたまらない。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>改成肯定形「〜に堪える」，意思會變成「經得起～、值得～」：<span class='gd-jp'>大人の鑑賞に堪える作品だ。</span>（這是值得大人欣賞的作品）。意思接近的還有「〜に足る」，可以一起學。</div>",
  "n1-39": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜てやまない」就是中文的<b>「衷心～」「～不已」</b>。<span class='gd-jp'>やむ</span>是「停止」，像<span class='gd-jp'>雨がやむ</span>（雨停了）。所以<span class='gd-jp'>願ってやまない</span>直翻是「願望停不下來」，也就是一直放在心裡、很深很強烈的感情。這是正式的書面說法，常出現在致詞、賀詞、文章裡。</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>動詞て形＋やまない。一般寫平假名<span class='gd-jp'>やまない</span>，比較少寫漢字。<br><span class='gd-pair'><span class='gd-jp'>願う</span> → <span class='gd-jp'>願って</span> → <span class='gd-jp'>願ってやまない</span></span><br><span class='gd-pair'><span class='gd-jp'>期待する</span> → <span class='gd-jp'>期待して</span> → <span class='gd-jp'>期待してやまない</span></span><br>正式場合講給人聽，用禮貌形<span class='gd-jp'>やみません</span>；講過去的事用<span class='gd-jp'>やまなかった</span>。<br>前面幾乎都是表達心情的動詞：<span class='gd-jp'>願う</span>、<span class='gd-jp'>祈る</span>、<span class='gd-jp'>望む</span>、<span class='gd-jp'>期待する</span>、<span class='gd-jp'>愛する</span>、<span class='gd-jp'>尊敬する</span>、<span class='gd-jp'>信じる</span>、<span class='gd-jp'>憧れる</span>。</div><div class='gd-h'>最常聽到的樣子</div><div class='gd-sec'><span class='gd-tag'>致詞・賀詞</span>祝福對方，最典型的用法。</div><div class='gd-ex-line'>・<span class='gd-jp'>皆様のご健康を祈ってやみません。</span>（衷心祝福各位身體健康）</div><div class='gd-sec'><span class='gd-tag'>自己的信念</span>寫文章表達自己長久以來的想法。</div><div class='gd-ex-line'>・<span class='gd-jp'>私は彼の才能を信じてやまない。</span>（我始終深信他的才華）</div><div class='gd-sec'><span class='gd-tag'>讓人著迷</span>主詞是東西，表示它一直深深吸引人。</div><div class='gd-ex-line'>・<span class='gd-jp'>この町の景色は、今も多くの人を魅了してやまない。</span>（這座城鎮的景色，至今仍讓許多人著迷不已）</div><div class='gd-sec'><span class='gd-tag'>修飾名詞</span>講別人的感情時，常放在名詞前面當形容。</div><div class='gd-ex-line'>・<span class='gd-jp'>祖父が愛してやまなかった海</span>（爺爺一生深愛的那片海）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・摘要寫「不停地」，但它<b>不是</b>拿來說動作一直持續。<span class='gd-jp'>雨が降ってやまない</span>、<span class='gd-jp'>走ってやまない</span>都不對，雨一直下就直接說<span class='gd-jp'>雨がやまない</span>。它只用在<b>心情、願望</b>。<br>・只接動詞，不接形容詞。「開心得不得了」不能說嬉しくてやまない，要說<span class='gd-jp'>嬉しくてたまらない</span>。<br>・這是很正式的說法，跟朋友聊天講<span class='gd-jp'>君を愛してやまない</span>，聽起來會像在念稿。<br>・正式場合講給人聽，用<span class='gd-jp'>願ってやみません</span>，不要說成願ってやまないです。<br>・放在句尾時，主詞通常是「我」。講別人的感情，多半出現在寫文章，或像上面那樣放在名詞前面。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>同樣講「故鄉」，三種感情不一樣：<br><b>てやまない</b>＝長久放在心裡的深厚感情，書面：<span class='gd-jp'>故郷を愛してやまない。</span>（深愛著故鄉）<br><b>てたまらない</b>（N2）＝現在的感覺強烈到受不了，口語也能用：<span class='gd-jp'>故郷に帰りたくてたまらない。</span>（好想回故鄉，想得受不了）<br><b>を禁じ得ない</b>＝看到某件事，忍不住湧上的感情：<span class='gd-jp'>故郷の変わりように驚きを禁じ得ない。</span>（看到故鄉的改變，不禁感到驚訝）</div><div class='gd-warn'>判斷小訣竅：長年的心願、愛、信念用<span class='gd-jp'>てやまない</span>；當下難受、好想要用<span class='gd-jp'>てたまらない</span>；被某件事觸動、忍不住產生的反應用<span class='gd-jp'>を禁じ得ない</span>。</div>",
  "n1-34": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜極まりない」就是中文的<b>「～至極」「～到了極點」</b>，像「無禮至極」「危險至極」。它專門用來<b>很重地批評</b>一件事，口氣跟新聞、評論、正式抗議信一樣硬。「〜極まる」意思一樣，只是更文言一點。</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>嚴厲批評</span>對別人的態度、行為下很重的評語。</div><div class='gd-ex-line'>・<span class='gd-jp'>あの店員の対応は失礼極まりない。</span>（那個店員的應對無禮至極）</div><div class='gd-ex-line'>・<span class='gd-jp'>夜中に大声で騒ぐなんて、迷惑極まりない。</span>（半夜大聲吵鬧，真是擾人到了極點）</div><div class='gd-sec'><span class='gd-tag'>描述很糟的狀況</span>新聞、報告講危險、麻煩的事。</div><div class='gd-ex-line'>・<span class='gd-jp'>雨の夜に無灯火で走るのは危険極まりない。</span>（下雨的晚上不開燈騎車，危險到了極點）</div><div class='gd-sec'><span class='gd-tag'>放在名詞前面</span>直接拿來形容後面的東西。</div><div class='gd-ex-line'>・<span class='gd-jp'>退屈極まりない会議が三時間も続いた。</span>（無聊透頂的會議整整開了三個小時）</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>な形容詞把「な」拿掉，直接接上去：<br><span class='gd-pair'><span class='gd-jp'>失礼な</span> → <span class='gd-jp'>失礼極まりない</span></span><span class='gd-pair'><span class='gd-jp'>危険な</span> → <span class='gd-jp'>危険極まる</span></span><br>最常搭的字：<span class='gd-jp'>失礼、無礼、危険、迷惑、不快、不愉快、退屈、非常識、無責任</span>，幾乎都是兩個漢字以上、本身就帶負面的詞。<br><br>「極まりない」的尾巴是「ない」，所以可以像い形容詞那樣變過去式：<span class='gd-pair'><span class='gd-jp'>失礼極まりない</span> → <span class='gd-jp'>失礼極まりなかった</span></span><br>い形容詞不能直接接，要先加「こと」：<span class='gd-pair'><span class='gd-jp'>情けない</span> → <span class='gd-jp'>情けないこと極まりない</span></span>（窩囊到了極點）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・「極まりない」的「ない」<b>不是否定</b>。「極まり」是「盡頭」，「極まりない」等於「沒有盡頭」，也就是「極度～」。<span class='gd-jp'>失礼極まりない</span>是「無禮至極」，不是「不失禮」。<br>・中間不要加な：是<span class='gd-jp'>失礼極まりない</span>，不是「失礼な極まりない」。<br>・幾乎都用在壞事上。想稱讚東西好吃、好用，請換別的說法，不要硬套它。<br>・口氣很重又很硬。跟朋友抱怨用<span class='gd-jp'>本当に失礼だよね</span>就好；當面對人說「失礼極まりない」，等於正式翻臉。<br>・念法：極まりない念きわまりない，極まる念きわまる。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>同樣是被店員無禮對待：<br><b>極まりない</b>＝冷靜地下一個很重的<b>評語</b>：<span class='gd-jp'>あの店員の態度は失礼極まりない。</span>（那個店員的態度無禮至極）<br><b>といったらない</b>＝整個人<b>情緒滿出來</b>的感嘆，比較口語，い形容詞可以直接接：<span class='gd-jp'>あの店員の態度、腹が立つといったらない。</span>（那個店員的態度真是氣死人了）</div><div class='gd-sec'><b>の至り</b>也翻成「～之至」，但方向相反：講的是<b>自己</b>的感受，多半是光榮、感激這類好事，用在致詞、客氣場合。<br><span class='gd-jp'>このような賞をいただき、光栄の至りです。</span>（能得到這樣的獎，光榮之至）</div><div class='gd-warn'>判斷小訣竅：批評一件壞事用「極まりない」；客氣地說自己很光榮、很感激用「の至り」；氣到、羞到、開心到情緒爆表的感嘆用「といったらない」。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>同一個漢字還有兩個常見說法：<br>名詞＋の極み：<span class='gd-jp'>こんな料理を毎日食べるなんて、贅沢の極みだ。</span>（每天吃這種料理，真是奢侈到了極點）<br>固定說法「感極まる」：<span class='gd-jp'>優勝が決まった瞬間、感極まって泣き出した。</span>（確定奪冠的那一刻，激動到哭了出來）</div>",
  "n1-52": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜まじき」就是中文的<b>「身為～，怎麼可以這樣！」</b>。用來罵一個人做了<b>跟他身分不相配</b>的事，像新聞說的「有失身分」「失格」。語氣很重、很正式，多半出現在新聞、社論、正式發言裡。</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>動詞辭書形（字典上查到的原形）＋まじき＋名詞<br><span class='gd-pair'><span class='gd-jp'>ある</span> → <span class='gd-jp'>あるまじき行為</span></span>（不該有的行為）<br><span class='gd-pair'><span class='gd-jp'>許す</span> → <span class='gd-jp'>許すまじき犯罪</span></span>（不可饒恕的犯罪）<br><span class='gd-pair'><span class='gd-jp'>言う</span> → <span class='gd-jp'>言うまじきこと</span></span>（不該說的話）<br>「する」除了<span class='gd-jp'>するまじき</span>，也會看到古一點的<span class='gd-jp'>すまじき</span>。</div><div class='gd-h'>最常聽到的樣子</div><div class='gd-sec'><span class='gd-tag'>身分＋にあるまじき</span>九成以上都是這個固定組合：「人或身分＋に（或として）＋あるまじき＋名詞」，意思是「以這個身分來說，不應該出現的～」。</div><div class='gd-ex-line'>・<span class='gd-jp'>医者にあるまじき行為だ。</span>（那是身為醫生不該有的行為）</div><div class='gd-ex-line'>・<span class='gd-jp'>プロにあるまじきミスだ。</span>（這是職業選手不該犯的失誤）</div><div class='gd-ex-line'>・<span class='gd-jp'>社会人としてあるまじき態度だと叱られた。</span>（被罵說那是社會人士不該有的態度）</div><div class='gd-sec'><span class='gd-tag'>許すまじき</span>不提身分，直接說「這件事絕不能原諒」。</div><div class='gd-ex-line'>・<span class='gd-jp'>子どもを狙った許すまじき犯罪だ。</span>（這是針對小孩、不可饒恕的犯罪）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・まじき<b>後面一定要接名詞</b>，不能直接結束句子：<br>　×<span class='gd-jp'>教師にあるまじきだ。</span><br>　○<span class='gd-jp'>教師にあるまじき発言だ。</span><br>・意思是「<b>不應該</b>」，不是「<b>不能、做不到</b>」。它是在做道德批判，跟能力無關。<br>・「許すまじき」的「許す」是<b>旁人</b>原諒不原諒，所以「政治家として許すまじき発言」容易讀成「我們身為政治家不能原諒」。要講「那個政治家不該說這種話」，用<span class='gd-jp'>政治家としてあるまじき発言</span>最清楚。<br>・非常生硬，平常聊天講出來會很怪。口語說<span class='gd-jp'>先生なのに、ありえない。</span>（明明是老師，太誇張了）就好。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>同樣罵一位老師體罰學生：<br><b>べきではない</b>＝一般的「不應該」，什麼場合都能用，也能放句尾：<span class='gd-jp'>教師は体罰をするべきではない。</span>（老師不應該體罰）<br><b>まじき</b>＝一樣是「不應該」，但更重、更書面，而且只能放名詞前面：<span class='gd-jp'>体罰は教師にあるまじき行為だ。</span>（體罰是老師不該有的行為）<br><b>べからざる</b>＝重點在「不可以、不能缺」，常講規則或必要性，不一定扯到身分：<span class='gd-jp'>水は生活に欠くべからざるものだ。</span>（水是生活不可或缺的東西）</div><div class='gd-warn'>判斷小訣竅：前面有「身分＋に／として」，在罵人失格，就是まじき；講規則或「不可或缺」，就是べからざる。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>「〜たる」＝身為～這樣的人，常跟まじき的意思搭在一起出現：<span class='gd-jp'>教師たる者、生徒の手本でなければならない。</span>（身為老師，就必須當學生的榜樣）</div>",
  "n1-53": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜べからず」就是告示牌上的<b>「禁止～」「不得～」「請勿～」</b>。它是古文說法，感覺很像中文的「閒人勿進」「禁止喧嘩」，又硬又正式。平常講話幾乎不會用，在<b>告示、標語、格言</b>裡最常看到。</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>告示牌</span>寫給所有人看的禁止規定，放在句尾。</div><div class='gd-ex-line'>・<span class='gd-jp'>ここに入るべからず。</span>（此處禁止進入）</div><div class='gd-ex-line'>・<span class='gd-jp'>ここにごみを捨てるべからず。</span>（此處禁止丟垃圾）</div><div class='gd-sec'><span class='gd-tag'>格言・標語</span>很多老話、名言都是這個形，直接整句記起來。</div><div class='gd-ex-line'>・<span class='gd-jp'>働かざる者食うべからず。</span>（不工作的人就不該吃飯）</div><div class='gd-ex-line'>・<span class='gd-jp'>初心忘るべからず。</span>（不可忘記初衷）</div><div class='gd-sec'><span class='gd-tag'>べからざる＋名詞</span>後面要接名詞的時候，換成<b>べからざる</b>，意思是「不可～的（東西）」，常出現在文章、新聞。</div><div class='gd-ex-line'>・<span class='gd-jp'>水は生活に欠くべからざるものだ。</span>（水是生活中不可或缺的東西）</div><div class='gd-ex-line'>・<span class='gd-jp'>それは許すべからざる行為だ。</span>（那是不可原諒的行為）</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>動詞用<b>辭書形</b>（字典上查到的原形），直接加：<br><span class='gd-pair'><span class='gd-jp'>入る</span> → <span class='gd-jp'>入るべからず</span></span><span class='gd-pair'><span class='gd-jp'>捨てる</span> → <span class='gd-jp'>捨てるべからず</span></span><br><b>する</b>通常變成<b>す</b>再接：<span class='gd-pair'><span class='gd-jp'>駐車する</span> → <span class='gd-jp'>駐車すべからず</span></span>（寫成するべからず也看得到，但すべからず比較道地）<br>要修飾名詞，就把ず換成ざる：<span class='gd-pair'><span class='gd-jp'>欠くべからず</span> → <span class='gd-jp'>欠くべからざるもの</span></span></div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・句尾用<b>べからず</b>，名詞前用<b>べからざる</b>，不要寫成「べからずもの」。<br>・它是寫在牌子上、文章裡的，<b>不能拿來當面叫人別做</b>。對朋友說「吸うべからず」會很怪，口語請用<span class='gd-jp'>吸わないで</span>或<span class='gd-jp'>吸っちゃだめ</span>。<br>・前面不能接ない形，「行かないべからず」是錯的。它本身就已經是「不可」了。<br>・<span class='gd-jp'>初心忘るべからず</span>的「忘る」是古文裡<span class='gd-jp'>忘れる</span>的原形，屬於固定說法，照原樣背就好，不要自己改。<br>・<span class='gd-jp'>すべからく</span>長得很像，但它是另一個詞，意思是「理應、務必」，不是否定。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>同樣是「抽菸」的情境：<br><b>べからず</b>＝告示上的<b>禁止規定</b>：<span class='gd-jp'>ここでたばこを吸うべからず。</span>（此處禁止吸菸）<br><b>べきではない</b>＝<b>勸人</b>「不應該」，一般講話、寫文章都能用：<span class='gd-jp'>ここでたばこを吸うべきではない。</span>（這裡不應該抽菸）<br><b>まじき</b>＝以那個<b>身分</b>來說不該有的：<span class='gd-jp'>患者の前でたばこを吸うなんて、医者にあるまじき行為だ。</span>（在病人面前抽菸，是身為醫生不該有的行為）</div><div class='gd-sec'>另外<b>べく</b>只是長得像，意思完全不同，是「為了～」：<span class='gd-jp'>合格すべく、毎日勉強している。</span>（為了考上，每天都在念書）</div><div class='gd-warn'>判斷小訣竅：看到告示、格言裡的「禁止」用べからず，勸人「不應該」用べきではない，扯到「身為～」用まじき，「為了～」是べく。</div>",
  "n1-55": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜たる」就是中文的<b>「身為～」</b>，跟「身為人師」「為人父母者」那種口氣很像。先把一個有份量的身份抬出來，後面再說「這個身份<b>就該</b>怎樣」。<br><span class='gd-jp'>たる</span>是很老的說法，意思等於<span class='gd-jp'>である</span>，專門放在名詞前面，所以聽起來很正式、很有架子，多半出現在文章、演講、訓話裡。</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>名詞＋たる＋名詞。最常見的是後面接<span class='gd-jp'>者</span>（也常寫成<span class='gd-jp'>もの</span>，一樣是「人」的意思）：<br><span class='gd-pair'><span class='gd-jp'>医者</span> → <span class='gd-jp'>医者たる者</span></span>（身為醫生的人）<br><span class='gd-pair'><span class='gd-jp'>親</span> → <span class='gd-jp'>親たるもの</span></span>（身為父母的人）</div><div class='gd-h'>最常聽到的樣子</div><div class='gd-sec'><span class='gd-tag'>講應該怎樣</span>最大宗。後面常接<span class='gd-jp'>べきだ</span>、<span class='gd-jp'>なければならない</span>、<span class='gd-jp'>てはならない</span>。</div><div class='gd-ex-line'>・<span class='gd-jp'>医者たる者、患者の話をよく聞くべきだ。</span>（身為醫生，就該好好聽病人說話）</div><div class='gd-ex-line'>・<span class='gd-jp'>プロたる者、言い訳はしない。</span>（身為職業選手，不找藉口）</div><div class='gd-sec'><span class='gd-tag'>批評沒做到</span>先抬出身份，再說他竟然做出不像樣的事。</div><div class='gd-ex-line'>・<span class='gd-jp'>教師たる者が生徒にうそをつくなんて、許されることではない。</span>（身為老師竟然對學生說謊，這是不可原諒的）</div><div class='gd-sec'><span class='gd-tag'>接其他名詞</span>後面不一定是者，也可以接「資格」這類名詞。</div><div class='gd-ex-line'>・<span class='gd-jp'>彼に代表たる資格はない。</span>（他沒有當代表的資格）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・前面只接<b>名詞</b>，而且通常是身份、職位、立場這種「有該盡責任」的詞。不能接動詞或形容詞。<br>・它不是過去式的「た」再加「る」，整個<span class='gd-jp'>たる</span>是一個詞，不要拆開想。<br>・很生硬，日常聊天這樣講會像在訓話。口語要講「身為～就該～」，用<span class='gd-jp'>〜なんだから</span>就好：<span class='gd-jp'>先生なんだから、ちゃんとしてよ。</span>（你是老師耶，認真一點啦）<br>・別跟同音的<span class='gd-jp'>足る</span>（夠格、值得）混在一起，下面會比較。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>同樣講老師：<br><b>たる者</b>＝先抬出身份，再講應該怎樣（或批評竟然沒做到）：<span class='gd-jp'>教師たる者、生徒の手本であるべきだ。</span>（身為老師，就該當學生的榜樣）<br><b>にあるまじき</b>＝直接評斷某個<b>行為、發言</b>「是這個身份不該有的」，後面接<span class='gd-jp'>行為</span>、<span class='gd-jp'>発言</span>這類名詞：<span class='gd-jp'>教師にあるまじき発言だ。</span>（這是身為老師不該有的發言）<br><b>ともなれば</b>＝到了那個等級，<b>自然就會</b>～，講的是理所當然的結果，不是義務：<span class='gd-jp'>ベテラン教師ともなれば、生徒の顔を見ただけで悩みに気づく。</span>（到了資深老師的程度，看學生的臉就知道他有煩惱）<br><b>に足る</b>＝<b>值得</b>～，前面接<span class='gd-jp'>信頼</span>、<span class='gd-jp'>尊敬</span>這類詞，而且多了一個<span class='gd-jp'>に</span>：<span class='gd-jp'>彼は信頼に足る教師だ。</span>（他是值得信賴的老師）</div><div class='gd-warn'>判斷小訣竅：要說「身為～就該怎樣」或「身為～竟然…」，先把身份抬出來時用たる（者）；要直接評斷某個行為「是身為～不該有的」，用「～にあるまじき＋行為／発言」；說「到了那個等級自然就～」用ともなれば；說「值得～」用に足る。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>同樣用來評斷身份的<span class='gd-jp'>〜まじき</span>（不該有的～），還有講「到了那種程度」的<span class='gd-jp'>〜ともなれば</span>，可以一起記。</div>",
  "n1-56": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜なくして（は）」就是中文的<b>「沒有～，就不可能…」</b>。前面放一個很重要的東西，後面說「少了它，事情根本辦不到」，用來強調<b>這東西絕對少不了</b>。語氣很正式，多半出現在文章、演講、得獎感言這種場合。</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>名詞直接加なくして，<b>中間不加「が」或「を」</b>：<br><span class='gd-pair'><span class='gd-jp'>努力</span> → <span class='gd-jp'>努力なくして</span></span><span class='gd-pair'><span class='gd-jp'>協力</span> → <span class='gd-jp'>協力なくしては</span></span><br>後面一定接「不可能、辦不到」的說法，最常見的是<span class='gd-jp'>あり得ない</span>（不可能有）、<span class='gd-jp'>できない</span>、<span class='gd-jp'>語れない</span>（沒辦法談）。<br>前面要放動作時，用「辭書形＋ことなくして」：<span class='gd-pair'><span class='gd-jp'>苦労する</span> → <span class='gd-jp'>苦労することなくして</span></span></div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>講道理</span>說明成功、成果背後少不了的條件。</div><div class='gd-ex-line'>・<span class='gd-jp'>日々の努力なくして成功はあり得ない。</span>（沒有每天的努力，就不可能成功）</div><div class='gd-ex-line'>・<span class='gd-jp'>信頼関係なくして、いいチームは作れない。</span>（沒有互相信任，就打造不出好團隊）</div><div class='gd-ex-line'>・<span class='gd-jp'>苦労することなくして、本当の喜びは味わえない。</span>（不吃苦，就嘗不到真正的喜悅）</div><div class='gd-sec'><span class='gd-tag'>感謝致詞</span>回頭說「當初要不是有你們就辦不到」，後面常用過去式。</div><div class='gd-ex-line'>・<span class='gd-jp'>皆様のご協力なくしては、このプロジェクトは成功しませんでした。</span>（沒有各位的協助，這個計畫不可能成功）</div><div class='gd-sec'><span class='gd-tag'>評價</span>說某人或某事物的地位重要到不能不提。</div><div class='gd-ex-line'>・<span class='gd-jp'>彼の存在なくして、日本のサッカーの歴史は語れない。</span>（談日本足球史，不能不提到他）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・後面一定是「不可能、辦不到」。<b>不能</b>說「努力なくして成功した」，那是自相矛盾。<br>・不要加「を」：<span class='gd-jp'>財布をなくして困った</span>是「錢包弄丟了很困擾」，那是動詞<span class='gd-jp'>なくす</span>（弄丟），跟這個文法無關。<br>・前面要放<b>真的很重要</b>的東西，像努力、愛、協助、信任。拿雨傘這種小事來說，聽起來會很誇張，日常講<span class='gd-jp'>傘がないと出かけられない</span>就好。<br>・它很硬，朋友聊天不會用。口語說「〜がなかったら、〜できない」就好。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>同樣是在感謝大家幫忙：<br><b>なくしては</b>＝沒有～就辦不到（最正式）：<span class='gd-jp'>皆様の協力なくしては、成功できませんでした。</span><br><b>なしには</b>＝意思幾乎一樣，稍微沒那麼硬：<span class='gd-jp'>皆様の協力なしには、成功できませんでした。</span><br><b>あっての</b>＝反過來講，「有A才有B」：<span class='gd-jp'>皆様の協力あっての成功でした。</span>（多虧大家協助才有這次成功）</div><div class='gd-sec'>要注意，「なしに」不加は的時候還可以單純表示「沒做～就直接做了」：<span class='gd-jp'>連絡なしに休んだ。</span>（沒先說一聲就缺勤了）<br>なくして沒有這種用法，它只用在「少了它就不可能」。</div><div class='gd-warn'>判斷小訣竅：句子後面是「不可能、辦不到」，なくして和なしには都可以，なくして比較正式；後面是「就直接做了」，只能用なしに；想從「有」的角度講，用あっての。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>「〜あっての」（有A才有B）剛好是なくして的反面，兩個一起記最好用：<span class='gd-jp'>お客様あっての商売だ。</span>（有客人才有生意）</div>",
  "n1-57": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「にして」是很硬的<b>書面語</b>，有點像中文的「年過半百才…」「一夕之間」「身兼…」這類文言味道的說法。常見的意思有三種：<b>「到了～才」</b>（也包含「只有～才」）、<b>「一下子就」</b>、<b>「既是～也是」</b>。前兩種常帶「真不簡單／真沒想到」的感嘆；「既是～也是」只是把兩種身分或性質並列，語氣正式、端正，不一定有驚訝的意思。</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>基本上接名詞：<span class='gd-pair'><span class='gd-jp'>50歳</span> → <span class='gd-jp'>50歳にして</span></span><br>「既是～也是」的用法也常接な形容詞（像<span class='gd-jp'>簡潔な</span>這種後面帶な的形容詞），把な拿掉再接：<span class='gd-pair'><span class='gd-jp'>簡潔な</span> → <span class='gd-jp'>簡潔にして</span></span></div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>到了～才</span>前面放年紀、第幾次、第幾年這種「階段」，後面常接<span class='gd-jp'>初めて</span>、<span class='gd-jp'>ようやく</span>，表示「熬到這一步才終於…」。</div><div class='gd-ex-line'>・<span class='gd-jp'>三度目の挑戦にして、ようやく合格した。</span>（挑戰到第三次，才終於考上）</div><div class='gd-ex-line'>・<span class='gd-jp'>50歳にして初めて海外に行った。</span>（到了 50 歲才第一次出國）</div><div class='gd-sec'>後面接<span class='gd-jp'>なお</span>，就變成「都到這個階段了，還…」：</div><div class='gd-ex-line'>・<span class='gd-jp'>彼は90歳にしてなお現役の医者だ。</span>（他都 90 歲了，還在第一線看診）</div><div class='gd-sec'><span class='gd-tag'>只有～才</span>前面放人，表示「要這種人才辦得到」，常寫成「〜にして初めて」。</div><div class='gd-ex-line'>・<span class='gd-jp'>これは彼にして初めてできる仕事だ。</span>（這是只有他才做得到的工作）</div><div class='gd-ex-line'>・<span class='gd-jp'>この親にしてこの子あり。</span>（有其父必有其子）</div><div class='gd-sec'><span class='gd-tag'>一下子</span>接在<span class='gd-jp'>一瞬</span>、<span class='gd-jp'>一夜</span>這種很短的時間後面，表示「轉眼間就…」。口語會直接說<span class='gd-jp'>一瞬で</span>。</div><div class='gd-ex-line'>・<span class='gd-jp'>町は一瞬にして炎に包まれた。</span>（整個城鎮一瞬間就陷入火海）</div><div class='gd-ex-line'>・<span class='gd-jp'>彼女は一夜にしてスターになった。</span>（她一夜之間成了明星）</div><div class='gd-sec'><span class='gd-tag'>既是～也是</span>「AにしてB」＝同時具備 A 和 B。意思跟「で」一樣，<span class='gd-jp'>医者で作家</span>是平常講法，<span class='gd-jp'>医者にして作家</span>是正式的寫法。</div><div class='gd-ex-line'>・<span class='gd-jp'>彼は医者にして作家でもある。</span>（他既是醫生，也是作家）</div><div class='gd-ex-line'>・<span class='gd-jp'>説明は簡潔にして明快だった。</span>（說明簡潔又清楚）</div><div class='gd-sec'>另外，<span class='gd-jp'>幸いにして</span>（所幸）、<span class='gd-jp'>不幸にして</span>（不幸的是）是固定說法，當一個詞背起來就好：<br><span class='gd-jp'>幸いにして、けが人はいなかった。</span>（所幸沒有人受傷）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・「到了～才」前面要放<b>人生階段或次數</b>（年紀、第幾次、第幾年），不能隨便放時刻，像「3時にして」就不對。<br>・這是寫文章、演講、新聞的用語，跟朋友聊天用會很做作，口語用「で」「〜歳で初めて」就好。<br>・接な形容詞時要把な拿掉：是<span class='gd-jp'>簡潔にして</span>，不是「簡潔なにして」。<br>・別跟「〜にする」的て形搞混：<span class='gd-jp'>ジュースにして飲む</span>是「做成果汁來喝」，跟這個文法無關，要看前後文判斷。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'><b>にして</b>＝到了這個階段<b>才</b>發生某件事：<br><span class='gd-jp'>50歳にして初めてパソコンを買った。</span>（到了 50 歲才第一次買電腦）<br><b>にしては</b>＝「以～來說，算是很…」，在評論跟一般印象不一樣：<br><span class='gd-jp'>50歳にしては体力がある。</span>（以 50 歲來說，體力算很好）</div><div class='gd-warn'>判斷小訣竅：後面接「初めて／ようやく／なお」講一件事終於發生或依然如此，是にして；後面在評價「跟一般比起來怎樣」，是にしては。多了一個「は」，意思就差很多。</div>",
  "n1-59": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜には当たらない」就是<b>「用不著～」「犯不著～」</b>。用來冷靜地評論：這件事沒那麼嚴重，<b>那種反應太過頭了</b>，例如用不著驚訝、用不著難過、用不著罵人。很像中文說「這有什麼好大驚小怪的」，只是語氣比較正式，比較常出現在文章、評論或正式發言裡。</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>動詞辭書形（字典上查到的原形）＋には当たらない<br><span class='gd-pair'><span class='gd-jp'>驚く</span> → <span class='gd-jp'>驚くには当たらない</span></span>（用不著驚訝）<br><span class='gd-pair'><span class='gd-jp'>悲観する</span> → <span class='gd-jp'>悲観するには当たらない</span></span>（用不著悲觀）<br>講話客氣一點就說<span class='gd-jp'>〜には当たりません</span>。「は」有時候會省略，寫成<span class='gd-jp'>驚くに当たらない</span>，意思一樣。</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>評論反應太過頭</span>前面通常會先交代理由：「因為本來就是這樣」或「才這點程度」，後面再下結論：「所以用不著～」。</div><div class='gd-ex-line'>・<span class='gd-jp'>彼はずっと努力してきたのだから、合格したのも驚くには当たらない。</span>（他一直很努力，考上了也用不著驚訝）</div><div class='gd-ex-line'>・<span class='gd-jp'>一度失敗したくらいで、悲観するには当たらない。</span>（才失敗一次，用不著悲觀）</div><div class='gd-ex-line'>・<span class='gd-jp'>子どもが言ったことだから、そんなに責めるには当たらない。</span>（小孩子講的話，用不著那樣責怪）</div><div class='gd-h'>最常聽到的樣子</div><div class='gd-sec'>前面常放「反應」類的動詞：<span class='gd-jp'>驚く</span>、<span class='gd-jp'>嘆く</span>、<span class='gd-jp'>悲観する</span>、<span class='gd-jp'>責める</span>、<span class='gd-jp'>非難する</span>、<span class='gd-jp'>褒める</span>、<span class='gd-jp'>感心する</span>。<br>理由的部分常搭配<span class='gd-jp'>〜くらいで</span>（才這點程度就～）、<span class='gd-jp'>〜からといって</span>（就算因為～）、<span class='gd-jp'>〜のだから</span>（既然～）。</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・這裡的<span class='gd-jp'>当たる</span>跟「中獎」「打中」無關，整句要當成一個固定說法來記。<br>・前面接的是<b>對某件事的反應或評價</b>。像「用不著特地跑一趟」這種「不必麻煩去做某個動作」，日文通常用<span class='gd-jp'>〜には及ばない</span>，不用這個（下面會比較）。<br>・名詞接<span class='gd-jp'>に当たらない</span>常常是另一個意思：「不算是～、不構成～」。例如<span class='gd-jp'>これは違反には当たらない。</span>（這不算違規）。初學時先記<b>動詞辭書形＋には当たらない＝用不著～</b>就好。<br>・翻成「不值得～」容易讓人誤會成「這東西沒價值」。它真正的意思是「那種反應不必要、不合理」，翻成「用不著～」比較準確。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'><b>には及ばない</b>＝不用麻煩去做（常帶體貼，對對方說）<br>情境：部下犯了一個小錯。<br>主管對部下說：<span class='gd-jp'>わざわざ謝りに来るには及ばないよ。</span>（不用特地跑來道歉啦）<br>同事評論這件事：<span class='gd-jp'>一度のミスで、そこまで彼を責めるには当たらない。</span>（才一次失誤，用不著把他罵成那樣）</div><div class='gd-sec'><b>に足りない</b>＝對象本身份量不夠，不足以～<br>情境：明天要比賽。<br><span class='gd-jp'>あんな相手は恐れるに足りない。</span>（那種對手不足為懼：重點是對手太弱）<br><span class='gd-jp'>初めての試合だからといって、恐れるには当たらない。</span>（雖然是第一次比賽，也用不著害怕：重點是這種害怕沒必要）</div><div class='gd-warn'>判斷小訣竅：說「那種反應沒必要」用には当たらない；說「不必麻煩去做」用には及ばない；說「對象本身沒什麼份量」用に足りない。</div>",
  "n1-62": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜がてら」就是中文的<b>「順便～」「兼～」</b>。出一趟門，一次搞定兩件事：散步兼買麵包、送朋友去車站兼聊天。重點是<b>一個行動同時有兩個目的</b>，有一石二鳥的感覺。</div><div class='gd-h'>怎麼接</div><div class='gd-sec'><span class='gd-tag'>名詞＋がてら</span>最常見。前面放的是「動作」的名詞，像<span class='gd-jp'>散歩</span>、<span class='gd-jp'>買い物</span>、<span class='gd-jp'>見物</span>（觀光）、<span class='gd-jp'>運動</span>、<span class='gd-jp'>ドライブ</span>。<br><span class='gd-pair'><span class='gd-jp'>散歩</span> → <span class='gd-jp'>散歩がてら</span></span>（散步順便）</div><div class='gd-ex-line'>・<span class='gd-jp'>散歩がてら、パンを買ってきた。</span>（散步順便買了麵包回來）</div><div class='gd-ex-line'>・<span class='gd-jp'>花見がてら、久しぶりに実家に帰った。</span>（回了一趟好久沒回的老家，順便賞花）</div><div class='gd-sec'><span class='gd-tag'>ます形＋がてら</span>動詞把「ます」拿掉，直接加がてら。<br><span class='gd-pair'><span class='gd-jp'>送ります</span> → ます拿掉 → <span class='gd-jp'>送りがてら</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>駅まで送りがてら、ちょっと話そうか。</span>（我送你到車站，順便聊一下吧）</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'>後面那句通常是<b>要移動、要出門</b>的動作，像<span class='gd-jp'>行く</span>、<span class='gd-jp'>来る</span>、<span class='gd-jp'>寄る</span>（繞過去）、<span class='gd-jp'>歩く</span>、<span class='gd-jp'>出かける</span>。因為「順便」本來就是「反正都要出門了，就一起做」。</div><div class='gd-ex-line'>・<span class='gd-jp'>運動がてら、一駅歩いて帰った。</span>（當作運動，多走一站回家）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・前面要放<b>動作</b>。<span class='gd-jp'>散歩がてら</span>可以，「雨がてら」「休みがてら」這種不是動作的詞不能用。<br>・前後兩件事要是<b>同一個人</b>做的。<br>・它不算書面語，日常聊天也很常聽到，比<span class='gd-jp'>ついでに</span>稍微成熟一點而已。<br>・講的是<b>這一次</b>順便做，不是長期同時做兩件事。長期的要用<span class='gd-jp'>かたわら</span>。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>同樣是「去買東西，順便去郵局」：<br><b>ついでに</b>＝最口語、最好用，主要是去買東西，郵局是附帶的：<span class='gd-jp'>買い物のついでに、郵便局に寄った。</span><br><b>がてら</b>＝一趟出門兼兩個目的：<span class='gd-jp'>買い物がてら、郵便局に寄った。</span></div><div class='gd-sec'><b>かたがた</b>＝很正式，多用在拜訪、問候，常見於商務場合或書信：<span class='gd-jp'>お礼かたがた、ご挨拶に伺いました。</span>（來向您道謝，順便打聲招呼）<br><b>かたわら</b>＝長期一邊做本業、一邊做別的：<span class='gd-jp'>会社に勤めるかたわら、小説を書いている。</span>（一邊上班，一邊寫小說）<br><b>ながら</b>＝同一時間手上做兩個動作：<span class='gd-jp'>歩きながら電話する。</span>（邊走邊講電話）</div><div class='gd-warn'>判斷小訣竅：平常講「順便」用ついでに或がてら；跟客戶、長輩拜訪問候用かたがた；長期兩邊都在做用かたわら；身體同時做兩個動作用ながら。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>接著看<span class='gd-jp'>〜かたがた</span>和<span class='gd-jp'>〜かたわら</span>，三個一起記，考試的選擇題就很好分。</div>",
  "n1-64": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜ずくめ」就像中文的<b>「一身黑」「滿滿都是～」「清一色～」</b>。從頭到尾、整體看過去全是同一類東西，比如全身都穿黑的、一整年好事接連不斷、規定多到處處被管。</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>名詞直接加ずくめ，就這麼簡單。<br><span class='gd-pair'><span class='gd-jp'>黒</span> → <span class='gd-jp'>黒ずくめ</span></span><span class='gd-pair'><span class='gd-jp'>いいこと</span> → <span class='gd-jp'>いいことずくめ</span></span><span class='gd-pair'><span class='gd-jp'>規則</span> → <span class='gd-jp'>規則ずくめ</span></span><br>接好之後，用法跟一般名詞一樣：<br>後面接名詞要加「の」：<span class='gd-jp'>黒ずくめの男</span>（全身黑衣的男人）<br>放句尾加「だ」：<span class='gd-jp'>いいことずくめだ</span><br>句子還沒說完用「で」：<span class='gd-jp'>規則ずくめで、疲れる</span></div><div class='gd-h'>最常聽到的樣子</div><div class='gd-sec'>ずくめ<b>不是什麼名詞都能接</b>，日本人常用的就那幾個固定搭配，先把下面這些記熟最實在。</div><div class='gd-sec'><span class='gd-tag'>顏色、穿著</span>全身都是同一個顏色。</div><div class='gd-ex-line'>・<span class='gd-jp'>黒ずくめの男が店に入ってきた。</span>（一個全身黑衣的男人走進店裡）</div><div class='gd-sec'><span class='gd-tag'>好事</span>好事一件接一件。</div><div class='gd-ex-line'>・<span class='gd-jp'>今年は結婚に昇進に、いいことずくめだった。</span>（今年又結婚又升官，全是好事）</div><div class='gd-ex-line'>・<span class='gd-jp'>旅行中はごちそうずくめで、3キロも太った。</span>（旅行期間餐餐大餐，胖了足足 3 公斤）</div><div class='gd-sec'><span class='gd-tag'>規定、限制</span>到處都被管，通常帶著「被綁得很緊」的不滿。</div><div class='gd-ex-line'>・<span class='gd-jp'>うちの会社は規則ずくめで、息が詰まる。</span>（我們公司規定一大堆，悶到喘不過氣）</div><div class='gd-sec'><span class='gd-tag'>新聞常見</span>形容一件事有很多跟平常不一樣的地方。</div><div class='gd-ex-line'>・<span class='gd-jp'>今回の大会は異例ずくめだった。</span>（這次大會處處都是破例）</div><div class='gd-sec'>從上面可以看出來：ずくめ<b>本身不分好壞</b>，重點只在「整體清一色」。<span class='gd-jp'>黒ずくめ</span>是中性，<span class='gd-jp'>いいことずくめ</span>是正面，<span class='gd-jp'>規則ずくめ</span>就偏負面。</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・只能接<b>名詞</b>。想說「全是好吃的」，要講<span class='gd-jp'>美味しいものずくめ</span>或<span class='gd-jp'>ごちそうずくめ</span>，不能把形容詞直接接上去說成美味しいずくめ。<br>・<b>沾在身上的髒東西</b>不用ずくめ：「滿身泥巴」是<span class='gd-jp'>泥まみれ</span>，不能說泥ずくめ；「滿身大汗」是<span class='gd-jp'>汗まみれ</span>。<br>・<span class='gd-jp'>結構ずくめ</span>（條件好到挑不出毛病）常帶一點懷疑的口氣：<span class='gd-jp'>結構ずくめの話には気をつけたほうがいい。</span>（條件全是好處的事最好小心一點）<br>・偶爾會看到寫成「づくめ」，是同一個東西，現在一般寫ずくめ。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>同樣講一件衣服，看看三種說法差在哪：<br><b>ずくめ</b>＝整體清一色：<span class='gd-jp'>黒ずくめの服</span>（全身上下一身黑）<br><b>まみれ</b>＝表面沾滿液體或粉狀的東西，幾乎都是負面：<span class='gd-jp'>泥まみれの服</span>（衣服沾滿泥巴）<br><b>だらけ</b>＝某樣東西多到到處都是，大多是不好的東西：<span class='gd-jp'>しわだらけの服</span>（衣服到處都是皺摺）</div><div class='gd-warn'>判斷小訣竅：整體清一色（穿著、好事、規定等固定搭配）用ずくめ；黏在表面、沾得一身都是用まみれ；數量多到滿地都是用だらけ。</div>",
  "n1-63": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜まみれ」就是中文的<b>「一身泥」「滿身是汗」「沾滿了血」</b>。重點是泥、汗、血、灰塵這類東西<b>黏在表面、整片都沾到了</b>，而且通常是髒的、讓人不舒服的東西。</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>身上、東西上沾滿髒東西</span>最基本的用法。常跟它一起出現的字：<span class='gd-jp'>泥</span>、<span class='gd-jp'>汗</span>、<span class='gd-jp'>血</span>、<span class='gd-jp'>ほこり</span>（灰塵）、<span class='gd-jp'>油</span>。</div><div class='gd-ex-line'>・<span class='gd-jp'>泥まみれになって、子供と遊んだ。</span>（和孩子玩得一身泥）</div><div class='gd-ex-line'>・<span class='gd-jp'>汗まみれで家に帰ってきた。</span>（滿身大汗地回到家）</div><div class='gd-ex-line'>・<span class='gd-jp'>倉庫からほこりまみれのアルバムが出てきた。</span>（從倉庫翻出一本積滿灰塵的相簿）</div><div class='gd-sec'><span class='gd-tag'>比喻：被壞事纏住</span>也可以拿來說抽象的東西，像被債務、謊言整個包住、甩不掉。</div><div class='gd-ex-line'>・<span class='gd-jp'>彼は借金まみれだ。</span>（他負債累累）</div><div class='gd-ex-line'>・<span class='gd-jp'>あの人の話は嘘まみれだ。</span>（那個人講的話全是謊言）</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>很簡單，<b>名詞直接加まみれ</b>：<span class='gd-pair'><span class='gd-jp'>泥</span> → <span class='gd-jp'>泥まみれ</span></span><br>接好之後就把它當成一個名詞來用，最常見的樣子有這幾種：<br>・<span class='gd-jp'>〜まみれになる</span>：變得一身都是～<br>・<span class='gd-jp'>〜まみれだ</span>：（現在）滿身都是～<br>・<span class='gd-jp'>〜まみれで</span>：在滿身～的狀態下（去做某事）<br>・<span class='gd-jp'>〜まみれの＋名詞</span>：沾滿～的（東西）　例：<span class='gd-jp'>血まみれのシャツ</span>（沾滿血的襯衫）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・まみれ是「<b>沾上去、黏在表面</b>」的感覺，所以只是「數量很多」的東西不要用。人很多要說<span class='gd-jp'>人でいっぱい</span>或<span class='gd-jp'>人だらけ</span>，不說人まみれ。<br>・傷口、錯字這種不是「沾上去」的東西，一般用<span class='gd-jp'>だらけ</span>：<span class='gd-jp'>傷だらけ</span>、<span class='gd-jp'>間違いだらけ</span>。<br>・它是負面的。好事、漂亮的東西一般不用まみれ，「全身都是花」「滿滿的幸福」這種正面的意思要換別的說法。<br>・後面接名詞要加「の」：是<span class='gd-jp'>血まみれのシャツ</span>，不是血まみれシャツ。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'><b>だらけ</b>＝<b>很多、到處都是</b>（重點在數量多、散得到處都是）：<span class='gd-jp'>この作文は間違いだらけだ。</span>（這篇作文錯誤百出）<br><b>まみれ</b>＝<b>沾滿、整片黏在表面</b>（重點在被液體、粉狀的東西蓋住）：<span class='gd-jp'>顔が汗まみれだ。</span>（臉上全是汗）<br>泥、汗、血這類兩個都能說：<span class='gd-jp'>泥だらけ</span>、<span class='gd-jp'>泥まみれ</span>都可以，只是まみれ「黏得滿滿的」畫面感更強。</div><div class='gd-sec'><b>ずくめ</b>＝<b>從頭到尾清一色</b>（不一定負面，也可以是好事）：<span class='gd-jp'>黒ずくめの服</span>（一身全黑的打扮）、<span class='gd-jp'>いいことずくめ</span>（全是好事）<br><b>まみれ</b>則是被髒東西沾滿：<span class='gd-jp'>泥まみれの服</span>（沾滿泥巴的衣服）</div><div class='gd-warn'>判斷小訣竅：黏在身上、沾滿了→まみれ；數量多、到處都是→だらけ；清一色、全都是→ずくめ。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>同一組常被拿來比較的<span class='gd-jp'>〜ずくめ</span>（清一色、全是～），可以接著看，兩個一起記最不容易混。</div>",
  "n1-69": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜を皮切りに」就是中文的<b>「以～為首站」「從～打頭陣」</b>。像演唱會說「從台北場開始，接著跑全台巡迴」，台北場就是那個「皮切り」，也就是第一棒。重點是<b>後面還有一連串的事接著來</b>。</div><div class='gd-sec'>「皮切り」本來是指第一下艾灸，最燙、最痛的那一下，後來引申成「一連串事情的第一個」。</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>活動、巡迴</span>第一站開始，後面一站一站接下去。</div><div class='gd-ex-line'>・<span class='gd-jp'>東京公演を皮切りに、全国ツアーが始まった。</span>（以東京場為首站，全國巡迴開跑了）</div><div class='gd-sec'><span class='gd-tag'>事業擴大</span>從第一間店、第一個商品開始，越做越多。</div><div class='gd-ex-line'>・<span class='gd-jp'>この店は渋谷店を皮切りに、各地に店舗を増やしている。</span>（這家店從澀谷店起家，在各地陸續增加店面）</div><div class='gd-sec'><span class='gd-tag'>一個帶頭，其他跟上</span>某人先開口，大家就接連跟進。</div><div class='gd-ex-line'>・<span class='gd-jp'>彼の発言を皮切りに、次々と意見が出た。</span>（他一開口，大家的意見就接連冒出來）</div><div class='gd-sec'>後半句常會搭<span class='gd-jp'>次々と</span>（接二連三）、<span class='gd-jp'>相次いで</span>（相繼）、<span class='gd-jp'>各地で</span>（在各地）這類詞，用來表示「接下來還有很多」。</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>名詞直接接：<span class='gd-pair'><span class='gd-jp'>東京公演</span> → <span class='gd-jp'>東京公演を皮切りに</span></span><br>如果是一個動作，通常用「名詞的說法」：<span class='gd-jp'>発売</span>（開賣）、<span class='gd-jp'>開店</span>（開幕）、<span class='gd-jp'>発言</span>（發言）。<br>後面加「して」意思一樣，兩種都可以用；不加「して」的「を皮切りに」比較簡潔，書面上更常見：<span class='gd-jp'>東京公演を皮切りにして</span>。<br>另外也會看到<span class='gd-jp'>を皮切りとして</span>，意思相同。</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・<b>後面一定要有「一連串」</b>。只發生一件事就不能用：<span class='gd-jp'>入学を皮切りに、一人暮らしを始めた</span>是錯的，因為後面只有一件事，要改成<span class='gd-jp'>入学をきっかけに</span>。<br>・它不是單純的「從～開始」。講時間起點用「から」就好：<span class='gd-jp'>月曜日から仕事が始まる</span>，不要說成月曜日を皮切りに。<br>・<b>壞事的連鎖比較少用</b>。地震、事故這類事情接連發生，日本人一般不會用皮切り，大多用在活動、事業、比賽這種「一路展開」的事。<br>・語感偏正式，新聞、報導、介紹文很常見；跟朋友聊天比較少講。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>同樣都是一場演唱會，用不同文法，意思就差很多：<br><b>を皮切りに</b>＝這場是<b>第一站</b>，後面還有很多場：</div><div class='gd-ex-line'>・<span class='gd-jp'>そのライブを皮切りに、彼らは全国を回った。</span>（以那場演唱會為首站，他們跑遍了全國）</div><div class='gd-sec'><b>をきっかけに</b>＝因為這件事，<b>帶來某個改變</b>（不一定有一連串）：</div><div class='gd-ex-line'>・<span class='gd-jp'>そのライブをきっかけに、彼らは有名になった。</span>（因為那場演唱會，他們出名了）</div><div class='gd-sec'><b>を限りに</b>＝剛好相反，是<b>最後一次</b>，到此為止：</div><div class='gd-ex-line'>・<span class='gd-jp'>今日のライブを限りに、活動を休止する。</span>（今天的演唱會是最後一場，之後暫停活動）</div><div class='gd-warn'>判斷小訣竅：「第一站，後面一串接著來」用を皮切りに；「因為那件事而改變」用をきっかけに；「最後一次，到此結束」用を限りに。</div>",
  "n1-75": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜きらいがある」就是中文的<b>「有～的毛病」「有～的傾向」</b>，而且一定是<b>不好的</b>傾向。口氣很像老師在聯絡簿寫「該生做事有急躁之傾向」：明明在講缺點，但說得很客氣、很含蓄。多半出現在文章、評論，或比較正式的談話裡。</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>動詞辭書形＋きらいがある　<span class='gd-pair'><span class='gd-jp'>抱え込む</span> → <span class='gd-jp'>抱え込むきらいがある</span></span><br>動詞ない形＋きらいがある　<span class='gd-pair'><span class='gd-jp'>聞かない</span> → <span class='gd-jp'>聞かないきらいがある</span></span><br>名詞＋の＋きらいがある　<span class='gd-pair'><span class='gd-jp'>独断</span> → <span class='gd-jp'>独断のきらいがある</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>彼は何でも一人で抱え込むきらいがある。</span>（他有什麼事都自己一個人扛的毛病）</div><div class='gd-ex-line'>・<span class='gd-jp'>彼女は人の話を最後まで聞かないきらいがある。</span>（她有不把別人的話聽完的毛病）</div><div class='gd-ex-line'>・<span class='gd-jp'>彼のやり方は独断のきらいがある。</span>（他的做法有點獨斷）</div><div class='gd-h'>最常聽到的樣子</div><div class='gd-sec'><span class='gd-tag'>〜すぎるきらいがある</span>批評「做過頭」時特別常用。</div><div class='gd-ex-line'>・<span class='gd-jp'>うちの部長は細かいことを気にしすぎるきらいがある。</span>（我們部長有太在意小細節的毛病）</div><div class='gd-sec'><span class='gd-tag'>講一群人</span>評論某個族群、組織、社會的整體作風。</div><div class='gd-ex-line'>・<span class='gd-jp'>最近のニュースは話題性を重視しすぎるきらいがある。</span>（最近的新聞有太過重視話題性的傾向）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・漢字寫成「嫌い」，但這裡<b>跟「討厭」沒關係</b>，意思是「傾向、毛病」。現在多半直接寫平假名<span class='gd-jp'>きらい</span>。<br>・只能講<b>不好的</b>傾向。說人「很體貼」不能用它，要說<span class='gd-jp'>優しいところがある</span>。<br>・講的是一個人（或團體）<b>平常的作風、個性</b>，不是某一次發生的事。「他昨天遲到了」不能用きらいがある。<br>・接名詞一定要加「の」：是<span class='gd-jp'>独断のきらいがある</span>，不是「独断きらいがある」。<br>・語感偏硬。跟朋友聊天講「他很容易想太多」，用<span class='gd-jp'>考えすぎるところがある</span>或<span class='gd-jp'>考えすぎがちだ</span>比較自然。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>同樣在講一個人容易往壞處想：<br><b>がち</b>＝「常常～、容易～」，重點在<b>次數多</b>，日常會話就能用：<span class='gd-jp'>彼は物事を悲観的に考えがちだ。</span>（他常常把事情往悲觀想）<br><b>きらいがある</b>＝「有～的毛病」，帶有<b>委婉評論</b>對方性格的味道，偏文章：<span class='gd-jp'>彼は物事を悲観的に考えるきらいがある。</span>（他有把事情往悲觀想的傾向）<br><b>気味</b>＝「有點～的感覺」，講<b>眼前的輕微狀態</b>，不是性格：<span class='gd-jp'>最近、ちょっと疲れ気味だ。</span>（最近有點累累的）<br>另外，がち也能講天氣、自然現象（<span class='gd-jp'>冬は空気が乾燥しがちだ</span>，冬天空氣容易乾燥），きらいがある基本上只拿來評論人或團體的作風。</div><div class='gd-warn'>判斷小訣竅：聊天說「常常～」用がち；說「有點～的感覺」用気味；寫評論、客氣地點出一個人或團體的「壞習慣」，用きらいがある。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>常跟「ともすると・ともすれば」（一不小心就～）一起出現：<span class='gd-jp'>人はともすると、楽な方を選ぶきらいがある。</span>（人一不小心就容易選輕鬆的那條路）</div>",
  "n1-80": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜にとどまらず」就是中文新聞常講的<b>「不僅限於～，還擴及到～」</b>。<span class='gd-jp'>とどまる</span>是「停在原地」，<span class='gd-jp'>とどまらず</span>就是「沒有停在那裡」。前面先講一個比較小的範圍，後面接更大的範圍，像水波一圈一圈往外擴散。</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>範圍擴大</span>最常用在影響、災情、人氣、活動這類會「擴散」的東西。新聞、報告、演講很常見，屬於書面又正式的說法。</div><div class='gd-ex-line'>・<span class='gd-jp'>彼女の人気は日本にとどまらず、アジア全体に広がっている。</span>（她的人氣不只在日本，還擴及整個亞洲）</div><div class='gd-ex-line'>・<span class='gd-jp'>この問題は一つの会社にとどまらず、業界全体に関わる。</span>（這個問題不只牽涉一家公司，還關係到整個業界）</div><div class='gd-sec'><span class='gd-tag'>做的事更進一步</span>前面也可以放一個動作，意思是「不只做到～，還更進一步～」。</div><div class='gd-ex-line'>・<span class='gd-jp'>ボランティアたちは物資を届けるにとどまらず、被災者の話にも耳を傾けた。</span>（志工們不只送物資，還傾聽受災者的心聲）</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>名詞＋にとどまらず：<span class='gd-pair'><span class='gd-jp'>国内</span> → <span class='gd-jp'>国内にとどまらず</span></span><br>動詞辭書形（字典裡查得到的原形）＋にとどまらず：<span class='gd-pair'><span class='gd-jp'>届ける</span> → <span class='gd-jp'>届けるにとどまらず</span></span><br>也常看到加了「だけ」的<span class='gd-jp'>国内だけにとどまらず</span>，意思一樣，語氣更強調一點。</div><div class='gd-sec'>放在句尾或修飾名詞時，改成<b>にとどまらない</b>：</div><div class='gd-ex-line'>・<span class='gd-jp'>彼の才能は音楽にとどまらない。</span>（他的才華不僅限於音樂）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・是<span class='gd-jp'>とどまる</span>，不是<span class='gd-jp'>とまる</span>。<span class='gd-jp'>涙が止まらない</span>是「眼淚停不下來」，跟這個文法完全無關，別把「とど」漏掉。<br>・後面一定要接<b>更大的範圍</b>，常搭配「も」「まで」「へと」：<span class='gd-jp'>海外にも</span>、<span class='gd-jp'>全国へと</span>。只寫前半句，話會講不完。<br>・它很正式，日常小事不要用。「我不只吃拉麵，還吃了壽司」講<span class='gd-jp'>ラーメンだけじゃなくて、寿司も食べた</span>就好，用にとどまらず會像在念新聞稿。<br>・沒有否定的<span class='gd-jp'>にとどまる</span>本身也很常見，意思反過來，是「只停留在～」：<span class='gd-jp'>今回の値上げは一部の商品にとどまる。</span>（這次漲價只限於部分商品）</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>同樣講一部動畫很紅：<br><b>だけでなく</b>＝最普通的「不只～也～」，什麼場合都能用：<span class='gd-jp'>このアニメは子どもだけでなく、大人にも人気だ。</span>（這部動畫不只小孩，大人也喜歡）<br><b>に限らず</b>＝不限於某一類，<b>換成別的也一樣</b>：<span class='gd-jp'>このアニメは子どもに限らず、大人にも人気だ。</span>（不限小孩，大人也喜歡＝誰都喜歡）<br><b>にとどまらず</b>＝範圍<b>往外擴散</b>出去：<span class='gd-jp'>このアニメの人気は日本にとどまらず、世界中に広がっている。</span>（人氣不只在日本，還擴散到全世界）<br><b>はおろか</b>＝前面的不用說，<b>連最誇張的</b>都～：<span class='gd-jp'>このアニメは、子どもはおろか、お年寄りまで知っている。</span>（小孩就不用說了，連老人家都知道）</div><div class='gd-warn'>判斷小訣竅：影響、範圍「越擴越大」用にとどまらず；「不限哪一類」用に限らず；「連最極端的都」用はおろか；拿不準就用だけでなく，最安全。</div>",
  "n1-81": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜すら」就是中文的<b>「連～都…」</b>。先舉一個最基本、最不可能出問題的例子，用它來凸顯情況有多誇張：<span class='gd-jp'>名前すら知らない</span>，連名字都不知道，那其他的就更不用說了。意思跟「さえ」差不多，但<b>口氣比較硬、比較書面</b>，常出現在文章、新聞、評論裡。</div><div class='gd-h'>怎麼接</div><div class='gd-sec'><span class='gd-tag'>名詞＋すら</span>最基本的接法。原本的「が」「を」直接被すら取代。<br><span class='gd-pair'><span class='gd-jp'>時間がない</span> → <span class='gd-jp'>時間すらない</span></span>（連時間都沒有）</div><div class='gd-ex-line'>・<span class='gd-jp'>忙しくて、食事する時間すらない。</span>（忙到連吃飯的時間都沒有）</div><div class='gd-sec'><span class='gd-tag'>名詞＋ですら</span>前面是「人」、而且這個人是做動作的一方時很常用。這裡的「で」不是「在」的意思，把「ですら」整組記起來就好。</div><div class='gd-ex-line'>・<span class='gd-jp'>専門家ですら答えられない問題だ。</span>（這是連專家都答不出來的問題）</div><div class='gd-ex-line'>・<span class='gd-jp'>子どもですら知っていることだ。</span>（這是連小孩都知道的事）</div><div class='gd-sec'><span class='gd-tag'>名詞＋に・と等＋すら</span>「に」「と」這類助詞要留著，すら加在後面。</div><div class='gd-ex-line'>・<span class='gd-jp'>このことは親にすら話していない。</span>（這件事我連父母都沒說）</div><div class='gd-sec'><span class='gd-tag'>て形＋すらいない</span>強調的是<b>動作本身</b>：連「做」這一步都還沒做。</div><div class='gd-ex-line'>・<span class='gd-jp'>彼はメールを読んですらいない。</span>（那封信他連讀都沒讀）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・すら<b>不是只能配否定</b>。大多數時候後面接「ない」，但像<span class='gd-jp'>子どもですら知っている</span>這種肯定句也很自然。<br>・「に」「と」不能省：要說<span class='gd-jp'>親にすら</span>，不能說親すら話していない。<br>・<span class='gd-jp'>メールすら読んでいない</span>是「連信都沒讀」（重點在信），<span class='gd-jp'>メールを読んですらいない</span>是「連讀都沒讀」（重點在讀這個動作），すら放的位置不同，強調的東西就不同。<br>・すら口氣偏硬，平常跟朋友聊天講<span class='gd-jp'>名前も知らない</span>或<span class='gd-jp'>名前さえ知らない</span>比較自然。<br>・すら常帶著「驚訝、傻眼、批評」的感覺，拿來稱讚人的時候不多。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'><b>すら</b>和<b>さえ</b>在「連～都」的意思上幾乎可以互換：<br><span class='gd-jp'>名前すら知らない。</span>／<span class='gd-jp'>名前さえ知らない。</span>（連名字都不知道）<br>差別在於すら比較書面，而且さえ還有一個すら<b>沒有</b>的用法：「〜さえ〜ば」＝只要～就好。<br><span class='gd-jp'>時間さえあれば行ける。</span>（只要有時間就能去）<br>這句<b>不能</b>換成すら。</div><div class='gd-warn'>判斷小訣竅：「連～都」兩個都行，寫文章時用すら更有力道；「只要～就」只能用さえ。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>すら很常跟「<span class='gd-jp'>〜はおろか</span>」（別說～了）搭在一起，前面講難的、後面講簡單的：<br><span class='gd-jp'>漢字はおろか、ひらがなすら書けない。</span>（別說漢字了，連平假名都不會寫）</div>",
  "n1-1": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜に至っては」就是中文的<b>「至於～，更是…」「～更誇張，竟然…」</b>。先講大家或整體都怎麼樣，再從裡面挑出<b>最誇張的那一個</b>拿出來說。<br>就像你抱怨：「我們家每個人都很會賴床，<b>至於我爸，更誇張</b>，睡到中午都不起來。」</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>名詞＋に至っては。<br><span class='gd-pair'><span class='gd-jp'>父</span> → <span class='gd-jp'>父に至っては</span></span><span class='gd-pair'><span class='gd-jp'>数学</span> → <span class='gd-jp'>数学に至っては</span></span><br>整句的樣子通常是：<b>先講整體情況 → 〇〇に至っては → 最極端的事</b>。</div><div class='gd-ex-line'>・<span class='gd-jp'>うちの家族はみんな朝が弱い。父に至っては、昼まで起きてこない。</span>（我們家每個人早上都爬不起來，我爸更誇張，睡到中午都不起床。）</div><div class='gd-ex-line'>・<span class='gd-jp'>成績が悪く、数学に至っては赤点だ。</span>（成績很差，數學甚至不及格。）</div><div class='gd-ex-line'>・<span class='gd-jp'>会議では誰も意見を言わなかった。部長に至っては、最初から最後まで寝ていた。</span>（會議上沒人發表意見，部長更誇張，從頭睡到尾。）</div><div class='gd-sec'>後半句常會搭「<span class='gd-jp'>さえ</span>」「<span class='gd-jp'>まで</span>」「<span class='gd-jp'>一度も〜ない</span>」這種加強語氣的說法，讓「誇張感」更明顯。</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・前面一定要先有一個<b>整體</b>（一群人、幾個科目、整件事），才能「挑出最誇張的」。突然冒一句「父に至っては…」，前面什麼都沒講，日本人會聽不懂你在比什麼。<br>・幾乎都用在<b>不好的、讓人傻眼的事</b>。拿來誇人「他更厲害，考了滿分」聽起來會很怪。<br>・後面講的要真的是<b>最極端</b>的程度，只是普通程度的話，用這個句型會顯得小題大作。<br>・這是偏書面、正式的說法。跟朋友聊天比較常說「<span class='gd-jp'>父なんか、昼まで寝てるよ</span>」。<br>・唸法是<b>いたっては</b>，「至」唸いた。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'><b>に至っては</b>＝在整體裡<b>挑出最誇張的一個</b>（多為負面）：<br>・<span class='gd-jp'>部屋はどこも汚かった。台所に至っては、足の踏み場もなかった。</span>（每個房間都很髒，廚房更誇張，連站的地方都沒有。）<br><b>に至るまで</b>＝從A到B<b>全部都包含</b>，強調範圍很廣，好壞都能用：<br>・<span class='gd-jp'>リビングから台所に至るまで、全部きれいに掃除した。</span>（從客廳到廚房，全部都打掃乾淨了。）</div><div class='gd-sec'><b>ときたら</b>＝單純把某個人拿出來<b>抱怨</b>，前面不需要先講一群人，口氣比較口語、帶不滿：<br>・<span class='gd-jp'>うちの父ときたら、毎晩飲んで帰ってくる。</span>（說到我爸，每天晚上都喝完酒才回家。）<br>・<span class='gd-jp'>家族はみんなお酒好きだが、父に至っては毎晩飲んで帰ってくる。</span>（家裡每個人都愛喝酒，我爸更誇張，每天晚上都喝完才回家。）</div><div class='gd-warn'>判斷小訣竅：先講「大家都～」再說「其中某某更誇張」→ に至っては；「從A到B全部」→ に至るまで；單純「說到某某真是受不了」→ ときたら。</div>",
  "n1-4": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜たりとも…ない」就是中文的<b>「連一～都不…」</b>，而且是加重語氣的版本。像有人拍桌說「一毛錢都不給！」「一分鐘都不准浪費！」，那種<b>斬釘截鐵、絕不讓步</b>的口氣，日文就用たりとも。</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>公式很固定：<b>「一」＋量詞＋たりとも＋否定</b>。<br><span class='gd-pair'><span class='gd-jp'>一日</span> → <span class='gd-jp'>一日たりとも</span></span>（連一天）<br><span class='gd-pair'><span class='gd-jp'>一円</span> → <span class='gd-jp'>一円たりとも</span></span>（連一塊錢）<br><span class='gd-pair'><span class='gd-jp'>一人</span> → <span class='gd-jp'>一人たりとも</span></span>（連一個人）<br>後面<b>一定要接否定</b>：<span class='gd-jp'>〜ない</span>、<span class='gd-jp'>〜ません</span>、<span class='gd-jp'>〜できない</span>、<span class='gd-jp'>許されない</span>、<span class='gd-jp'>〜するな</span>這類。<br>最常見的組合：<span class='gd-jp'>一秒</span>、<span class='gd-jp'>一瞬</span>、<span class='gd-jp'>一日</span>、<span class='gd-jp'>一円</span>、<span class='gd-jp'>一人</span>、<span class='gd-jp'>一歩</span>、<span class='gd-jp'>一滴</span>、<span class='gd-jp'>一度</span>，都是「最小單位」，強調連這麼一點點都不行。</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>強烈的決心</span>自己絕對不要、不想做某件事。</div><div class='gd-ex-line'>・<span class='gd-jp'>残り時間、一秒たりとも無駄にしたくない。</span>（剩下的時間，我連一秒都不想浪費）</div><div class='gd-sec'><span class='gd-tag'>規定、命令</span>不准、不容許，主管、教練、告示很常用。</div><div class='gd-ex-line'>・<span class='gd-jp'>試合が終わるまで、一瞬たりとも気を抜くな。</span>（比賽結束前，一刻都不准鬆懈）</div><div class='gd-ex-line'>・<span class='gd-jp'>医療ミスは一件たりとも許されない。</span>（醫療疏失，一件都不容許發生）</div><div class='gd-sec'><span class='gd-tag'>強烈的感情</span>常跟「〜たことはない」一起，表達「從來沒有過」。</div><div class='gd-ex-line'>・<span class='gd-jp'>君のことを一日たりとも忘れたことはない。</span>（我沒有一天忘記過你）</div><div class='gd-h'>一個特別的固定說法</div><div class='gd-sec'><span class='gd-jp'>何人たりとも</span>＝「不管是誰都不准～」。這裡的何人要念<b>なんぴと</b>，是很硬的書面語，常出現在告示、小說、動漫台詞裡。</div><div class='gd-ex-line'>・<span class='gd-jp'>何人たりとも、ここに立ち入ることは許さない。</span>（不管是誰，都不准踏進這裡）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・前面只能是<b>「一」</b>：<span class='gd-jp'>二日たりとも</span>、<span class='gd-jp'>三人たりとも</span>都不對。要強調的就是「最小量」。<br>・後面<b>一定是否定</b>，不能說「一日たりとも休む」這種肯定句。<br>・量詞後面直接接たりとも，不要多加「も」或「の」：說成「一日もたりとも」是錯的。<br>・語氣很重、偏書面。日常聊天說<span class='gd-jp'>一円も払わない</span>就夠了，換成たりとも會像在發誓或宣言。<br>・單純描述事實（例如「教室裡一個學生都沒有」）用<span class='gd-jp'>一人もいなかった</span>比較自然；たりとも適合講決心、規定、強烈情緒。<br>・何人たりとも的何人念なんぴと，不是なんにん。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>同樣講「錢」，看三種說法：<br><b>一〜も…ない</b>＝單純說「連一個都沒有」，中性，生活用：<span class='gd-jp'>財布には一円もない。</span>（錢包裡一塊錢都沒有）<br><b>一〜たりとも…ない</b>＝帶著強烈主張、絕不讓步：<span class='gd-jp'>税金は一円たりとも無駄にできない。</span>（稅金連一塊錢都不能浪費）<br><b>すら</b>＝舉一個「最基本的東西」來強調，前面不必是「一＋量詞」：<span class='gd-jp'>今月は電車代すらない。</span>（這個月連搭電車的錢都沒有）</div><div class='gd-warn'>判斷小訣竅：只是陳述「一個都沒有」用も；「一＋量詞」再加上決心、禁止、絕不允許的口氣，用たりとも；舉出「連這麼基本的東西都～」用すら。</div>",
  "n1-5": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜であれ」就是中文的<b>「不管是～都…」「就算是～也…」</b>。像「不管是誰都要排隊」「就算是社長也要守規矩」：前面換成什麼都一樣，後面的結論不會變。它很正式，多半出現在新聞、演講、文章裡。</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>前面放<b>名詞</b>，直接加であれ：<span class='gd-pair'><span class='gd-jp'>社長</span> → <span class='gd-jp'>社長であれ</span></span><br>な形容詞去掉「な」，直接加であれ：<span class='gd-pair'><span class='gd-jp'>有名な</span> → <span class='gd-jp'>有名であれ</span></span><br>也可以放「誰、何、どんな～」這類問句用的詞：<span class='gd-pair'><span class='gd-jp'>誰</span> → <span class='gd-jp'>誰であれ</span></span><span class='gd-pair'><span class='gd-jp'>どう</span> → <span class='gd-jp'>どうであれ</span></span><br>「であれ」其實就是「である」（＝「だ」的書面說法，常用於文章）的命令形，但在這裡<b>不是要人去做什麼</b>，而是「隨便是什麼都一樣」的讓步用法，意思是「就算是～」。</div><div class='gd-h'>最常聽到的三種樣子</div><div class='gd-sec'><span class='gd-tag'>たとえ＋名詞＋であれ</span>就算是某個特別的身分或情況，也一樣。前面常加「たとえ」（就算）來加強。</div><div class='gd-ex-line'>・<span class='gd-jp'>たとえ子供であれ、自分のしたことには責任がある。</span>（就算是小孩，也要為自己做的事負責）</div><div class='gd-sec'><span class='gd-tag'>誰／何／どんな～＋であれ</span>不管是誰、不管是什麼，全部都一樣。</div><div class='gd-ex-line'>・<span class='gd-jp'>誰であれ、許可なく入ることはできない。</span>（不管是誰，沒有許可都不能進入）</div><div class='gd-ex-line'>・<span class='gd-jp'>理由はどうであれ、約束を破ったのは事実だ。</span>（不管理由是什麼，違背約定是事實）</div><div class='gd-sec'><span class='gd-tag'>AであれBであれ</span>不管是A還是B，結果都一樣。</div><div class='gd-ex-line'>・<span class='gd-jp'>男であれ女であれ、能力があれば評価される。</span>（不論男女，有能力就會被肯定）</div><div class='gd-ex-line'>・<span class='gd-jp'>晴れであれ雨であれ、試合は予定どおり行う。</span>（不管晴天還是下雨，比賽都照原定計畫舉行）</div><div class='gd-sec'>後半句通常是<b>不會因此改變的結論</b>，常見「〜できない」「許されない」「〜べきだ」「変わりはない」。</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・前面要放名詞或な形容詞語幹，動詞不能直接接：<b>不能說</b>「行くであれ」。前面想放動詞，要改用「〜ようが」或「〜にせよ」。<br>・它很硬，平常聊天講會很怪。口語改用「でも」，例如：<span class='gd-jp'>誰でも許可が必要だよ。</span>（不管是誰都需要許可喔）<br>・想說「誰都不能進」要用<span class='gd-jp'>誰も入れない</span>，不要說<span class='gd-jp'>誰でも入れない</span>（聽起來很不自然）。如果想說「不是誰都能進」，要講<span class='gd-jp'>誰でも入れるわけではない</span>。<br>・<span class='gd-jp'>であれ</span>跟<span class='gd-jp'>であれば</span>只差一個字，意思卻完全不同。であれば是「如果是～」：<span class='gd-jp'>社長であれば決められる。</span>（如果是社長就能決定）；であれ是「就算是～也」：<span class='gd-jp'>社長であれ、勝手には決められない。</span>（就算是社長也不能擅自決定）</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>同樣講「不管理由是什麼，遲到就是不行」：<br><b>であれ</b>：前面放名詞或な形容詞語幹，最正式。<br><span class='gd-jp'>どんな理由であれ、遅刻は許されない。</span><br><b>にせよ</b>：前面可以放名詞也可以放動詞，稍微沒那麼硬。<br><span class='gd-jp'>どんな理由にせよ、遅刻はよくない。</span><br><span class='gd-jp'>行くにせよ行かないにせよ、連絡してください。</span>（不管去不去，都請聯絡我）<br><b>ようが／ようと</b>：前面放動詞的意向形（〜う／〜よう的形），語氣是「再怎麼～都不管」。<br><span class='gd-jp'>どんな理由があろうと、遅刻は許されない。</span></div><div class='gd-warn'>判斷小訣竅：前面是名詞、場合很正式，用であれ；前面想放動詞，用にせよ或ようが。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>同樣是「A也好B也好」的句型還有「〜にせよ…にせよ」，以及固定說法「〜かれ〜かれ」：<span class='gd-jp'>多かれ少なかれ</span>（或多或少）、<span class='gd-jp'>遅かれ早かれ</span>（遲早）。</div>",
  "n1-6": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜とあれば」就是<b>「如果是～的話，那（我）就…」</b>。前面放的是一個<b>特別的、分量很重的理由</b>，像「為了孩子」「老闆的命令」「好朋友拜託」；後面接「那我願意做」或「那也只好做」。中文說「既然是為了孩子，再苦也甘願」，就是這種感覺。</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>名詞直接接：<span class='gd-pair'><span class='gd-jp'>子供のため</span> → <span class='gd-jp'>子供のためとあれば</span></span><br>な形容詞也是直接接：<span class='gd-pair'><span class='gd-jp'>必要</span> → <span class='gd-jp'>必要とあれば</span></span><br>動詞用普通形（字典上那個樣子，或ない形、た形）：<span class='gd-pair'><span class='gd-jp'>社長が来る</span> → <span class='gd-jp'>社長が来るとあれば</span></span></div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>甘願付出</span>為了重要的人或事，什麼都願意做。最常跟「のため」一起出現。</div><div class='gd-ex-line'>・<span class='gd-jp'>子供のためとあれば、親はどんな苦労も厭わない。</span>（只要是為了孩子，父母再辛苦都甘願）</div><div class='gd-ex-line'>・<span class='gd-jp'>家族のためとあれば、どんな仕事でもする。</span>（只要是為了家人，什麼工作我都做）</div><div class='gd-sec'><span class='gd-tag'>只好接受</span>對方的身分或情況特別，不做說不過去。</div><div class='gd-ex-line'>・<span class='gd-jp'>親友の頼みとあれば、断るわけにはいかない。</span>（既然是好朋友拜託，總不能拒絕）</div><div class='gd-ex-line'>・<span class='gd-jp'>社長の命令とあれば、従うしかない。</span>（既然是社長的命令，也只能照做）</div><div class='gd-h'>最常聽到的樣子</div><div class='gd-sec'>商務場合很常聽到這兩句固定說法：</div><div class='gd-ex-line'>・<span class='gd-jp'>必要とあれば、いつでもご連絡ください。</span>（如果有需要，請隨時跟我聯絡）</div><div class='gd-ex-line'>・<span class='gd-jp'>お客様のご希望とあれば、できる限り対応いたします。</span>（只要是客人希望的，我們會盡量配合）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・前面要是<b>有分量的理由</b>。普通的日常條件不用它：「下雨的話就帶傘」說<span class='gd-jp'>雨なら傘を持っていく</span>，說成「雨とあれば」很怪。<br>・後面通常接<b>決心或判斷</b>，像<span class='gd-jp'>何でもする</span>、<span class='gd-jp'>喜んで</span>、<span class='gd-jp'>しかない</span>、<span class='gd-jp'>わけにはいかない</span>，不是單純描述發生了什麼事。<br>・名詞後面直接接とあれば，不用另外加だ。<br>・語氣正式、偏書面。跟朋友聊天說<span class='gd-jp'>子供のためなら</span>就好，意思差不多，比較輕鬆。<br>・「為了」是從前面的<span class='gd-jp'>のため</span>來的，とあれば本身只是「如果是～」，不是每句都有「為了」的意思。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>「とあれば」「とあって」都是「と＋あ…」開頭，只差後面一點點；「ともなれば」也是と開頭，看起來也很像。用同一個「社長」情境來比：<br><b>とあれば</b>＝<b>如果是</b>～，那就…（假設，後面接決心）：<span class='gd-jp'>社長の命令とあれば、従うしかない。</span>（如果是社長的命令，也只能照做）<br><b>とあって</b>＝<b>因為是</b>～，所以…（已經發生的事實，後面描述狀況）：<span class='gd-jp'>社長の命令とあって、みんな必死に働いている。</span>（因為是社長下的命令，大家都拚命在做）<br><b>ともなれば</b>＝<b>一旦到了</b>～這個身分或程度，自然就…：<span class='gd-jp'>社長ともなれば、責任も重くなる。</span>（一旦當上社長，責任自然就重了）</div><div class='gd-warn'>判斷小訣竅：「如果是～我就願意／只好」用とあれば；「因為是～所以現在這樣」用とあって；「到了～這個地步就自然會」用ともなれば。</div>",
  "n1-7": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜をおいて」就是中文的<b>「非～莫屬」「除了～還有誰」</b>。說話的人先把一堆可能的人、事物想過一輪，最後認定：<b>真的只有這一個最適合</b>。它不只是在說「只有」，裡面還帶著很高的評價。</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>名詞＋<span class='gd-jp'>をおいて</span>＋<span class='gd-jp'>ほかに</span>〜<span class='gd-jp'>ない</span>／<span class='gd-jp'>いない</span><br>後面講人就用<span class='gd-jp'>いない</span>，講東西、時間、地方就用<span class='gd-jp'>ない</span>。<br><span class='gd-pair'><span class='gd-jp'>彼</span> → <span class='gd-jp'>彼をおいてほかにいない</span></span>（除了他沒有別人）<br><span class='gd-pair'><span class='gd-jp'>今</span> → <span class='gd-jp'>今をおいてほかにない</span></span>（除了現在沒有別的時機）</div><div class='gd-h'>最常聽到的樣子</div><div class='gd-sec'><span class='gd-tag'>講人</span>推薦人選、稱讚某人是唯一人選時最常用。</div><div class='gd-ex-line'>・<span class='gd-jp'>次のリーダーにふさわしいのは、山田さんをおいてほかにいない。</span>（最適合當下一任隊長的，非山田莫屬）</div><div class='gd-sec'><span class='gd-tag'>講時機</span><span class='gd-jp'>今をおいてほかにない</span>是固定說法，意思是「就是現在，錯過就沒了」。</div><div class='gd-ex-line'>・<span class='gd-jp'>留学するなら、今をおいてほかにない。</span>（要去留學，就是現在了）</div><div class='gd-sec'><span class='gd-tag'>反問</span>後面不一定是「ない」，也可以用「還有誰呢？」的反問語氣，意思一樣是「只有他」。</div><div class='gd-ex-line'>・<span class='gd-jp'>この役を演じられるのは、彼をおいて誰がいるだろうか。</span>（能演這個角色的，除了他還有誰呢）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・<b>不能拿來講單純的事實</b>。「房間裡除了他沒別人」只是客觀狀況，要說<span class='gd-jp'>部屋には彼以外誰もいなかった</span>，不能用をおいて。<br>・它通常用在<b>好的評價</b>，像「最適合」「最厲害」「只有他做得到」。拿來講壞事會很怪。<br>・<span class='gd-jp'>をおいて</span>跟<span class='gd-jp'>において</span>只差一個字，意思完全不同：<span class='gd-jp'>会議室において</span>是「在會議室」，表示場所或場合。<br>・這是比較正式、書面的講法，常見於文章、演講、新聞。跟朋友聊天直接說<span class='gd-jp'>彼しかいないよ</span>就好。<br>・<span class='gd-jp'>何をおいても</span>是另一個慣用說法，意思是「不管怎樣都優先」：<span class='gd-jp'>何をおいても駆けつける</span>（不管怎樣都會趕過去）。不要跟「除了～沒有別的」搞混。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>同樣在講一家很厲害的老店：<br><b>をおいて</b>＝在一堆候選人裡<b>挑出唯一一個</b>：<span class='gd-jp'>この味を出せるのは、あの店をおいてほかにない。</span>（做得出這個味道的，非那家店莫屬）<br><b>ならでは</b>＝某種特色<b>只有它才有</b>：<span class='gd-jp'>これはあの店ならではの味だ。</span>（這是那家店才有的味道）<br><b>以外</b>＝單純說<b>「除了～」</b>，不帶評價：<span class='gd-jp'>あの店以外で食べたことがない。</span>（除了那家店，我沒在別的地方吃過）</div><div class='gd-warn'>判斷小訣竅：在講「要選誰／選哪個，答案只有這個」，就用をおいて；在講「這個特色是它專屬的」，就用ならでは；只是客觀說「除了～」，就用以外。</div>",
  "n1-11": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜ならまだしも」就是中文的<b>「～也就算了，可是…」</b>。先退一步說「如果只是這樣，我還能接受」，再指出「但現在這個程度，真的不行」。整句的重點在後半：<b>你在抱怨、在表示無法接受</b>。</div><div class='gd-ex-line'>・<span class='gd-jp'>一度ならまだしも、三度も遅刻するなんて。</span>（一次也就算了，竟然遲到三次）</div><div class='gd-h'>拆開來看</div><div class='gd-sec'><span class='gd-jp'>まだしも</span>可以想成「<span class='gd-jp'>まだ</span>（還）＋<span class='gd-jp'>しも</span>（加強語氣）」，意思是「還算說得過去」。所以句子的結構固定是：<br><b>比較輕、還能忍的情況</b>＋ならまだしも、<b>比較嚴重、不能接受的情況</b>。<br>前面那個輕的情況，常常是「實際上並不是這樣」，只是拿來對比。像<span class='gd-jp'>冗談ならまだしも</span>，言下之意就是「你根本不是在開玩笑」。</div><div class='gd-h'>怎麼接</div><div class='gd-sec'><b>名詞</b>：直接接。<span class='gd-pair'><span class='gd-jp'>冗談</span> → <span class='gd-jp'>冗談ならまだしも</span></span><br><b>な形容詞</b>：不加だ，直接接。<span class='gd-pair'><span class='gd-jp'>下手</span> → <span class='gd-jp'>下手ならまだしも</span></span><br><b>動詞、い形容詞</b>：用普通形（就是不加ます、です的普通說法）。<span class='gd-pair'><span class='gd-jp'>知らない</span> → <span class='gd-jp'>知らないならまだしも</span></span></div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>對已經發生的事不滿</span></div><div class='gd-ex-line'>・<span class='gd-jp'>知らないならまだしも、知っていて黙っていたのは許せない。</span>（不知道也就算了，明明知道還不說，我不能原諒）</div><div class='gd-sec'><span class='gd-tag'>判斷還沒發生的情況</span>後半不一定是過去的事，也可以是對假設、未來的判斷。</div><div class='gd-ex-line'>・<span class='gd-jp'>夏はまだしも、冬はこの部屋じゃ無理だ。</span>（夏天還好，冬天住這個房間絕對不行）</div><div class='gd-sec'><span class='gd-tag'>拜託對方別再這樣</span>後半也可以接請求或禁止。</div><div class='gd-ex-line'>・<span class='gd-jp'>一日ならまだしも、毎日来るのはやめてほしい。</span>（一天也就算了，每天都來真的拜託不要）</div><div class='gd-h'>最常聽到的樣子</div><div class='gd-sec'>名詞後面也常直接用<span class='gd-jp'>はまだしも</span>，像上面的<span class='gd-jp'>夏はまだしも</span>，意思一樣。<br>另外，意思很接近的還有<span class='gd-jp'>ならともかく</span>，很多時候可以互換。</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・<b>順序不能顛倒</b>：前面放輕的、後面放嚴重的。說成<span class='gd-jp'>三度ならまだしも、一度遅刻するなんて</span>就不合邏輯了。<br>・名詞和な形容詞後面不要加だ：是<span class='gd-jp'>冗談ならまだしも</span>，不是冗談だならまだしも。<br>・後半要是負面的評價（<span class='gd-jp'>ありえない</span>、<span class='gd-jp'>許せない</span>、<span class='gd-jp'>無理だ</span>、<span class='gd-jp'>やめてほしい</span>這類），不能拿來稱讚或講好事。<br>・口氣是在抱怨、念人，對長輩或客人直接這樣講會有指責的感覺，要小心場合。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>同樣是看到一個大人為了小事哭：<br><b>ならまだしも</b>：<span class='gd-jp'>子どもならまだしも、大人がこんなことで泣くなんて。</span>（小孩也就算了，大人竟然為這種事哭）<br><b>ではあるまいし</b>：<span class='gd-jp'>子どもではあるまいし、こんなことで泣かないで。</span>（又不是小孩子，別為這種事哭）<br><b>ならまだしも</b>的重點在「前面還能接受，後面這個程度就不行」的<b>落差</b>，常用來抱怨或表示無法接受。<b>ではあるまいし</b>的重點在「又不是～」，<b>否定前面的前提</b>，再要求對方該怎麼做或下判斷。</div><div class='gd-warn'>判斷小訣竅：中文想講「A也就算了，B就太過分了」用ならまだしも；想講「又不是A，你應該…」用ではあるまいし。</div>",
  "n1-12": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「AこそあれB（ない）」就是中文的<b>「A是有，B可就沒有了」</b>，白話一點就是<b>「只有A，沒有B」</b>。像「對他只有感謝，沒有怨恨」這種話。它是很硬的書面語，日常聊天說「<span class='gd-jp'>Aはあっても、Bはない</span>」就好。</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>只有A沒有B</span>前後放一組<b>相反或對比</b>的東西，例如感謝和怨恨、批評和讚美。先承認A確實存在，重點在強調後面的B「根本沒有」。</div><div class='gd-ex-line'>・<span class='gd-jp'>彼には感謝こそあれ、恨みは少しもない。</span>（對他只有感謝，一點怨恨也沒有）</div><div class='gd-ex-line'>・<span class='gd-jp'>彼の行動には批判こそあれ、賞賛の声はほとんど聞かれない。</span>（對他的行為只有批評，幾乎聽不到讚美）</div><div class='gd-sec'><span class='gd-tag'>固定說法</span><span class='gd-jp'>程度の差こそあれ</span>、<span class='gd-jp'>多少の違いこそあれ</span>＝「雖然程度上有差別，但……」。這時後半<b>不一定是否定</b>，常用來說「大家其實都一樣」。</div><div class='gd-ex-line'>・<span class='gd-jp'>程度の差こそあれ、誰にでも悩みはある。</span>（雖然程度不同，但每個人都有煩惱）</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>名詞直接加こそあれ：<span class='gd-pair'><span class='gd-jp'>感謝</span> → <span class='gd-jp'>感謝こそあれ</span></span><span class='gd-pair'><span class='gd-jp'>批判</span> → <span class='gd-jp'>批判こそあれ</span></span><br>後半常見的收尾是「<span class='gd-jp'>〜はない</span>」「<span class='gd-jp'>ほとんど〜ない</span>」「<span class='gd-jp'>〜ことはない</span>」。</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・前面要放<b>名詞</b>。動詞的辭書形不能直接接，說成「批判するこそあれ」是錯的。想用動詞，請改用下面的「こそすれ」，而且要用<b>ます形把ます拿掉</b>的樣子來接。<br>・它的意思<b>不是</b>「正因為有～」。這是舊式教材常見的誤解，「正因為」是另一個文法。<br>・前後兩邊要是同一個話題裡的對比組合。前後扯不上關係，例如「祭典有樸素感，但沒有衰退跡象」，日本人聽起來會覺得怪。<br>・語氣很正式，常出現在文章、評論、演講裡。跟朋友講會像在念公文。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'><b>こそすれ</b>也是「只有A，沒有B」，差在前面接的是<b>動作</b>。<br>接法：<b>動詞ます形（把ます拿掉）＋こそすれ</b><br><span class='gd-pair'><span class='gd-jp'>上がります</span> → 把ます拿掉 → <span class='gd-jp'>上がりこそすれ</span></span><br><span class='gd-pair'><span class='gd-jp'>褒められます</span> → 把ます拿掉 → <span class='gd-jp'>褒められこそすれ</span></span><br>する動詞可以用「名詞＋こそすれ」，也可以用「し＋こそすれ」：<span class='gd-pair'><span class='gd-jp'>感謝します</span> → <span class='gd-jp'>感謝こそすれ</span>／<span class='gd-jp'>感謝しこそすれ</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>物価は上がりこそすれ、下がることはないだろう。</span>（物價只會漲，不會跌吧）</div><div class='gd-ex-line'>・<span class='gd-jp'>褒められこそすれ、叱られる理由はない。</span>（該被稱讚才對，沒有理由挨罵）</div><div class='gd-sec'>同一個情境對照看：<br><span class='gd-jp'>彼女には感謝こそあれ、恨みはない。</span>（心裡<b>有</b>的是感謝：講「存在」）<br><span class='gd-jp'>彼女には感謝こそすれ、恨むことはない。</span>（我<b>會做</b>的是感謝：講「動作」）<br>兩句的中文意思幾乎一樣。</div><div class='gd-sec'>另外，「正因為～才～」是<span class='gd-jp'>〜ばこそ</span>；「只有～才～」是<span class='gd-jp'>〜てこそ</span>，例如<span class='gd-jp'>努力してこそ成功できる</span>（只有努力才能成功）。不要因為都有こそ，就跟こそあれ混在一起。</div><div class='gd-warn'>判斷小訣竅：前面是<b>名詞</b>（感謝、批判、差）就用こそあれ；前面是<b>動詞</b>就用こそすれ，而且動詞要先變成ます形再把ます拿掉，例如「上がり（こそすれ）」「褒められ（こそすれ）」「感謝し（こそすれ）」，千萬不要寫成「褒められるこそすれ」。</div>",
  "n1-13": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜まで（のこと）だ」就像我們說的<b>「大不了就～嘛」</b>和<b>「我只是～而已啦」</b>。<span class='gd-jp'>まで</span>本來是「到」，這裡可以想成<b>「事情頂多就到這一步，沒什麼大不了」</b>。前面接辭書形還是た形，意思不一樣，下面分開講。</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>辭書形：大不了就～</span>計畫行不通的時候，你已經想好退路，而且一副「沒差，就這樣做」的態度。前面很常有「〜なら」「〜ば」「〜ても」，先講假如不順利。</div><div class='gd-ex-line'>・<span class='gd-jp'>だめなら、また一からやり直すまでだ。</span>（不行的話，大不了從頭再來）</div><div class='gd-ex-line'>・<span class='gd-jp'>誰も手伝ってくれないなら、一人でやるまでだ。</span>（沒人要幫忙的話，我自己做就是了）</div><div class='gd-ex-line'>・<span class='gd-jp'>電車が動かなければ、歩いて帰るまでのことだ。</span>（電車停駛的話，大不了走路回去）</div><div class='gd-sec'><span class='gd-tag'>た形：只不過是～而已</span>解釋自己做過的事，表示「沒有別的意思」「沒什麼了不起」。被人道謝的時候很常用，聽起來謙虛。</div><div class='gd-ex-line'>・<span class='gd-jp'>当然のことをしたまでです。</span>（我只是做了該做的事而已）</div><div class='gd-ex-line'>・<span class='gd-jp'>念のため、確認したまでです。</span>（我只是保險起見確認一下而已）</div><div class='gd-ex-line'>・<span class='gd-jp'>思ったことを言ったまでだ。</span>（我只是把心裡想的說出來罷了）</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>動詞辭書形＋までだ／までのことだ：<span class='gd-pair'><span class='gd-jp'>やり直す</span> → <span class='gd-jp'>やり直すまでだ</span></span><br>動詞た形＋までだ／までのことだ：<span class='gd-pair'><span class='gd-jp'>した</span> → <span class='gd-jp'>したまでです</span></span><br>加不加「<span class='gd-jp'>のこと</span>」意思一樣，加了更有「就這樣而已」的感覺。要講得客氣，把<span class='gd-jp'>だ</span>換成<span class='gd-jp'>です</span>就好。</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・這裡的<span class='gd-jp'>まで</span>不是「到～為止」。<span class='gd-jp'>帰るまで</span>單獨出現是「到回家為止」，要看後面有沒有接<span class='gd-jp'>だ</span>收尾。<br>・辭書形和た形不要接錯：<span class='gd-jp'>やり直すまでだ</span>是「大不了重做」（還沒做），<span class='gd-jp'>やり直したまでだ</span>是「我只是重做了而已」（已經做了）。<br>・辭書形的用法帶有「豁出去」的語氣，通常是講<b>自己</b>這一方的決心，不是拿來叫別人去做。<br>・前面接的通常是「本來不是首選、但也沒關係」的備案，不是什麼值得高興的好事。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'><b>〜までだ</b>＝大不了就去做：<span class='gd-jp'>聞かれたら、説明するまでだ。</span>（被問到的話，解釋就是了）<br><b>〜までもない</b>＝根本不必做：<span class='gd-jp'>簡単だから、説明するまでもない。</span>（很簡單，不用特別解釋）</div><div class='gd-sec'><b>〜までだ</b>＝還有退路，很樂觀：<span class='gd-jp'>失敗したら、またやるまでだ。</span>（失敗了大不了再來）<br><b>〜ばそれまでだ</b>＝一旦那樣就全完了，很悲觀：<span class='gd-jp'>一度失敗すれば、それまでだ。</span>（只要失敗一次就完了）</div><div class='gd-warn'>判斷小訣竅：「動詞＋までだ」是還有路可走；「それまでだ」是路斷了；「までもない」是不用走這條路。</div>",
  "n1-17": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜そばから」就是中文的<b>「前腳才剛～，後腳就又～」</b>。你這邊才在做，那邊馬上被打回原形，而且<b>每次都這樣</b>，等於在做白工。想像你剛拖完地，小孩馬上穿著拖鞋踩過去，拖一次踩一次，那種無力感就是そばから。</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>動詞的辭書形或た形，後面直接加そばから。<br><span class='gd-pair'><span class='gd-jp'>片付ける</span> → <span class='gd-jp'>片付けるそばから</span></span>（這邊才在收拾）<br><span class='gd-pair'><span class='gd-jp'>覚えた</span> → <span class='gd-jp'>覚えたそばから</span></span>（才剛背完）<br>兩種意思差不多。硬要分的話，辭書形比較像「一邊做，一邊就被破壞」，た形比較像「才剛做完就被破壞」。</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>努力被抵銷</span>做了某件事，結果馬上被打回原形。</div><div class='gd-ex-line'>・<span class='gd-jp'>覚えたそばから忘れてしまう。</span>（才剛背完就忘了）</div><div class='gd-ex-line'>・<span class='gd-jp'>雪かきしたそばから、また積もっていく。</span>（才剛鏟完雪，又積起來了）</div><div class='gd-sec'><span class='gd-tag'>前面進、後面出</span>東西才來就馬上沒了，留不住。</div><div class='gd-ex-line'>・<span class='gd-jp'>稼ぐそばから使ってしまうので、全然貯金できない。</span>（賺多少就花多少，完全存不了錢）</div><div class='gd-ex-line'>・<span class='gd-jp'>掃除するそばから、犬が毛を落としていく。</span>（我這邊在打掃，狗就在那邊一直掉毛）</div><div class='gd-sec'>後半句常常會搭配<span class='gd-jp'>〜てしまう</span>、<span class='gd-jp'>〜ていく</span>，或是用被動的<span class='gd-jp'>〜される</span>（例：<span class='gd-jp'>子供に散らかされる</span>），用來表現「事情不受控制、我拿它沒辦法」的感覺。</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・そばから講的是<b>反覆發生</b>的事。只發生一次的事不能用，例如「我一到家就下雨了」不能說「家に着いたそばから雨が降り出した」。這種情況要用<span class='gd-jp'>とたん</span>或<span class='gd-jp'>や否や</span>。<br>・幾乎都用在<b>抱怨、無奈、白費力氣</b>的場面。好事一直來，一般不會用そばから。<br>・後半句是在描述「現實就是這樣」，不能接「我要～」「請～」這類意志或命令的說法。<br>・這裡的そば不是「蕎麦（蕎麥麵）」，是「旁邊」的意思。可以想成「才剛做，旁邊就馬上～」。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'><span class='gd-jp'>〜が早いか</span>和<span class='gd-jp'>〜や否や</span>也是「一～就～」，但它們講的是<b>某一次</b>的事，兩件事緊接著發生，不帶「白費」的意思。<br>同樣講領薪水：<br><b>そばから</b>：<span class='gd-jp'>給料が入るそばから使ってしまう。</span>（薪水一進來就被花掉，每個月都這樣）<br><b>や否や</b>：<span class='gd-jp'>給料が入るや否や、新しいスマホを買った。</span>（那次薪水一入帳，我就馬上買了新手機）</div><div class='gd-warn'>判斷小訣竅：「每次都這樣、做了等於白做」用そばから；「那一次，前一件事一發生，下一件馬上跟著來」用が早いか或や否や。</div>",
  "n1-21": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜んがため（に）」就是<b>「為了～，不惜一切」</b>。意思跟「ために」一樣是「為了」，但口氣強很多，有種「非達成不可」的拚勁。它很古風，平常聊天幾乎不講，比較常在小說、演講、評論文章裡看到。</div><div class='gd-h'>這個「ん」是什麼</div><div class='gd-sec'>這裡的「ん」<b>不是否定</b>，是古文裡表示「想要～、打算～」的字，意思接近現代的「〜う／〜よう」。「が」相當於「の」。所以<span class='gd-jp'>勝たんがため</span>大約就是「想要贏的那個目的」，也就是「為了贏」。</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>先把動詞變成ない形，<b>把ない拿掉</b>，再加「んがため（に）」。</div><div class='gd-sec'><b>第一類（五段動詞）</b>：<br><span class='gd-pair'><span class='gd-jp'>勝つ</span> → <span class='gd-jp'>勝たない</span> → <span class='gd-jp'>勝たんがため</span></span><br><span class='gd-pair'><span class='gd-jp'>守る</span> → <span class='gd-jp'>守らんがため</span></span><br><span class='gd-pair'><span class='gd-jp'>売る</span> → <span class='gd-jp'>売らんがため</span></span><br><span class='gd-pair'><span class='gd-jp'>言う</span> → <span class='gd-jp'>言わんがため</span></span>（う結尾的要變わ，跟ない形一樣）</div><div class='gd-sec'><b>第二類（一段動詞）</b>：<br><span class='gd-pair'><span class='gd-jp'>生きる</span> → <span class='gd-jp'>生きない</span> → <span class='gd-jp'>生きんがため</span></span><br><span class='gd-pair'><span class='gd-jp'>逃れる</span> → <span class='gd-jp'>逃れんがため</span></span></div><div class='gd-sec'><b>第三類</b>：<span class='gd-jp'>する</span>要變成<b>せ</b>，不是し。<br><span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>せんがため</span></span><br><span class='gd-pair'><span class='gd-jp'>優勝する</span> → <span class='gd-jp'>優勝せんがため</span></span><br>「来る」在這個句型裡幾乎看不到，不用特別記。</div><div class='gd-h'>最常聽到的樣子</div><div class='gd-sec'><span class='gd-tag'>んがために</span>放在句子前半，後面接「為此做了什麼」。</div><div class='gd-ex-line'>・<span class='gd-jp'>勝たんがために、彼は必死に練習した。</span>（為了贏，他拚了命地練習）</div><div class='gd-ex-line'>・<span class='gd-jp'>生きんがために、どんな仕事でもした。</span>（為了活下去，什麼工作都做過）</div><div class='gd-sec'><span class='gd-tag'>んがための＋名詞</span>修飾後面的名詞。<span class='gd-jp'>売らんがため</span>常帶負面意思，指「一心只想賣錢」。</div><div class='gd-ex-line'>・<span class='gd-jp'>売らんがための広告には、もううんざりだ。</span>（那種只想著賣東西的廣告，我已經受夠了）</div><div class='gd-sec'><span class='gd-tag'>んがためだ</span>放句尾，說明「那樣做，是為了～」。</div><div class='gd-ex-line'>・<span class='gd-jp'>彼が嘘をついたのは、自分を守らんがためだった。</span>（他會說謊，是為了保護自己）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・する是<b>せんがため</b>，寫成「しんがため」是錯的。<br>・「ん」不是否定：<span class='gd-jp'>勝たんがため</span>是「為了贏」，不是「為了不贏」。<br>・後半要是<b>有人刻意去做的事</b>，而且通常是同一個人自己想達成的目標，不能拿來講天氣、自然現象。<br>・後半不接「請你～」「去做～」：<span class='gd-jp'>合格せんがため、勉強しなさい</span>不自然，要說<span class='gd-jp'>合格するために、勉強しなさい</span>。<br>・用在小事上會很誇張好笑：買麵包去超商，講<span class='gd-jp'>パンを買うために</span>就好。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>同一個情境「為了考上，每天念書念到很晚」：<br><b>ために</b>＝一般的「為了」，什麼場合都能用：<span class='gd-jp'>合格するために、毎晩遅くまで勉強した。</span><br><b>べく</b>＝書面的「為了」，辭書形直接接，する可以變<span class='gd-jp'>すべく</span>：<span class='gd-jp'>合格すべく、毎晩遅くまで勉強した。</span><br><b>んがため</b>＝更古風、更有「拚死也要」的感覺：<span class='gd-jp'>合格せんがため、毎晩遅くまで勉強した。</span></div><div class='gd-sec'>另一個要小心的是<b>んばかりに</b>，前面的變法一模一樣，意思卻完全不同，是「簡直就要～的樣子」：<br><span class='gd-jp'>泣かんばかりに頼んだ。</span>（幾乎要哭出來似地拜託）</div><div class='gd-warn'>判斷小訣竅：「ん」後面接<b>がため</b>是「為了」，接<b>ばかり</b>是「幾乎要」。想表達「為了」：平常用ために，書面用べく，要寫出「不惜一切」的氣勢才用んがため。</div>",
  "n1-24": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜とあって」就是新聞、報導很愛用的<b>「因為是～這麼特別的狀況，所以果然…」</b>。像台灣新聞常說「適逢連假首日，機場湧現大批旅客」，那個「適逢～」的感覺就是它。前面講一個特別的日子或場合，後面講因此看到的場面、大家的反應。</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>特別的日子・場合</span>連假、特賣、煙火大會這種不是天天有的事，所以人特別多、特別熱鬧。</div><div class='gd-ex-line'>・<span class='gd-jp'>連休初日とあって、空港は大混雑だった。</span>（適逢連假第一天，機場擠得不得了）</div><div class='gd-ex-line'>・<span class='gd-jp'>年に一度のセールとあって、店の前には朝から長い列ができていた。</span>（因為是一年一次的特賣，店門口一大早就排了長長的人龍）</div><div class='gd-sec'><span class='gd-tag'>人的反應</span>因為狀況難得，當事人緊張、興奮、特別認真。</div><div class='gd-ex-line'>・<span class='gd-jp'>初めての海外旅行とあって、娘はずいぶん張り切っている。</span>（因為是第一次出國，女兒超級興奮）</div><div class='gd-ex-line'>・<span class='gd-jp'>人気歌手が来るとあって、会場には若い人が大勢集まった。</span>（因為有人氣歌手要來，會場聚集了一大堆年輕人）</div><div class='gd-h'>怎麼接</div><div class='gd-sec'><b>名詞</b>：直接接，一般不加「だ」。<br><span class='gd-pair'><span class='gd-jp'>連休</span> → <span class='gd-jp'>連休とあって</span></span><span class='gd-pair'><span class='gd-jp'>花火大会</span> → <span class='gd-jp'>花火大会とあって</span></span><br><b>動詞、い形容詞</b>：用普通形（就是不加ます、です的說法，過去式也可以）。<br><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来るとあって</span></span><span class='gd-pair'><span class='gd-jp'>優勝した</span> → <span class='gd-jp'>優勝したとあって</span></span><span class='gd-pair'><span class='gd-jp'>安い</span> → <span class='gd-jp'>安いとあって</span></span></div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・後面只能寫<b>實際看到的結果、狀況</b>，不能放自己的打算、邀約、請求。<br>×<span class='gd-jp'>連休とあって、旅行に行こう。</span><br>○<span class='gd-jp'>連休だから、旅行に行こう。</span>（因為連假，去旅行吧）<br>・前面要是<b>特別、難得</b>的事。太日常的理由聽起來很怪，像「肚子餓了所以買麵包」直接用「から」「ので」就好。<br>・名詞後面通常不加だ：要說<span class='gd-jp'>連休とあって</span>，不說連休だとあって。<br>・這是書面、新聞的口氣，跟朋友聊天講「〜から」「〜ので」比較自然。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>同樣是跟「社長」有關的情境：<br><b>とあって</b>＝因為是～，<b>所以看到這種結果</b>（已經發生的事）<br><span class='gd-jp'>社長が来るとあって、社員はみんな緊張している。</span>（因為社長要來，員工都很緊張）<br><b>とあれば</b>＝<b>如果是～的話</b>，就（願意）…（假設、條件）<br><span class='gd-jp'>社長の頼みとあれば、断るわけにはいかない。</span>（如果是社長拜託的，總不能拒絕）<br><b>にあって</b>＝<b>身處～的立場、狀況中</b><br><span class='gd-jp'>社長という立場にあって、そんな発言は許されない。</span>（身為社長，那種發言是不被允許的）</div><div class='gd-warn'>判斷小訣竅：「因為是～，所以（大家）果然…」是とあって；「如果是～的話」是とあれば；「身在～之中」是にあって。</div>",
  "n1-25": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜ばこそ」就是<b>「正因為～，才…」</b>，跟「からこそ」意思差不多，只是更正式、更像文章或演講裡的說法。很常用在「看起來不好的事，背後其實有好的理由」，例如「正因為愛你，才罵你」。</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>說出真正的理由</span>別人可能誤會你的行為，你想強調「我這麼做，是因為～」。</div><div class='gd-ex-line'>・<span class='gd-jp'>あなたを思えばこそ、厳しく言うのです。</span>（正因為為你著想，我才對你說重話）</div><div class='gd-ex-line'>・<span class='gd-jp'>信頼していればこそ、この仕事を任せたのです。</span>（正因為信任你，才把這份工作交給你）</div><div class='gd-sec'><span class='gd-tag'>有這個條件才做得到</span>強調某個好條件是關鍵。</div><div class='gd-ex-line'>・<span class='gd-jp'>若ければこそ、失敗を恐れずに挑戦できる。</span>（正因為年輕，才能不怕失敗去挑戰）</div><div class='gd-ex-line'>・<span class='gd-jp'>健康であればこそ、好きなことに挑戦できる。</span>（正因為身體健康，才能挑戰自己喜歡的事）</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>先把前面的詞變成「〜ば」的樣子，再加<b>こそ</b>。<br><b>第一類（五段動詞）</b>：最後一個音換成同一行的「え」段音，加ば。<br><span class='gd-pair'><span class='gd-jp'>思う</span> → う換成え → <span class='gd-jp'>思えばこそ</span></span><br><b>第二類（一段動詞）</b>：把る拿掉，加れば。<br><span class='gd-pair'><span class='gd-jp'>信じる</span> → <span class='gd-jp'>信じればこそ</span></span><br><b>第三類（する・来る）</b>：<span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>すればこそ</span></span><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来ればこそ</span>（くればこそ）</span><br>「〜ている」的話，把いる變成いれば：<span class='gd-pair'><span class='gd-jp'>案じている</span> → <span class='gd-jp'>案じていればこそ</span></span></div><div class='gd-sec'><b>い形容詞</b>：把い換成ければ。<span class='gd-pair'><span class='gd-jp'>若い</span> → <span class='gd-jp'>若ければこそ</span></span><br><b>名詞、な形容詞</b>：後面加であれば。<span class='gd-pair'><span class='gd-jp'>親</span> → <span class='gd-jp'>親であればこそ</span></span><span class='gd-pair'><span class='gd-jp'>健康</span> → <span class='gd-jp'>健康であればこそ</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>親であればこそ、子どもの幸せを願うのだ。</span>（正因為是父母，才會希望孩子幸福）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・這裡的「ば」<b>不是「如果」</b>，是「因為」。<span class='gd-jp'>思えばこそ</span>不是「如果想的話」，而是「正因為想著（你）」。這是古文留下來的用法，所以看起來跟條件形一模一樣。<br>・名詞、な形容詞不能直接接：要說<span class='gd-jp'>健康であればこそ</span>，不是「健康ばこそ」。<br>・語氣很正式，聊天時很少用。跟朋友講用<span class='gd-jp'>からこそ</span>就好，用ばこそ會像在念稿。<br>・前面的理由通常是正面、真心的（愛、信任、健康、努力），不太拿來講倒楣或負面的原因。<br>・後半句常用<span class='gd-jp'>のだ／のです</span>收尾，有「其實是這樣」的感覺，例句裡可以多注意。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'><b>からこそ</b>＝正因為～才…，口語、書面都能用：<span class='gd-jp'>好きだからこそ、厳しく言うんだよ。</span>（就是因為喜歡你，才講得比較重）<br><b>ばこそ</b>＝意思一樣，但更正式，多用在文章、演講：<span class='gd-jp'>愛すればこそ、厳しく言うのである。</span>（正因為愛，才會嚴厲地說）<br><b>あっての</b>＝「有了～才有…」，前面接名詞，重點是「沒有它就不成立」：<span class='gd-jp'>健康あっての人生だ。</span>（有健康才有人生）</div><div class='gd-warn'>判斷小訣竅：平常講話用からこそ；寫文章、致詞想講得莊重一點用ばこそ；要說「少了它就什麼都沒有」就用あっての。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>同樣是 N1 講原因的說法，還可以接著看<span class='gd-jp'>〜ゆえ（に）</span>（因為～，更書面）和<span class='gd-jp'>〜あっての</span>。</div>",
  "n1-26": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜手前」就是中文的<b>「話都說出口了，總不能…」「人家都在看，拉不下臉…」</b>。因為自己已經說了、做了什麼，或是有某些人在看，為了顧<b>自己的面子和立場</b>，只好這樣做，或是不能那樣做。</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>話都說出口了</span>前面放動詞，通常是自己已經說過、做過的事。因為說過了，現在不能打自己的臉。</div><div class='gd-ex-line'>・<span class='gd-jp'>引き受けた手前、途中でやめるわけにはいかない。</span>（既然都接下來了，總不能做到一半就放棄）</div><div class='gd-ex-line'>・<span class='gd-jp'>「絶対合格する」と言った手前、遊んでいられない。</span>（都誇下海口說「一定會考上」了，哪還能玩）</div><div class='gd-sec'><span class='gd-tag'>有人在看</span>前面放人，意思是「當著～的面」「顧慮～怎麼看我」。要顧的是<b>自己</b>在這些人眼中的形象。</div><div class='gd-ex-line'>・<span class='gd-jp'>みんなの手前、そんなことは言えない。</span>（當著大家的面，那種話說不出口）</div><div class='gd-ex-line'>・<span class='gd-jp'>子どもの手前、夫婦げんかはしないようにしている。</span>（顧慮到孩子，我們盡量不在孩子面前吵架）</div><div class='gd-sec'><span class='gd-tag'>自己的身分</span>用「〜である手前」講自己的身分，意思是「身為～，總不能…」。</div><div class='gd-ex-line'>・<span class='gd-jp'>教師である手前、生徒の前でたばこは吸えない。</span>（身為老師，總不能在學生面前抽菸）</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>動詞：直接接普通形（就是不加ます的說法）。最常見的是た形，辭書形、ている形也可以。<br><span class='gd-pair'><span class='gd-jp'>約束した</span> → <span class='gd-jp'>約束した手前</span></span><span class='gd-pair'><span class='gd-jp'>言っている</span> → <span class='gd-jp'>言っている手前</span></span><br>名詞：加「の」再接。<span class='gd-pair'><span class='gd-jp'>部下</span> → <span class='gd-jp'>部下の手前</span></span><br>後半句常常是「不得不」或「不能」的說法，例如<span class='gd-jp'>〜わけにはいかない</span>、<span class='gd-jp'>〜しかない</span>、<span class='gd-jp'>〜られない</span>、<span class='gd-jp'>〜ないといけない</span>。</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・它講的是<b>自己（或句子主語）</b>的面子和立場，不是在顧對方的面子。<span class='gd-jp'>部長は部下の手前、ミスを認めにくかった。</span>是部長在部屬面前拉不下臉，要顧的是部長自己的形象，不是部屬的面子。<br>・後半句幾乎都是「只好～」「不能～」這種被逼的感覺，不能接開心、期待的事。像「約束した手前、楽しみだ」就很怪。<br>・<span class='gd-jp'>手前</span>念<b>てまえ</b>。它本來是「這一側、前面一點」的意思，例如<span class='gd-jp'>駅の手前で降りる</span>（在快到車站的地方下車）。看到「名詞＋の手前」要看前後文：前面是人，後面是不能做、只好做的事，就是這個文法，不是在講位置。<br>・這是偏正式、書面一點的說法，日常聊天比較常聽到「言っちゃったし…」這種講法。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'><span class='gd-jp'>〜からには</span>、<span class='gd-jp'>〜以上</span>也翻成「既然～」，但重點不一樣：<br><b>からには／以上</b>＝既然～了，就應該、就要負責到底。重點是<b>道理和決心</b>。<br><b>手前</b>＝既然～了，不這樣做<b>會很沒面子</b>。重點是<b>別人怎麼看我</b>。</div><div class='gd-ex-line'>・<span class='gd-jp'>約束したからには、必ず行く。</span>（既然答應了，我就一定會去：講決心）</div><div class='gd-ex-line'>・<span class='gd-jp'>約束した手前、行かないわけにはいかない。</span>（都答應人家了，不去實在說不過去：講面子）</div><div class='gd-sec'>からには、以上後面可以接自己想做的事，手前就不行：<br><span class='gd-jp'>日本に来たからには、富士山に登りたい。</span>（既然來了日本，就想去爬富士山）<br>這句換成手前就不通，因為爬不爬富士山跟面子沒有關係。</div><div class='gd-warn'>判斷小訣竅：後面能補一句「不然很丟臉、說不過去」的，用手前；只是「既然～，就應該～」，用からには或以上。</div>",
  "n1-32": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜ところを」最常見的就是中文的<b>「百忙之中還麻煩您」「在您休息的時候打擾了」</b>。先點出「對方正處在某個狀態（很忙、在休息、很累）」，後面接<b>感謝或道歉</b>，是很正式的客套說法。另外它也能表示<b>「本來應該～，卻…」</b>。</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>客套：打擾到對方</span>前面放對方的狀況，後面放「謝謝」「不好意思」，或是對方為你做了什麼。商務電話、致詞、email 超常出現。</div><div class='gd-ex-line'>・<span class='gd-jp'>お忙しいところをありがとうございます。</span>（百忙之中，謝謝您）</div><div class='gd-ex-line'>・<span class='gd-jp'>お休みのところ、申し訳ありません。</span>（您休息的時候打擾，真抱歉）</div><div class='gd-ex-line'>・<span class='gd-jp'>お疲れのところ、すみません。少しだけいいですか。</span>（您累了還打擾，不好意思。可以佔用一點時間嗎）</div><div class='gd-sec'><span class='gd-tag'>本來應該～卻</span>前面說「照理來講會怎樣」，後面說實際上變成另一個樣子，通常是對自己有利的事。</div><div class='gd-ex-line'>・<span class='gd-jp'>本来ならこちらから伺うべきところを、わざわざお越しいただきました。</span>（本來應該由我們登門拜訪，卻勞您特地跑一趟）</div><div class='gd-ex-line'>・<span class='gd-jp'>普通なら罰金のところを、今回は注意だけで済んだ。</span>（一般來說要罰錢，這次只被警告就沒事了）</div><div class='gd-h'>怎麼接</div><div class='gd-sec'><b>動詞</b>：直接接。<br><span class='gd-pair'><span class='gd-jp'>休んでいる</span> → <span class='gd-jp'>休んでいるところを</span></span><br><span class='gd-pair'><span class='gd-jp'>伺うべき</span> → <span class='gd-jp'>伺うべきところを</span></span><br><b>い形容詞</b>：直接接，客套時前面常加お。<br><span class='gd-pair'><span class='gd-jp'>忙しい</span> → <span class='gd-jp'>お忙しいところを</span></span><br><b>な形容詞</b>：加な再接。<br><span class='gd-pair'><span class='gd-jp'>大変</span> → <span class='gd-jp'>大変なところを</span></span><br><b>名詞</b>：加の再接。<br><span class='gd-pair'><span class='gd-jp'>お休み</span> → <span class='gd-jp'>お休みのところを</span></span><br><span class='gd-pair'><span class='gd-jp'>ご多忙</span> → <span class='gd-jp'>ご多忙のところを</span></span><br>講話時「を」常常省略，說成<span class='gd-jp'>お忙しいところ</span>也完全可以。</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・い形容詞後面不能加の：是<span class='gd-jp'>お忙しいところ</span>，不是お忙しいのところ。名詞才要加の。<br>・這是很正式的說法，對朋友講「お忙しいところを」會變得很生疏。朋友之間說<span class='gd-jp'>忙しいのにごめんね</span>就好。<br>・客套用法前面放的是<b>對方</b>的狀態，不是自己的。自己很忙還來幫忙，不會說「私の忙しいところを」。<br>・後面的事通常會<b>影響到對方</b>：打擾、麻煩、對方為你做了什麼。不能接跟對方無關的事。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'><b>ところを＋見る／見つかる</b>＝<b>被撞見的那個場面</b>，這是 N3 的「ところ」加上受詞的を，不是客套：<span class='gd-jp'>タバコを吸っているところを先生に見られた。</span>（抽菸的時候被老師看到了）<br><b>ところを（本來應該～卻）</b>＝照理會那樣，實際卻有好結果：<span class='gd-jp'>普通なら怒られるところを、許してもらった。</span>（一般來說會被罵，卻被原諒了）<br><b>ものを</b>＝「明明～就好了」，帶抱怨、遺憾，常放在句尾：<span class='gd-jp'>一言言ってくれればよかったものを。</span>（說一聲就好了嘛）</div><div class='gd-warn'>判斷小訣竅：後面是「見られた、見つかった」→ 被撞見的場面；後面是謝謝、抱歉或得到好處 → 客套／本來應該卻；整句在抱怨「早知道就～」→ ものを。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>意思很接近、也常用在客套的「中」：<span class='gd-jp'>お足元の悪い中、お越しいただきありがとうございます。</span>（天候不佳，感謝各位前來）</div>",
  "n1-35": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜の至り」就是中文的<b>「〜之至」</b>，像「榮幸之至」「感激之至」。日文說<span class='gd-jp'>光栄の至りです</span>，意思是「我真的榮幸到了極點」。這是很正式的講法，通常在典禮致詞、得獎感言、商業書信裡出現，平常跟朋友聊天不會這樣講。</div><div class='gd-h'>「至り」是什麼</div><div class='gd-sec'><span class='gd-jp'>至り</span>是動詞<span class='gd-jp'>至る</span>（到達）變成的名詞，意思是「走到最頂點」。所以<span class='gd-jp'>光栄の至り</span>＝光榮走到最頂點＝光榮到不行。</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>名詞＋の至り，句尾通常接です或でございます。<br><span class='gd-pair'><span class='gd-jp'>光栄</span> → <span class='gd-jp'>光栄の至りです</span></span><br><span class='gd-pair'><span class='gd-jp'>感激</span> → <span class='gd-jp'>感激の至りでございます</span></span><br>要特別注意，前面放的名詞<b>幾乎就是固定那幾個</b>，不是什麼名詞都能套進去。</div><div class='gd-h'>最常聽到的樣子</div><div class='gd-sec'><span class='gd-tag'>感謝・榮幸</span>最常見的是<span class='gd-jp'>光栄の至り</span>、<span class='gd-jp'>感激の至り</span>。</div><div class='gd-ex-line'>・<span class='gd-jp'>このような賞をいただき、光栄の至りです。</span>（能得到這樣的獎項，真是榮幸之至）</div><div class='gd-ex-line'>・<span class='gd-jp'>皆様から温かいお言葉をいただき、感激の至りです。</span>（收到各位溫暖的話，真是感激之至）</div><div class='gd-sec'><span class='gd-tag'>過意不去・慚愧</span>常見的是<span class='gd-jp'>恐縮の至り</span>（非常過意不去）、<span class='gd-jp'>赤面の至り</span>（慚愧到臉紅）。</div><div class='gd-ex-line'>・<span class='gd-jp'>お忙しいところお越しいただき、恐縮の至りでございます。</span>（百忙之中勞駕您前來，實在過意不去）</div><div class='gd-ex-line'>・<span class='gd-jp'>こんな初歩的なミスをしてしまい、赤面の至りです。</span>（犯了這麼基本的錯，真是慚愧至極）</div><div class='gd-sec'><span class='gd-tag'>特別的一個</span><span class='gd-jp'>若気の至り</span>的意思不太一樣，指的是「年輕不懂事所犯下的錯」。這裡的至り比較接近「造成的結果」。這句話常拿來回想以前做過的荒唐事，帶一點自嘲，不一定是正式場合。</div><div class='gd-ex-line'>・<span class='gd-jp'>学生時代は若気の至りで、ずいぶん無茶をした。</span>（學生時代年少輕狂，做了不少魯莽的事）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・前面要放<b>名詞＋の</b>，不能直接接形容詞。<span class='gd-jp'>嬉しいの至り</span>、<span class='gd-jp'>ありがたいの至り</span>都是錯的。想表達開心、感謝，就用<span class='gd-jp'>光栄</span>、<span class='gd-jp'>感激</span>這些固定搭配。<br>・不要自己隨便換名詞，背熟光栄・感激・恐縮・赤面・若気這幾個最安全。<br>・這個說法主要是講<b>自己</b>的心情，帶有謙虛的味道。用它描述別人的心情，例如說「部長很榮幸之至」，聽起來會很怪。<br>・它的語氣非常正式。跟朋友說<span class='gd-jp'>ケーキありがとう、感激の至り！</span>，聽起來會像在開玩笑、故意裝模作樣。<br>・<span class='gd-jp'>若気</span>念<span class='gd-jp'>わかげ</span>，不是わかき。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'><b>の至り</b>＝自己的感謝或慚愧到了極點，語氣謙虛：<span class='gd-jp'>お招きいただき、光栄の至りです。</span>（承蒙邀請，榮幸之至）<br><b>極まりない</b>＝某件事或某個態度「極度～」，多半拿來批評、抱怨：<span class='gd-jp'>連絡もなく欠席するなんて、失礼極まりない。</span>（連聯絡都沒有就缺席，實在失禮至極）<br><b>に至る</b>＝動詞，表示事情「發展到某個結果或地步」：<span class='gd-jp'>何度も話し合った結果、ようやく合意に至った。</span>（經過多次討論，終於達成共識）</div><div class='gd-warn'>判斷小訣竅：講自己心情的「～之至」用の至り，罵人或抱怨「極度～」用極まりない，講事情「演變到～」用に至る。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'><span class='gd-jp'>〜に堪えない</span>也是正式場合表達強烈心情的說法：<span class='gd-jp'>皆様のご支援には感謝に堪えません。</span>（對各位的支持感激不盡）</div>",
  "n1-41": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜といったらない」就是中文的<b>「～得沒話說」「～到不行」「～死了」</b>。字面上是「要說有多～，簡直找不到話來形容」，用來誇張地強調某種感覺強烈到極點。好的壞的都能講：高興到不行、冷到不行、丟臉死了，都可以用。</div><div class='gd-h'>怎麼接</div><div class='gd-sec'><b>名詞</b>＋といったらない（最常見的是把形容詞變成「～さ」的名詞）<br><span class='gd-pair'><span class='gd-jp'>寒い</span> → い換成さ → <span class='gd-jp'>寒さといったらない</span></span><br><b>い形容詞</b>：直接接<br><span class='gd-pair'><span class='gd-jp'>うれしい</span> → <span class='gd-jp'>うれしいといったらない</span></span><br><b>な形容詞</b>：不加な，直接接<br><span class='gd-pair'><span class='gd-jp'>退屈</span> → <span class='gd-jp'>退屈といったらない</span></span></div><div class='gd-sec'>講<b>過去</b>發生的事，改成「といったら<b>なかった</b>」。</div><div class='gd-ex-line'>・<span class='gd-jp'>初めて富士山を見た時の感動といったらなかった。</span>（第一次看到富士山時，那份感動真的無法形容）</div><div class='gd-ex-line'>・<span class='gd-jp'>毎日同じ作業ばかりで、退屈といったらない。</span>（每天都做一樣的事，無聊到不行）</div><div class='gd-h'>最常聽到的樣子</div><div class='gd-sec'><span class='gd-tag'>ったらない</span>「といったらない」的口語縮短版，跟朋友聊天、發牢騷時很常聽到，前面多半直接接い形容詞。</div><div class='gd-ex-line'>・<span class='gd-jp'>隣の工事、うるさいったらないよ。</span>（隔壁在施工，吵死了）</div><div class='gd-sec'><span class='gd-tag'>ったらありゃしない</span>更口語、更有情緒的說法，大多用在抱怨、丟臉、生氣。</div><div class='gd-ex-line'>・<span class='gd-jp'>みんなの前で転ぶなんて、恥ずかしいったらありゃしない。</span>（在大家面前跌倒，丟臉死了）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・這裡的「ない」<b>不是否定</b>。<span class='gd-jp'>うれしいといったらない</span>是「高興得不得了」，不是「不高興」。<br>・な形容詞不要加な：說<span class='gd-jp'>退屈といったらない</span>，不說退屈なといったらない。<br>・事情已經過去了，要用「といったらなかった」，不然聽起來像現在還在發生。<br>・前面通常放形容詞或名詞，尤其是「～さ」；動詞很少這樣直接接。<br>・「ったらない」「ったらありゃしない」很口語，正式場合或對上司不要用。<br>・別跟「といったら（說到～）」搞混：<span class='gd-jp'>日本といったら、やっぱり寿司だ。</span>（說到日本，果然就是壽司）後面沒有ない，意思完全不同。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'><b>〜ったら（n1-44）</b>：前面接<b>人</b>，意思是「我說那個～啊」，帶著無奈或抱怨，後面接一整句話。<br><span class='gd-jp'>うちの母ったら、また夜中に電話してきた。</span>（我媽真是的，又半夜打電話來）<br><span class='gd-jp'>うちの母、心配性ったらない。</span>（我媽愛操心到不行）</div><div class='gd-warn'>判斷小訣竅：「ったら」後面緊接著「ない」、前面是形容詞或「～さ」，就是在講程度；前面是人、後面接一句話，就是在抱怨那個人。</div><div class='gd-sec'><b>〜極まりない（n1-34）</b>：也是「～到極點」，但比較生硬、偏書面，大多用在負面評價，像新聞、客訴信。「といったらない」比較像在講自己的親身感受，正面負面都能用。<br><span class='gd-jp'>あの店員の態度は失礼極まりない。</span>（那個店員的態度失禮至極：像正式投訴）<br><span class='gd-jp'>あの店員の態度の悪さといったらなかった。</span>（那個店員態度差到不行：像在跟朋友講經歷）</div><div class='gd-warn'>判斷小訣竅：寫正式文章、嚴厲批評用「極まりない」；講自己的感受、帶點情緒誇張用「といったらない」。</div>",
  "n1-42": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「Aと言わずBと言わず」就是中文的<b>「不管是A還是B，全都～」</b>。舉出兩個有代表性的部分，讓人感覺到「<b>整個都是這樣</b>」。像中文說「手上、腳上全是泥巴」，其實是在說整個人都髒兮兮。</div><div class='gd-ex-line'>・<span class='gd-jp'>手と言わず足と言わず、泥だらけになった。</span>（不管手還是腳，全都沾滿了泥）</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>名詞＋と言わず＋名詞＋と言わず，<b>兩個名詞後面都要各接一個「と言わず」</b>。<br>「言わず」是「言わない」比較文言的說法，字面是「不說是A、也不說是B」，意思就是「A、B都不分」。也常寫成平假名<span class='gd-jp'>といわず</span>。</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>身體</span>從頭到腳、全身都是。</div><div class='gd-ex-line'>・<span class='gd-jp'>顔と言わず腕と言わず、蚊に刺されてしまった。</span>（臉上、手臂上，到處都被蚊子叮了）</div><div class='gd-sec'><span class='gd-tag'>地點</span>整個空間、整個地方都是。</div><div class='gd-ex-line'>・<span class='gd-jp'>壁と言わず床と言わず、部屋中に落書きがしてあった。</span>（牆上也好地上也好，整個房間都是塗鴉）</div><div class='gd-sec'><span class='gd-tag'>時間</span>不分時段，一直都是。</div><div class='gd-ex-line'>・<span class='gd-jp'>昼と言わず夜と言わず、工事の音が響いている。</span>（不管白天晚上，施工的聲音一直響個不停）</div><div class='gd-ex-line'>・<span class='gd-jp'>平日と言わず週末と言わず、この店はいつも行列ができている。</span>（不管平日還是週末，這家店總是在排隊）</div><div class='gd-sec'>你會發現後半句常出現<span class='gd-jp'>部屋中</span>、<span class='gd-jp'>町中</span>、<span class='gd-jp'>いつも</span>、<span class='gd-jp'>だらけ</span>這類「全部」的字眼，跟前面的「不分A、B」互相呼應。</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・兩個「と言わず」都要寫。<span class='gd-jp'>手と足と言わず</span>是錯的，要說<span class='gd-jp'>手と言わず足と言わず</span>。<br>・A跟B要是<b>同一類東西</b>，而且是某個整體的一部分（手和腳＝全身、白天和晚上＝整天）。隨便拿兩個不相關的東西湊在一起會很怪。<br>・它是拿來<b>描述實際看到的狀況</b>，而且常常是讓人吃驚、不太好的狀況（全身是泥、到處是傷、吵個不停）。<br>・這是書面、比較硬的說法，小說、報導比較常看到。平常聊天的話，日本人多半說<span class='gd-jp'>手も足も</span>、<span class='gd-jp'>どこもかしこも</span>。<br>・別跟單獨出現的「と言わず」搞混：<span class='gd-jp'>明日と言わず、今すぐ行こう。</span>（別說明天了，現在就去吧）這是「不用等到A」的意思，跟本文法不一樣。<br>・<span class='gd-jp'>何も言わずに帰った</span>（什麼都沒說就回去了）裡的「言わず」是真的「沒說話」，跟這個句型無關。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>同樣是「不管A還是B」，<span class='gd-jp'>Aであれ Bであれ</span>的感覺不一樣：<br><b>と言わず</b>＝<b>描述眼前的實際狀況</b>，到處都這樣：<br><span class='gd-jp'>駅前と言わず住宅街と言わず、どこも観光客であふれている。</span>（不管車站前還是住宅區，到處都擠滿觀光客）<br><b>であれ</b>＝<b>不管是哪一個，都適用同一個規定或判斷</b>：<br><span class='gd-jp'>駅前であれ住宅街であれ、ごみを捨ててはいけない。</span>（不管是車站前還是住宅區，都不可以亂丟垃圾）<br>第二句在講規定，換成と言わず就不自然了。</div><div class='gd-warn'>判斷小訣竅：在描述「放眼看去到處都是」，用と言わず；在說「不管哪種都一樣要～」的規定、判斷，用であれ。</div>",
  "n1-44": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「名詞＋ったら」就是中文的<b>「我們家那個齁，真是的…」</b>。先把一個身邊的人點出來，接著講他讓你又好氣又好笑的事。重點是<b>無奈、抱怨，但帶著親暱</b>，不是真的在罵人。</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>名詞後面直接加「ったら」，不用變化。<br><span class='gd-pair'><span class='gd-jp'>弟</span> → <span class='gd-jp'>弟ったら</span></span><span class='gd-pair'><span class='gd-jp'>お母さん</span> → <span class='gd-jp'>お母さんったら</span></span><span class='gd-pair'><span class='gd-jp'>あなた</span> → <span class='gd-jp'>あなたったら</span></span></div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>跟別人抱怨</span>跟朋友聊家人、同事、寵物的時候，用來帶出「他又來了」的話題。</div><div class='gd-ex-line'>・<span class='gd-jp'>うちの猫ったら、また私の椅子で寝てる。</span>（我家的貓真是的，又睡在我的椅子上）</div><div class='gd-ex-line'>・<span class='gd-jp'>父ったら、また眼鏡をなくしたの。</span>（我爸真是的，又把眼鏡弄丟了）</div><div class='gd-sec'><span class='gd-tag'>當面唸對方</span>直接叫對方，表示「你喔，真是的！」，常常配「もう」。</div><div class='gd-ex-line'>・<span class='gd-jp'>もう、お母さんったら！その話はしないでって言ったでしょ。</span>（唉唷，媽！不是叫你不要講那件事嗎）</div><div class='gd-ex-line'>・<span class='gd-jp'>田中さんったら、冗談ばっかり。</span>（田中你真是的，老愛開玩笑）</div><div class='gd-sec'>後面的話常常講一半就停，像<span class='gd-jp'>弟ったら、また忘れ物して…。</span>（我弟真是的，又忘東西了…），沒講完的部分就是那聲「唉」。</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・它<b>不是「如果」</b>。<span class='gd-jp'>雨が降ったら</span>的たら是「如果～的話」，名詞＋ったら是「說到～真是的」，兩個完全不同。<br>・語氣很口語、很親近，用在家人、朋友、寵物身上。對上司、客人當面講，或在正式場合講，都不適合。<br>・後面通常接<b>讓你傻眼、無奈、有點不好意思</b>的事。單純想誇人、謝謝人，用一般的「は」就好。要搭配好事時，也是「他太客氣了啦，真是的」這種害羞或無奈的感覺。<br>・ったら前面有個小小的っ，要停一拍念成「ったら」，不要念成「たら」。<br>・你也會聽到<span class='gd-jp'>お母さんってば</span>，語氣跟ったら很像，都是口語。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'><b>ったら</b>＝無奈裡帶著疼愛，也可以當面叫對方：<br><span class='gd-jp'>うちの子ったら、またゲームばっかり。</span>（我家小孩真是的，又在打電動）<br><b>ときたら</b>＝比較認真地數落，負面感比較重，多半是跟別人講，不會拿來當面叫對方：<br><span class='gd-jp'>うちの子ときたら、毎日ゲームばっかりで全然勉強しない。</span>（說到我家小孩，每天只會打電動，完全不念書）<br><b>ったらない</b>＝前面多半接形容詞，意思是「～得要命」，跟抱怨某個人無關：<br><span class='gd-jp'>あの時は恥ずかしいったらなかった。</span>（那時候真是丟臉得要命）</div><div class='gd-warn'>判斷小訣竅：嘴角帶笑說「真是的」是ったら；皺著眉頭數落是ときたら；ったら後面還有「ない」，而且前面是形容詞，就是「～得要命」。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>接著學<span class='gd-jp'>～ときたら</span>，把「親暱抱怨」和「認真數落」這兩種語氣分清楚。</div>",
  "n1-45": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜ときたら」就像台灣人抱怨時說的<b>「說到我們家那個喔……真的是」</b>。先把一個讓你受不了的人或東西點出來，後面接著數落它。整句的重點是<b>不滿、傻眼、拿它沒辦法</b>。</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>名詞直接加ときたら，前面通常是人或東西。<br><span class='gd-pair'><span class='gd-jp'>うちの息子</span> → <span class='gd-jp'>うちの息子ときたら</span></span>（說到我家兒子）<br><span class='gd-pair'><span class='gd-jp'>このパソコン</span> → <span class='gd-jp'>このパソコンときたら</span></span>（說到這台電腦）</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>數落身邊的人</span>最常用在家人、同事、主管這些跟你很近、讓你很頭痛的人。</div><div class='gd-ex-line'>・<span class='gd-jp'>うちの息子ときたら、ゲームばかりしている。</span>（說到我家兒子，整天只會打電動）</div><div class='gd-ex-line'>・<span class='gd-jp'>うちの部長ときたら、会議のたびに話が長い。</span>（說到我們部長，每次開會都講超久）</div><div class='gd-sec'><span class='gd-tag'>抱怨東西</span>不好用的東西也可以。</div><div class='gd-ex-line'>・<span class='gd-jp'>このパソコンときたら、すぐ固まるんだから。</span>（這台電腦真是的，動不動就當機）</div><div class='gd-sec'><span class='gd-tag'>罵自己</span>拿自己開刀也很自然。</div><div class='gd-ex-line'>・<span class='gd-jp'>私ときたら、また傘を電車に忘れてきた。</span>（我真是的，又把傘忘在電車上了）</div><div class='gd-sec'><span class='gd-tag'>後面不講完</span>口語裡常把抱怨的內容省略，只說到ときたら，靠語氣讓人聽出不滿。</div><div class='gd-ex-line'>・<span class='gd-jp'>まったく、うちの主人ときたら……</span>（真是的，我家那口子喔……）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・它是<b>跟第三者</b>數落某人某物用的，不能當面喊對方。對著媽媽本人說「お母さんときたら！」是錯的。<br>・後面接的是描述跟抱怨，不接「請～」「～吧」這種要求或決定。像<span class='gd-jp'>うちの部長ときたら、早く帰ってください</span>這樣接一個請求，就不對。<br>・基本上是負面的，不要拿來誇人。<span class='gd-jp'>うちの息子ときたら、頭がいい</span>聽起來會很怪。<br>・語感偏口語、閒聊，正式文章或報告裡不太用。<br>・口語有時會聽到<span class='gd-jp'>夏ときたら、やっぱりビールでしょ。</span>（說到夏天，當然就是啤酒啦）這種「說到A就想到B」的講法，那是另一種用法，不是抱怨，聽到別搞混。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'><b>ったら</b>：也能抱怨，但語氣比較輕，常帶點「真拿你沒辦法」的親暱感，而且<b>可以當面叫對方</b>。<br><span class='gd-jp'>もう、お母さんったら！</span>（唉唷，媽你真是的！）：對著媽媽講，可以<br><b>ときたら</b>：批評比較重，只能跟別人講那個人的事。<br><span class='gd-jp'>うちの母ときたら、人の話を全然聞かない。</span>（說到我媽，完全不聽人講話）：跟朋友抱怨</div><div class='gd-sec'><b>に至っては</b>：先講一群人或一堆事，再挑出<b>最誇張的那一個</b>。<br><span class='gd-jp'>みんな遅刻したが、田中さんに至っては来なかった。</span>（大家都遲到，田中更誇張，根本沒來）<br><b>ときたら</b>不用跟別人比，就是直接點名某個人來數落。</div><div class='gd-warn'>判斷小訣竅：當面喊「你真是的」用ったら；跟別人數落某個人用ときたら；從一群裡挑最誇張的用に至っては。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>常跟「<span class='gd-jp'>まったく</span>」「<span class='gd-jp'>〜んだから</span>」一起出現，抱怨感更強：<span class='gd-jp'>うちの夫ときたら、まったく何もしないんだから。</span>（說到我老公，真的是什麼都不做）</div>",
  "n1-46": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜にあって」就是中文書面語的<b>「身處～之中」「身為～」</b>。前面放一個特別的時代、處境或身分，後面講在這種環境下的狀態、做法，或應該怎麼做。新聞、演講、文章常見，日常聊天幾乎不講。</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>只接名詞：名詞＋にあって<br><span class='gd-pair'><span class='gd-jp'>非常時</span> → <span class='gd-jp'>非常時にあって</span></span>（在這種非常時期）<br><span class='gd-pair'><span class='gd-jp'>現代</span> → <span class='gd-jp'>現代にあって</span></span>（身處現代）</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>特別的時代、狀況</span>非常時期、不景氣、資訊爆炸的年代這類。</div><div class='gd-ex-line'>・<span class='gd-jp'>この非常時にあって、リーダーは冷静であるべきだ。</span>（在這種非常時期，領導者應該冷靜）</div><div class='gd-ex-line'>・<span class='gd-jp'>情報があふれる現代にあって、正しい情報を選ぶ力が必要だ。</span>（身處資訊氾濫的現代，需要分辨正確資訊的能力）</div><div class='gd-sec'><span class='gd-tag'>身分、立場</span>常寫成「〜という立場にあって」。</div><div class='gd-ex-line'>・<span class='gd-jp'>社長という立場にあって、軽率な発言は許されない。</span>（身為社長，不能隨便亂說話）</div><div class='gd-sec'><span class='gd-tag'>身在某處</span>多半是「異國」「戰場」這種不尋常的地方，帶點文學味。</div><div class='gd-ex-line'>・<span class='gd-jp'>異国にあって、家族からの手紙が何よりの支えだった。</span>（身在異鄉，家人的信是我最大的支柱）</div><div class='gd-h'>最常聽到的兩種變身</div><div class='gd-sec'><span class='gd-tag'>にあっても</span>加了「も」，變成<b>「即使身處～，也…」</b>，後面接「還是不放棄、還是很堅強」這類。</div><div class='gd-ex-line'>・<span class='gd-jp'>どんな苦境にあっても、彼女は笑顔を忘れなかった。</span>（不管身處多艱難的處境，她都沒忘記微笑）</div><div class='gd-sec'><span class='gd-tag'>にあっては</span>加了「は」，強調<b>「在這種情況下，就（只能）…」</b>。</div><div class='gd-ex-line'>・<span class='gd-jp'>この不況下にあっては、どの会社も節約せざるを得ない。</span>（在這種不景氣之下，每家公司都不得不節省）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・只接名詞。想用動詞，就先把它變成名詞，或改說「〜という状況にあって」。<br>・前面要是<b>值得一提的特殊環境或身分</b>。「月曜日にあって」「普通の日にあって」這種平凡的時間很怪。<br>・很硬的書面語。跟朋友聊天說「忙しい中」「〜なのに」就好，講にあって會像在唸新聞稿。<br>・別跟單純的「在哪裡」搞混：<span class='gd-jp'>その店は駅前にあって便利だ。</span>（那家店在車站前，很方便）這裡的あって只是「位在」的意思，不是這個文法。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'><b>にあたって</b>（只差一個字，最常看錯）＝<b>要做某件事之前、之際</b>，可以接動詞。<br><span class='gd-jp'>社長に就任するにあたって、一言ご挨拶申し上げます。</span>（在就任社長之際，跟各位說幾句話）<br><span class='gd-jp'>社長という立場にあって、軽率な発言は許されない。</span>（身為社長，不能隨便亂說話）<br>前一句重點是「就任這個時間點」，後一句是「一直身處社長這個位置」。</div><div class='gd-sec'><b>とあって</b>＝<b>因為是～，所以</b>（講原因）。<br><span class='gd-jp'>不況とあって、就職が厳しい。</span>（因為不景氣，找工作很難）<br><span class='gd-jp'>不況にあって、この会社は売り上げを伸ばしている。</span>（身處不景氣之中，這家公司營收還在成長）<br>とあって是「因為這樣所以那樣」；にあって是「人在這個環境裡，怎麼表現」。</div><div class='gd-warn'>判斷小訣竅：「身處～／身為～」用にあって，「要做～之際」用にあたって，「因為是～」用とあって。</div>",
  "n1-48": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「～ともなれば」就是中文的<b>「都已經是～了，當然就…」</b>。前面放一個<b>比平常高一階</b>的身分、年紀或時期，後面講「到了這個層級，自然就會這樣」。就像台灣人會說「人家都當到社長了，放假還要接工作電話很正常啊」，就是這種口氣。</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>身分、年紀升級</span>當上某個職位、到了某個年紀，責任和別人的期待就跟著變了。</div><div class='gd-ex-line'>・<span class='gd-jp'>プロともなれば、これくらいは当然できる。</span>（都是職業的了，這種程度當然做得到）</div><div class='gd-ex-line'>・<span class='gd-jp'>社長ともなれば、休みの日も仕事の電話が来る。</span>（當到社長，連放假都會接到工作電話）</div><div class='gd-sec'><span class='gd-tag'>時期到了</span>到了某個特別的季節或日子，周圍的狀況自然就不一樣了。</div><div class='gd-ex-line'>・<span class='gd-jp'>12月ともなれば、街はクリスマス一色になる。</span>（一到 12 月，街上到處都是聖誕氣氛）</div><div class='gd-sec'><span class='gd-tag'>真的要做大事</span>前面接動詞，意思是「如果真的要做到這一步」，這時候「假如」的味道比較明顯。</div><div class='gd-ex-line'>・<span class='gd-jp'>海外に引っ越すともなれば、準備することが山ほどある。</span>（如果真的要搬到國外，要準備的事可多了）</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>名詞＋ともなれば：<span class='gd-pair'><span class='gd-jp'>大学生</span> → <span class='gd-jp'>大学生ともなれば</span></span><br>動詞辭書形＋ともなれば：<span class='gd-pair'><span class='gd-jp'>結婚する</span> → <span class='gd-jp'>結婚するともなれば</span></span><br>後面常接<span class='gd-jp'>当然</span>、<span class='gd-jp'>～なければならない</span>、<span class='gd-jp'>～ものだ</span>這種「理所當然」「本來就該」的說法。</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・前面要讓人覺得<b>已經到了不一樣的層級</b>。<span class='gd-jp'>小学生ともなれば</span>可以，因為是跟幼稚園比，已經升了一級；隨便放一個普通的詞，句子會很怪。<br>・後面講的是「自然會這樣」，<b>不放自己的意志或請求</b>。想說「當上社長的話我想更努力」，不能說<span class='gd-jp'>社長ともなれば、もっと頑張りたい</span>，要說<span class='gd-jp'>社長になったら、もっと頑張りたい。</span><br>・語氣偏正式，新聞、文章、演講比較常見。平常聊天多半說<span class='gd-jp'>～になると</span>或<span class='gd-jp'>～となると</span>。<br>・別跟<span class='gd-jp'>となれば</span>搞混：少了那個<span class='gd-jp'>も</span>，就只是單純的「如果是那樣的話」，沒有「都到這個層級了」的強調。例：<span class='gd-jp'>明日も雨となれば、試合は中止だ。</span>（如果明天也下雨，比賽就取消）</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'><b>ともなると</b>：意思幾乎一樣，考試時兩個大多可以互換。<br><span class='gd-jp'>12月ともなると、街はクリスマス一色になる。</span><br><span class='gd-jp'>12月ともなれば、街はクリスマス一色になる。</span><br>兩句都對。硬要分的話，<span class='gd-jp'>ともなれば</span>因為有<span class='gd-jp'>ば</span>，「假如真的到了那一步」的味道稍微多一點。</div><div class='gd-sec'><b>とあれば</b>：長得很像，方向卻相反。它是「既然是為了～／既然是～的要求」，後面常接<b>自己願意做、只好去做</b>的事。<br><span class='gd-jp'>社長の命令とあれば、従うしかない。</span>（既然是社長的命令，只能照做）<br><span class='gd-jp'>社長ともなれば、責任も重くなる。</span>（當到社長，責任自然也變重）</div><div class='gd-warn'>判斷小訣竅：前面是「升了一級」，後面講「自然會這樣」，就用ともなれば／ともなると；前面是「特別的理由」，後面講「那我就去做」，就用とあれば。</div>",
  "n1-49": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'><span class='gd-jp'>ともなく</span>有兩種用法，核心都是<b>「說不清楚」</b>。<br>一種是<b>動作沒有目的</b>，像中文的「有一搭沒一搭地看」：電視開著，你眼睛有在看，但根本沒在看什麼。<br>另一種是<b>說不出來源</b>：「不知道從哪裡」「不知道是誰先開始的」。</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>不經意地做</span>沒打算要做，卻自然而然在做。最大的特徵是<b>前後放同一個動詞</b>，或意思很接近的動詞。</div><div class='gd-ex-line'>・<span class='gd-jp'>見るともなく窓の外を見ていた。</span>（我沒特別要看什麼，就這樣望著窗外）</div><div class='gd-ex-line'>・<span class='gd-jp'>聞くともなく隣の席の話を聞いていた。</span>（我不是故意要聽，隔壁桌的話還是傳進耳朵裡）</div><div class='gd-ex-line'>・<span class='gd-jp'>見るともなくテレビを眺めていたら、見覚えのある街が映った。</span>（我有一搭沒一搭地看著電視，結果畫面上出現了眼熟的街景）</div><div class='gd-sec'><span class='gd-tag'>說不出是誰、哪裡</span>前面放「どこ、誰、いつ」這種問句用的字。後面常會帶<span class='gd-jp'>から</span>、<span class='gd-jp'>へ</span>、<span class='gd-jp'>に</span>。</div><div class='gd-ex-line'>・<span class='gd-jp'>どこからともなく、いい匂いがしてきた。</span>（不知道從哪裡飄來一股香味）</div><div class='gd-ex-line'>・<span class='gd-jp'>誰からともなく拍手が起こった。</span>（不知道是誰先開始的，大家都鼓起掌來）</div><div class='gd-ex-line'>・<span class='gd-jp'>男はどこへともなく歩いていった。</span>（那個男人不知道往哪裡走掉了）</div><div class='gd-ex-line'>・<span class='gd-jp'>誰にともなく「ありがとう」とつぶやいた。</span>（沒有對著誰，只是小聲說了句「謝謝」）</div><div class='gd-h'>怎麼接</div><div class='gd-sec'><b>動詞</b>：用原本字典上的樣子（辭書形）加<span class='gd-jp'>ともなく</span>，後面再接同一個動詞。<br><span class='gd-pair'><span class='gd-jp'>見る</span> → <span class='gd-jp'>見るともなく見る</span></span><span class='gd-pair'><span class='gd-jp'>聞く</span> → <span class='gd-jp'>聞くともなく聞く</span></span><br><b>問句用的字</b>：「どこ、誰、いつ」加上助詞，再加<span class='gd-jp'>ともなく</span>。<br><span class='gd-pair'><span class='gd-jp'>どこから</span> → <span class='gd-jp'>どこからともなく</span></span><span class='gd-pair'><span class='gd-jp'>誰から</span> → <span class='gd-jp'>誰からともなく</span></span></div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・動詞要用辭書形：<span class='gd-jp'>見るともなく</span>。不能把ます拿掉接成「見ともなく」，也不能接過去形「見たともなく」。<br>・能這樣用的動詞很有限，幾乎都是<span class='gd-jp'>見る</span>、<span class='gd-jp'>聞く</span>、<span class='gd-jp'>言う</span>、<span class='gd-jp'>考える</span>、<span class='gd-jp'>待つ</span>這類眼睛、耳朵、嘴巴、腦袋會自然做的事。不要隨便套到別的動詞上。<br>・<span class='gd-jp'>どこからともなく</span>和<span class='gd-jp'>どことなく</span>只差一點點，意思不一樣。<span class='gd-jp'>どことなく</span>是「總覺得哪裡有點～」，講的是感覺：<span class='gd-jp'>彼はどことなく父に似ている。</span>（他說不上哪裡，就是有點像我爸）。要講「從哪裡來」，請用<span class='gd-jp'>どこからともなく</span>。<br>・「不經意」不是「沒在做」。<span class='gd-jp'>見るともなく見る</span>還是有在看，只是沒有目的。<br>・這是偏書面的說法，小說、散文很常見。日常聊天多半說<span class='gd-jp'>なんとなく</span>或<span class='gd-jp'>どこからか</span>。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>同級的<b><span class='gd-jp'>ともなると</span></b>（和<span class='gd-jp'>ともなれば</span>意思相同）只差幾個字，意思完全不同。它的意思是：一到了某個程度或立場，<b>自然就會～</b>。前面多半是名詞，也可以接動詞辭書形。<br>用同一個「一個人住」的情境比比看：<br><b><span class='gd-jp'>ともなく</span></b>（不經意）：<span class='gd-jp'>一人の部屋で、見るともなくテレビを見ていた。</span>（一個人在房間裡，有一搭沒一搭地看著電視）<br><b><span class='gd-jp'>ともなく</span></b>（說不出來源）：<span class='gd-jp'>夜中、どこからともなく猫の鳴き声が聞こえてきた。</span>（半夜不知道從哪裡傳來貓叫聲）<br><b><span class='gd-jp'>ともなると</span></b>（名詞）：<span class='gd-jp'>夜中ともなると、この辺りはすっかり静かになる。</span>（一到半夜，這一帶就變得非常安靜）<br><b><span class='gd-jp'>ともなると</span></b>（動詞）：<span class='gd-jp'>一人暮らしをするともなると、家事も全部自分でやらなければならない。</span>（一旦要一個人住，家事就全部得自己來）</div><div class='gd-warn'>判斷小訣竅：<br>・<span class='gd-jp'>ともなく</span>通常長成「同一個動詞＋ともなく＋同一個動詞」或「どこから／誰から＋ともなく」，意思是不經意、說不出是誰或哪裡。<br>・<span class='gd-jp'>ともなると</span>後面會接「就會～、當然～」，意思是到了那個程度或立場，自然會有某種情況。<br>不要只看前面是名詞還是動詞，要看整句的形式和意思。</div>",
  "n1-50": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「AともBともつかない」就是中文的<b>「說A也不像A，說B也不像B」</b>，像「似笑非笑」「說藍不藍、說綠不綠」那種感覺。眼前的東西卡在兩者中間，你分不出它到底算哪一邊。</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>A、B 放<b>名詞</b>或<b>動詞普通形</b>（辭書形、ている形、ない形這些不加ます的形），後面各加一個「とも」，最後接「つかない」。<br><span class='gd-pair'><span class='gd-jp'>本気</span>＋<span class='gd-jp'>冗談</span> → <span class='gd-jp'>本気とも冗談ともつかない</span></span><br><span class='gd-pair'><span class='gd-jp'>笑っている</span>＋<span class='gd-jp'>泣いている</span> → <span class='gd-jp'>笑っているとも泣いているともつかない</span></span><br>這裡的「つかない」是「判斷不出來、定不下來」的意思，通常寫平假名。後面最常直接接名詞，例如表情、聲音、口氣、回答、顏色。</div><div class='gd-h'>最常聽到的兩種樣子</div><div class='gd-sec'><span class='gd-tag'>ともつかない</span>東西本身就模稜兩可，你看了、聽了也分不出來。</div><div class='gd-ex-line'>・<span class='gd-jp'>本気とも冗談ともつかない言い方だった。</span>（那種講法，分不清他是認真還是開玩笑）</div><div class='gd-ex-line'>・<span class='gd-jp'>ため息ともあくびともつかない声が聞こえた。</span>（傳來一個分不清是嘆氣還是打哈欠的聲音）</div><div class='gd-ex-line'>・<span class='gd-jp'>彼女は笑っているとも泣いているともつかない顔をしていた。</span>（她露出一種似笑非笑、像哭又不像哭的表情）</div><div class='gd-sec'><span class='gd-tag'>とも言わない</span>A、B 通常是一正一反，表示對方<b>不表態</b>，有點像中文的「不置可否」。</div><div class='gd-ex-line'>・<span class='gd-jp'>彼は行くとも行かないとも言わない。</span>（他沒說要去，也沒說不去）</div><div class='gd-ex-line'>・<span class='gd-jp'>部長はいいとも悪いとも言わなかった。</span>（部長沒說好，也沒說不好）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・「つかない」是指<b>那個東西本身</b>分不出來，用來形容表情、聲音、回答這類眼前的東西。單純「我不知道答案」不要用它：想說「我不知道他會不會來」，要講<span class='gd-jp'>彼が来るか来ないか分からない</span>。<br>・A 和 B 後面<b>都要</b>加とも。只寫一個，或寫成「AかBともつかない」都不對。<br>・動詞直接接とも，不需要多加「の」：寫<span class='gd-jp'>笑っているとも</span>就好，不必寫成笑っているのとも。<br>・這是偏書面、小說的寫法。平常聊天說<span class='gd-jp'>冗談か本気か分からない</span>就夠了。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'><b>AともBとも言わない</b>：兩個都<b>沒說</b>，態度不明。<br><span class='gd-jp'>彼は賛成とも反対とも言わなかった。</span>（他沒說贊成，也沒說反對）<br><b>Aと言わずBと言わず</b>：不管是A還是B，<b>全部都</b>是那樣。<br><span class='gd-jp'>手と言わず足と言わず泥だらけになった。</span>（手也好、腳也好，全身都是泥）<br>兩個都是「A…B…」加上「言わ」，看起來很像，意思卻完全不同：一個是「兩邊都不講」，一個是「哪裡都一樣」。</div><div class='gd-sec'><b>〜ともなく</b>也有「とも」，但它只有<b>一格</b>，前面常接疑問詞，意思是「說不上是哪裡、是誰」。<br><span class='gd-jp'>どこからともなく音楽が聞こえてきた。</span>（不知道從哪裡傳來了音樂）</div><div class='gd-warn'>判斷小訣竅：有兩個選項、分不出是哪一個，用ともつかない；兩邊都不表態，用とも言わない；兩個都包含、全部都是，用と言わず；只有一個疑問詞「不知道從哪裡、不知道是誰」，用ともなく。</div>",
  "n1-51": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜てまで」就是中文的<b>「不惜～也要…」「甚至～也要…」</b>。為了達成某個目的，連平常不會做、代價很大的事都做了。日本人講這句時，常常帶著「有必要做到這樣嗎？」的口氣。</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>把動詞變成て形，後面加「まで」，再接你真正想達成的目的。<br><span class='gd-pair'><span class='gd-jp'>借金する</span> → <span class='gd-jp'>借金して</span> → <span class='gd-jp'>借金してまで</span></span><br><span class='gd-pair'><span class='gd-jp'>無理をする</span> → <span class='gd-jp'>無理をしてまで</span></span><br><span class='gd-pair'><span class='gd-jp'>嘘をつく</span> → <span class='gd-jp'>嘘をついてまで</span></span><br>整句的骨架是<b>「Aてまで、B」＝為了B，不惜做A</b>。A是你付出的代價，B是你想要的東西。</div><div class='gd-h'>最常聽到的樣子</div><div class='gd-sec'><span class='gd-tag'>不值得</span>後面接「〜必要はない」「〜たくない」，意思是「為了這個做到那種地步，不划算」。這是最常見的用法。</div><div class='gd-ex-line'>・<span class='gd-jp'>借金してまで、ブランド品を買う必要はない。</span>（沒必要為了買名牌去借錢）</div><div class='gd-ex-line'>・<span class='gd-jp'>体を壊してまで働きたくない。</span>（我不想為了工作把身體搞壞）</div><div class='gd-sec'><span class='gd-tag'>傻眼、質疑</span>覺得別人付出的代價太誇張，用問句表達。</div><div class='gd-ex-line'>・<span class='gd-jp'>そこまでして行きたいの？</span>（要做到那種地步你也想去？）</div><div class='gd-ex-line'>・<span class='gd-jp'>友達を裏切ってまで、出世したかったのか。</span>（你就那麼想升官，不惜背叛朋友？）</div><div class='gd-sec'><span class='gd-tag'>單純說有多拚</span>不一定是批評，也可以只是描述某人付出很多，有時還帶點佩服。</div><div class='gd-ex-line'>・<span class='gd-jp'>徹夜してまで並んで、限定スイーツを手に入れた。</span>（不惜熬夜排隊，終於買到了限定甜點）</div><div class='gd-ex-line'>・<span class='gd-jp'>社長は自分の給料を減らしてまで、社員を守った。</span>（社長不惜減自己的薪水，也要保住員工）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・<b>順序別放反</b>：てまで前面是「代價」，後面才是「目的」。<span class='gd-jp'>借金してまで買う</span>是「為了買而借錢」。如果寫成「買ってまで借金する」，就變成「為了借錢而去買」，意思完全不通。<br>・前面要放<b>不尋常、犧牲很大</b>的事。輕鬆、本來就會做的事放進去，句子就沒有「不惜」的感覺，聽起來很怪。<br>・<span class='gd-jp'>そこまでして</span>是口語很常用的固定說法，意思是「做到那種地步」，跟てまで是同一種感覺。要注意它是在說<b>代價太大</b>，不是「都已經這種狀況了」。<br>・名詞要先加「する」或「をする」變成動詞，才能接てまで：<span class='gd-jp'>借金してまで</span>、<span class='gd-jp'>無理をしてまで</span>、<span class='gd-jp'>家族を犠牲にしてまで</span>。不能直接寫「借金まで」，那會變成「連借錢都…」，是另一個意思。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>都是動詞後面加「まで」，只差在動詞變成什麼形，意思就完全不同：<br><b>辭書形＋まで</b>＝直到～<br>・<span class='gd-jp'>彼が来るまで待った。</span>（我一直等到他來）<br><b>て形＋まで</b>＝不惜～也要<br>・<span class='gd-jp'>3時間も待ってまで、彼に会いたかった。</span>（我不惜等三個小時，也想見到他）<br><b>辭書形＋までだ（放句尾）</b>＝大不了就～<br>・<span class='gd-jp'>彼が来ないなら、一人で行くまでだ。</span>（他不來的話，大不了我自己去）</div><div class='gd-warn'>判斷小訣竅：まで前面是<b>て形</b>就是「不惜」；是<b>辭書形</b>而且句子還沒結束，就是「直到」；<b>までだ</b>放在句尾，就是「大不了／只是」。</div>",
  "n1-54": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜かろう」就是「〜いだろう」的<b>老派書面版</b>，意思是「大概～吧」「想必～吧」。<span class='gd-jp'>難しいだろう</span>寫成<span class='gd-jp'>難しかろう</span>，意思不變，只是聽起來像社論、小說，或是古裝劇裡的老爺爺在說話。</div><div class='gd-h'>怎麼接</div><div class='gd-sec'><b>只能接い形容詞</b>：把最後的「い」拿掉，加「かろう」。<br><span class='gd-pair'><span class='gd-jp'>難しい</span> → い拿掉 → <span class='gd-jp'>難しかろう</span></span><br><span class='gd-pair'><span class='gd-jp'>寒い</span> → <span class='gd-jp'>寒かろう</span></span><span class='gd-pair'><span class='gd-jp'>高い</span> → <span class='gd-jp'>高かろう</span></span><br><b>兩個要特別記</b>：<br><span class='gd-pair'><span class='gd-jp'>いい</span> → <span class='gd-jp'>よかろう</span></span>（從<span class='gd-jp'>よい</span>變來的）<br><span class='gd-pair'><span class='gd-jp'>ない</span> → <span class='gd-jp'>なかろう</span></span><br>「〜たい」的變化跟い形容詞一樣，所以也能接：<span class='gd-pair'><span class='gd-jp'>帰りたい</span> → <span class='gd-jp'>帰りたかろう</span></span>（大概很想回去吧）</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>書面推測</span>文章、評論裡推測情況，常跟<span class='gd-jp'>さぞ</span>（想必）一起出現。</div><div class='gd-ex-line'>・<span class='gd-jp'>山の上はさぞ寒かろう。</span>（山上想必很冷吧）</div><div class='gd-ex-line'>・<span class='gd-jp'>最初は苦しかろうが、すぐに慣れる。</span>（一開始大概會很辛苦，但很快就會習慣）</div><div class='gd-h'>最常聽到的樣子</div><div class='gd-sec'><span class='gd-tag'>ではなかろうか</span>＝「是不是～呢」，論文、社論超常見，是比較委婉的主張。</div><div class='gd-ex-line'>・<span class='gd-jp'>この計画には無理があるのではなかろうか。</span>（這個計畫是不是有點勉強呢）</div><div class='gd-sec'><span class='gd-tag'>よかろう</span>長輩或上司說「好吧，可以」，有種上對下、勉強答應的感覺。</div><div class='gd-ex-line'>・<span class='gd-jp'>まあ、よかろう。今回だけは許してやる。</span>（嗯，好吧。這次就饒了你）</div><div class='gd-sec'><span class='gd-tag'>固定說法</span><span class='gd-jp'>安かろう悪かろう</span>＝便宜沒好貨。</div><div class='gd-ex-line'>・<span class='gd-jp'>安かろう悪かろうの時代は終わった。</span>（便宜沒好貨的時代已經過去了）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・な形容詞和名詞<b>不能</b>接かろう：<span class='gd-jp'>静かかろう</span>是錯的，要說<span class='gd-jp'>静かだろう</span>或<span class='gd-jp'>静かであろう</span>；名詞也一樣，要用<span class='gd-jp'>学生だろう</span>或<span class='gd-jp'>学生であろう</span>。<br>・動詞也不能接：要說<span class='gd-jp'>行くだろう</span>或<span class='gd-jp'>行くであろう</span>。<br>・<span class='gd-jp'>いい</span>要變成<span class='gd-jp'>よかろう</span>，沒有「いかろう」這種說法。<br>・「ろう」要拉長音念成ろー。<br>・跟朋友聊天說<span class='gd-jp'>暑かろう</span>會很像在演古裝劇，平常講<span class='gd-jp'>暑いだろう</span>就好。<br>・<span class='gd-jp'>よかろう</span>是上對下的口氣，對上司、老師說會很失禮。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>「〜かろうが／〜かろうと」有兩種意思，要看句子怎麼搭：<br><b>大概～，但…</b>（推測再轉折）：<span class='gd-jp'>その試験は難しかろうが、準備すれば突破できる。</span>（那場考試大概很難，但只要準備就能過）<br><b>不管～都…</b>（就是<span class='gd-jp'>〜ようが／〜ようと</span>的い形容詞版）：<span class='gd-jp'>高かろうが安かろうが、必要なものは買う。</span>（不管貴還是便宜，需要的東西就買）<br><span class='gd-jp'>どんなに辛かろうと、最後までやり抜く。</span>（不管多辛苦，都要堅持到最後）</div><div class='gd-warn'>判斷小訣竅：前面有「どんなに」「いくら」，或是兩個成對出現（高かろうが安かろうが）→「不管～都」；只有一個，後面接「但…」→「大概～，但」。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>動詞、名詞版的「不管～」就是<span class='gd-jp'>〜ようが／〜ようと</span>：<span class='gd-jp'>雨が降ろうが、試合は行われる。</span>（就算下雨，比賽還是照常舉行）</div>",
  "n1-58": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜とばかりに」就是中文的<b>「一副『～』的樣子」</b>。對方嘴巴沒講，可是動作、表情明顯在說某句話，你就把那句<b>心裡的台詞</b>放在前面，後面接他做的動作。<br>像課長一直看手錶，嘴巴沒講，但大家都看得出來他在說「快下班吧」，這時就用它。</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>描寫別人的樣子</span>把對方動作背後的「台詞」寫出來，小說、報導、敘述場面最常見。</div><div class='gd-ex-line'>・<span class='gd-jp'>「早く帰れ」とばかりに、課長は時計をちらちら見た。</span>（課長一直瞄手錶，一副「快回去」的樣子）</div><div class='gd-ex-line'>・<span class='gd-jp'>「遊ぼう」とばかりに、犬がボールをくわえて走ってきた。</span>（狗咬著球跑過來，一副「來玩嘛」的樣子）</div><div class='gd-ex-line'>・<span class='gd-jp'>「待ってました」とばかりに、彼は勢いよく手を挙げた。</span>（他一副「就等這個了」的樣子，用力舉起手）</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>前面放的是<b>一句台詞</b>，所以台詞長什麼樣都可以：命令的口氣（<span class='gd-jp'>帰れ</span>）、揪人的口氣（<span class='gd-jp'>遊ぼう</span>）、ます形（<span class='gd-jp'>待ってました</span>）、一個單字或感嘆都行。常會加上「」，讓人一眼看出是台詞。<br>後面要接名詞時改成<b>とばかりの</b>：<br>・<span class='gd-jp'>「もう帰れ」とばかりの冷たい態度だった。</span>（擺出一副「快滾」的冷淡態度）</div><div class='gd-h'>最常聽到的樣子</div><div class='gd-sec'><span class='gd-tag'>ここぞとばかりに</span><span class='gd-jp'>ここぞ</span>＝「就是這裡、就是現在」，整句變成「逮到機會似的、趁機猛～」，非常常見。</div><div class='gd-ex-line'>・<span class='gd-jp'>会議で、彼はここぞとばかりに不満を言い始めた。</span>（開會時，他逮到機會似的開始大吐苦水）</div><div class='gd-sec'><span class='gd-tag'>今だとばかりに</span>「就是現在！」看準時機馬上行動。</div><div class='gd-ex-line'>・<span class='gd-jp'>相手が転んだ瞬間、今だとばかりに走り出した。</span>（對手一跌倒，他就一副「就是現在」的樣子衝了出去）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・這是<b>從旁邊看別人</b>的說法，通常不拿來講自己。自己心裡想什麼你自己最清楚，不需要「看起來像在說」。<br>・前面的話<b>其實沒說出口</b>。如果對方真的講了，就直接用「〜と言って」。<br>・這裡的ばかり不是「只有」的意思，別翻成「只是～」。<br>・它不是只能接普通形，前面放命令、ます形、單字都可以，因為它就是在引用一句話。<br>・多半用在書面、描寫場面；平常聊天比較少這樣講。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'><b>とばかりに</b>＝前面放一句<b>台詞</b>：「一副『～』的樣子」<br><b>んばかりに</b>＝前面放一個<b>快要發生的動作</b>：「簡直快要～」<br>同一個情境：小孩拿到禮物超開心。</div><div class='gd-ex-line'>・<span class='gd-jp'>「やった」とばかりに、子どもは両手を上げた。</span>（小孩舉起雙手，一副「太好了」的樣子）</div><div class='gd-ex-line'>・<span class='gd-jp'>子どもは飛び上がらんばかりに喜んだ。</span>（小孩高興得簡直快跳起來）</div><div class='gd-sec'>んばかりに的接法：先變成ない形，把「ない」拿掉，加「ん」。<br><span class='gd-pair'><span class='gd-jp'>飛び上がる</span> → <span class='gd-jp'>飛び上がらない</span> → <span class='gd-jp'>飛び上がらんばかりに</span></span><br><span class='gd-pair'><span class='gd-jp'>泣き出す</span> → <span class='gd-jp'>泣き出さない</span> → <span class='gd-jp'>泣き出さんばかりに</span></span><br>※<b>する要變成「せん」</b>，不是「しん」：<span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>せんばかりに</span></span>（例：<span class='gd-jp'>今にも爆発せんばかりに</span>）<br>另外，<span class='gd-jp'>「帰れ」と言わんばかりに</span>（簡直就要說出「回去」）的意思跟<span class='gd-jp'>「帰れ」とばかりに</span>幾乎一樣，可以互換。</div><div class='gd-warn'>判斷小訣竅：前面是一句「台詞」就用とばかりに；前面是「差一點就要做出來的動作」就用んばかりに。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>同樣是在描寫「樣子」，可以接著看<span class='gd-jp'>〜んばかりに</span>（簡直快要～），兩個一起記最不容易混。</div>",
  "n1-60": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「Aかたがた」就是中文書信裡的<b>「兼致謝意」「順道問候」</b>。去拜訪或寫信給某人時，順便帶上另一個目的，例如道謝、報告近況、問候。它是很正式的說法，常出現在拜訪長輩、客戶，或商務書信裡。</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>前面放<b>名詞</b>，而且多半是「動作」的名詞，例如<span class='gd-jp'>お礼</span>（道謝）、<span class='gd-jp'>ご挨拶</span>（問候）、<span class='gd-jp'>ご報告</span>（報告）、<span class='gd-jp'>お見舞い</span>（探病）、<span class='gd-jp'>散歩</span>（散步）。<br><span class='gd-pair'><span class='gd-jp'>お礼</span> → <span class='gd-jp'>お礼かたがた</span></span><span class='gd-pair'><span class='gd-jp'>ご報告</span> → <span class='gd-jp'>ご報告かたがた</span></span><br>後面接的通常是「去拜訪」或「寫信、致詞」這類動作，最常看到<span class='gd-jp'>伺う</span>、<span class='gd-jp'>お邪魔する</span>、<span class='gd-jp'>申し上げる</span>。</div><div class='gd-h'>最常聽到的樣子</div><div class='gd-sec'><span class='gd-tag'>登門拜訪</span>說明自己今天來的目的。</div><div class='gd-ex-line'>・<span class='gd-jp'>先日のお礼かたがた、ご挨拶に伺いました。</span>（今天來向您問候，也為前幾天的事道謝）</div><div class='gd-ex-line'>・<span class='gd-jp'>近くまで来ましたので、ご挨拶かたがたお邪魔しました。</span>（剛好到附近，就順道過來跟您打聲招呼）</div><div class='gd-sec'><span class='gd-tag'>書信</span>商務信、問候信的結尾很常用，幾乎是固定句。</div><div class='gd-ex-line'>・<span class='gd-jp'>略儀ながら書中をもちまして、お礼かたがたご挨拶申し上げます。</span>（請容我以書信代替，在此向您致謝並問候）</div><div class='gd-ex-line'>・<span class='gd-jp'>転勤のご報告かたがた、お手紙を差し上げます。</span>（寫這封信，也是想向您報告我調職的消息）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・前面接名詞，不接動詞辭書形：要說<span class='gd-jp'>お礼かたがた</span>，不說<span class='gd-jp'>お礼を言うかたがた</span>。<br>・中文的「順便」聽起來好像那件事不重要，但日文的かたがた沒有這個意思，道謝跟問候都是真心的目的。用<span class='gd-jp'>お礼かたがた</span>不會失禮，反而很得體。<br>・它很正式，後面常搭<span class='gd-jp'>伺う</span>、<span class='gd-jp'>申し上げる</span>這類謙虛說法。跟朋友講「我順便去超商」不會用它。<br>・<span class='gd-jp'>ご来場の方々</span>、<span class='gd-jp'>関係者の方々</span>裡的「<span class='gd-jp'>方々</span>（かたがた）」意思是「各位」，只是發音一樣，跟這個文法無關。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'><b>かたがた</b>＝正式場合，拜訪或寫信時<b>兼帶另一個目的</b>：<br><span class='gd-jp'>お礼かたがた、先生のお宅に伺いました。</span>（去老師家拜訪，也是去道謝）<br><b>がてら</b>＝日常口語，<b>出門做A，順路做B</b>：<br><span class='gd-jp'>散歩がてら、パンを買ってきた。</span>（出去散步，順便買了麵包）<br><b>かたわら</b>＝長時間<b>一邊做本業，一邊做另一件事</b>，跟「順便」沒關係：<br><span class='gd-jp'>会社に勤めるかたわら、小説を書いている。</span>（他一邊上班，一邊寫小說）</div><div class='gd-warn'>判斷小訣竅：正式拜訪、寫信時「兼表謝意、順道問候」用かたがた；日常出門順路做點事用がてら；長期身兼兩件事用かたわら。</div>",
  "n1-61": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「AかたわらB」就是<b>「在做A（本業）之餘，還兼做B」</b>，有點像現在說的「斜槓」。<span class='gd-jp'>かたわら</span>本來的意思是「旁邊」：主要的事擺中間，旁邊還兼著另一件事。</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>長期兼著做</span>講一個人的生活或工作狀態：本業是什麼，另外還長期在做什麼。常出現在人物介紹、報導、自我介紹的文章裡。</div><div class='gd-ex-line'>・<span class='gd-jp'>会社に勤めるかたわら、週末は小説を書いている。</span>（在公司上班之餘，週末都在寫小說）</div><div class='gd-ex-line'>・<span class='gd-jp'>彼女は大学で教えるかたわら、翻訳の仕事もしている。</span>（她在大學教書之外，也有在做翻譯）</div><div class='gd-ex-line'>・<span class='gd-jp'>仕事のかたわら、日本語の勉強を続けている。</span>（工作之餘，一直持續在學日文）</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>動詞：辭書形（字典裡的原形）＋かたわら<br><span class='gd-pair'><span class='gd-jp'>働く</span> → <span class='gd-jp'>働くかたわら</span></span><span class='gd-pair'><span class='gd-jp'>店を経営する</span> → <span class='gd-jp'>店を経営するかたわら</span></span><br>名詞：名詞＋の＋かたわら<br><span class='gd-pair'><span class='gd-jp'>仕事</span> → <span class='gd-jp'>仕事のかたわら</span></span><span class='gd-pair'><span class='gd-jp'>育児</span> → <span class='gd-jp'>育児のかたわら</span></span><br>名詞通常是「工作、研究、育兒」這種本身就代表一件事的詞。</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・它<b>不是</b>「同一個時間手上一邊做這個、一邊做那個」。<span class='gd-jp'>音楽を聞くかたわら勉強する</span>是錯的，這種要用<span class='gd-jp'>聞きながら</span>。<br>・兩件事都是<b>持續一段時間</b>的，所以後面很常配「〜ている」。只發生一次的事不適合。<br>・前面放<b>主要的</b>那件，後面放兼做的那件，不要放反。<br>・前面不接た形：<span class='gd-jp'>勤めたかたわら</span>是錯的，一律用辭書形。<br>・這是書面語，跟朋友聊天很少講，口語通常說<span class='gd-jp'>仕事しながら</span>或<span class='gd-jp'>本業のほかに</span>。<br>・看到<span class='gd-jp'>母のかたわらで</span>這種「名詞のかたわらで」，大多是字面的「在～旁邊」，不是這個文法。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'><b>ながら</b>＝同一個時間，手上同時做兩件事：<br><span class='gd-jp'>音楽を聞きながら勉強する。</span>（邊聽音樂邊念書）<br><b>かたわら</b>＝長期兩種身分或兩份事情：<br><span class='gd-jp'>会社で働くかたわら、夜間の大学に通っている。</span>（白天上班之餘，晚上還去念夜間大學）<br><b>がてら</b>＝這一趟出門，順便兼辦另一件事，是短時間、一次性的：<br><span class='gd-jp'>散歩がてら、パンを買ってきた。</span>（出去散散步，順便把麵包買回來了）<br><b>かたがた</b>＝意思跟がてら接近，但更正式，多用在拜訪、道謝、問候。後面是實際的行動，前面是同時兼帶的目的：<br><span class='gd-jp'>先日のお礼かたがた、ご挨拶に伺いました。</span>（兼表前幾天的謝意，前來拜訪問候您）</div><div class='gd-warn'>判斷小訣竅：講一個人長期兼著兩件事，用かたわら；這一趟出門兼辦兩件事，用がてら（正式場合用かたがた）；手上同一時間做兩件事，用ながら。</div>",
  "n1-65": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜いかん」就是中文公文裡的<b>「視～而定」「端看～」</b>。漢字寫作中文的「如何」兩個字，但現在多半直接寫平假名<span class='gd-jp'>いかん</span>。意思是：結果怎麼樣，要看前面那件事的狀況。很硬、很正式，新聞、公告、合約、主管訓話才會出現。</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>只接<b>名詞</b>，中間的「の」可加可不加，不加比較常見。<br><span class='gd-pair'><span class='gd-jp'>努力</span> → <span class='gd-jp'>努力いかん</span></span>（看努力的程度）<br><span class='gd-pair'><span class='gd-jp'>試験の結果</span> → <span class='gd-jp'>試験の結果いかん</span></span>（看考試結果）<br>前面的名詞要是<b>會有好有壞、有高有低</b>的東西，例如：<span class='gd-jp'>結果</span>、<span class='gd-jp'>努力</span>、<span class='gd-jp'>態度</span>、<span class='gd-jp'>対応</span>、<span class='gd-jp'>天候</span>、<span class='gd-jp'>返答</span>、<span class='gd-jp'>内容</span>。</div><div class='gd-h'>最常聽到的樣子</div><div class='gd-sec'><span class='gd-tag'>いかんだ／いかんにかかっている</span>放在句尾，「就看～了」。</div><div class='gd-ex-line'>・<span class='gd-jp'>合格できるかどうかは、本人の努力いかんだ。</span>（能不能考上，就看本人努不努力）</div><div class='gd-ex-line'>・<span class='gd-jp'>今期の業績は、チームの努力いかんにかかっている。</span>（本期業績取決於團隊的努力）</div><div class='gd-sec'><span class='gd-tag'>いかんで／いかんによって</span>放在句中，「依～而決定、而改變」。</div><div class='gd-ex-line'>・<span class='gd-jp'>参加費は人数いかんで変わります。</span>（參加費會依人數而有所不同）</div><div class='gd-sec'><span class='gd-tag'>いかんでは／いかんによっては</span>多了一個「は」，意思變成「視情況，<b>甚至有可能</b>～」，後面通常接一個特別的、常常是不太好的結果。</div><div class='gd-ex-line'>・<span class='gd-jp'>天候いかんでは、試合が中止になることもあります。</span>（視天候狀況，比賽也有可能取消）</div><div class='gd-ex-line'>・<span class='gd-jp'>会社の対応いかんでは、訴訟も考えています。</span>（看公司怎麼處理，我們也考慮提告）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・念<b>いかん</b>。同樣是「如何」兩個字，在<span class='gd-jp'>如何ですか</span>裡念いかが，別混在一起。<br>・不能直接接動詞或形容詞：說「看你努不努力」要寫<span class='gd-jp'>努力いかんで</span>，不能寫成「頑張るいかんで」。<br>・前面要是有變數的名詞，像「明日」這種沒有好壞高低可言的詞就不能用。<br>・太正式了，跟朋友聊天說「天気いかんで決めよう」會很怪，口語請用<span class='gd-jp'>天気次第で決めよう</span>或<span class='gd-jp'>天気によって決めよう</span>。<br>・口語裡單獨一句<span class='gd-jp'>それはいかん</span>是「那可不行」，是另一個詞，跟這個文法無關。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'><b>次第</b>（N2）＝意思幾乎一樣，但口語、書面都能用，比較輕鬆：<br><span class='gd-jp'>結果次第で、計画を変えるかもしれない。</span>（看結果，計畫可能會改）<br><b>いかん</b>＝同樣的意思，換成公文、報告的口氣：<br><span class='gd-jp'>結果いかんでは、計画を変更することもあり得る。</span>（視結果而定，計畫亦可能變更）<br><b>いかんによらず／いかんにかかわらず</b>（n1-66）＝意思相反，「<b>不管</b>～怎麼樣都一樣」：<br><span class='gd-jp'>理由のいかんにかかわらず、返金はいたしません。</span>（無論理由為何，恕不退款）</div><div class='gd-warn'>判斷小訣竅：いかん後面接「で・によって・だ・にかかっている」，是「<b>要看它</b>」；接「によらず・にかかわらず・を問わず」，是「<b>不管它</b>」。想講得輕鬆一點，就把いかん換成次第。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>接著學 n1-66 的<span class='gd-jp'>いかんによらず</span>、<span class='gd-jp'>いかんにかかわらず</span>，還有公告上很常看到的<span class='gd-jp'>理由のいかんを問わず</span>（不問理由）。</div>",
  "n1-66": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜いかんによらず／いかんにかかわらず」就是中文公文裡的<b>「不論～如何，一律……」</b>。前面放一個可能有各種狀況的東西（理由、結果、天氣），後面講的結論<b>不會因此改變</b>。你在公告、合約、退票規定上最常看到它，平常聊天幾乎不用。</div><div class='gd-h'>先拆開來看</div><div class='gd-sec'><span class='gd-jp'>いかん</span>寫成漢字是<span class='gd-jp'>如何</span>，意思是「內容、狀況怎麼樣」。<br><span class='gd-jp'>によらず</span>＝不依照、不取決於；<span class='gd-jp'>にかかわらず</span>＝跟～沒關係。<br>兩個意思一樣，都是「不管～怎麼樣」。另外還有一個也很常見的說法：<span class='gd-jp'>いかんを問わず</span>（不問～如何）。</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>名詞＋の＋いかんによらず／いかんにかかわらず<br><span class='gd-pair'><span class='gd-jp'>理由</span> → <span class='gd-jp'>理由のいかんによらず</span></span><span class='gd-pair'><span class='gd-jp'>天候</span> → <span class='gd-jp'>天候のいかんにかかわらず</span></span><br>前面的名詞要是<b>會有好幾種可能</b>的東西，例如<span class='gd-jp'>理由</span>、<span class='gd-jp'>結果</span>、<span class='gd-jp'>事情</span>、<span class='gd-jp'>国籍</span>、<span class='gd-jp'>天候</span>。<br>正式文件裡有時會把「の」省掉，寫成<span class='gd-jp'>理由いかんにかかわらず</span>。你看得懂就好，自己寫的時候先用有「の」的版本。</div><div class='gd-h'>最常看到的樣子</div><div class='gd-sec'><span class='gd-tag'>規定・公告</span>店家或公司在講「沒有例外」。</div><div class='gd-ex-line'>・<span class='gd-jp'>理由のいかんを問わず、購入後のキャンセルはできません。</span>（不論理由為何，購買後都不能取消）</div><div class='gd-ex-line'>・<span class='gd-jp'>天候のいかんにかかわらず、イベントは予定通り開催されます。</span>（不論天氣如何，活動都會照常舉行）</div><div class='gd-sec'><span class='gd-tag'>資格・條件</span>表示大家一視同仁。</div><div class='gd-ex-line'>・<span class='gd-jp'>国籍のいかんによらず、どなたでも応募できます。</span>（不論國籍，任何人都可以報名）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・前面只能接<b>名詞</b>，不能直接接動詞或形容詞：<span class='gd-jp'>行くいかんによらず</span>是錯的。<br>・前面要放「有各種狀況」的詞。<span class='gd-jp'>雨のいかんにかかわらず</span>不通，因為「雨」沒有「怎麼樣」可言，要說<span class='gd-jp'>天候のいかん</span>。<br>・這裡的<span class='gd-jp'>如何</span>念<b>いかん</b>。同樣的漢字在<span class='gd-jp'>如何ですか</span>念いかが，不要搞混。<br>・非常硬，跟朋友講會很怪。口語說<span class='gd-jp'>どんな理由でも</span>（不管什麼理由）就好。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'><b>〜いかんで／いかんによっては</b>（N1 的「〜如何」）意思剛好<b>相反</b>：結果<b>要看</b>前面怎麼樣。<br>・<span class='gd-jp'>面接の結果いかんで、採用が決まります。</span>（錄不錄取，要看面試結果）<br>・<span class='gd-jp'>面接の結果のいかんにかかわらず、交通費は支給します。</span>（不論面試結果如何，交通費都會發給你）</div><div class='gd-sec'><b>〜にかかわらず</b>（N2）是比較一般的「不管」，不用加いかん，前面也可以放<span class='gd-jp'>天気</span>、<span class='gd-jp'>年齢</span>這類詞：<span class='gd-jp'>天気にかかわらず、試合は行われます。</span>（不管天氣，比賽照常進行）<br>加上「のいかん」會更正式，更像官方文件的口氣。</div><div class='gd-warn'>判斷小訣竅：いかん後面接「によらず／にかかわらず／を問わず」，就是「不管」；接「で／によっては」，就是「要看」。</div>",
  "n1-68": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜をもってしても」就是中文的<b>「就連靠～，也還是…」</b>。前面放一個很厲害、照理說應該有用的東西（最新技術、某人的實力），後面說「結果還是不行、還是很難」。重點在<b>「連這麼強的都沒辦法」</b>，用來凸顯事情有多難。</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>直接接在名詞後面：名詞＋をもってしても<br><span class='gd-pair'><span class='gd-jp'>最新の技術</span> → <span class='gd-jp'>最新の技術をもってしても</span></span>（就連靠最新的技術）<br><span class='gd-pair'><span class='gd-jp'>彼の実力</span> → <span class='gd-jp'>彼の実力をもってしても</span></span>（就連以他的實力）<br>前面也可以直接放人，意思是「連他那麼厲害的人」：<span class='gd-jp'>彼をもってしても</span></div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>技術、科學、方法</span>連目前最好的辦法都做不到。</div><div class='gd-ex-line'>・<span class='gd-jp'>今の科学をもってしても、地震を正確に予知することはできない。</span>（就算靠現在的科學，也沒辦法準確預測地震）</div><div class='gd-sec'><span class='gd-tag'>人的能力</span>連很強的人都覺得難。</div><div class='gd-ex-line'>・<span class='gd-jp'>彼の実力をもってしても、優勝は難しいだろう。</span>（就連以他的實力，要拿冠軍恐怕也很難）</div><div class='gd-ex-line'>・<span class='gd-jp'>天才と呼ばれた彼をもってしても、この問題は解けなかった。</span>（就連被稱為天才的他，也解不開這道題）</div><div class='gd-sec'><span class='gd-tag'>言語、表達</span>演講、致詞常見的說法，表示感受強烈到講不出來。</div><div class='gd-ex-line'>・<span class='gd-jp'>どんな言葉をもってしても、この感謝の気持ちは伝えきれません。</span>（不管用什麼樣的言詞，都表達不完我的感謝）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・後面幾乎都是<b>「做不到、很難、還是不夠」</b>這種結果，例如<span class='gd-jp'>できない</span>、<span class='gd-jp'>難しい</span>、<span class='gd-jp'>無理だ</span>。後面接「成功了」會整句很怪。<br>・前面要放<b>本來被期待很有用</b>的東西。放普通的東西，例如「用我的鉛筆」，就沒有「連這都不行」的張力。<br>・這是很正式的書面說法，新聞、論文、演講常見。平常講話說<span class='gd-jp'>最新の技術でも</span>（就算是最新技術也…）就好。<br>・它的重點是「靠這個力量去做」，不是「從～的角度來看」。不要翻成「以～來看」。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>同一個「技術」，三種說法結果完全不同：<br><b>をもって</b>＝用、靠（單純說手段）：<span class='gd-jp'>この技術をもって、問題を解決した。</span>（靠這個技術解決了問題）<br><b>をもってすれば</b>＝只要有～就做得到：<span class='gd-jp'>この技術をもってすれば、問題は解決できる。</span>（只要有這個技術，問題就能解決）<br><b>をもってしても</b>＝就算有～也做不到：<span class='gd-jp'>この技術をもってしても、問題は解決できない。</span>（就算有這個技術，問題也解決不了）<br>另外，<span class='gd-jp'>をもって</span>還有「以此為界」的用法，例如<span class='gd-jp'>本日をもって閉店します。</span>（本店營業到今天為止），這跟をもってしても無關，不要混在一起。</div><div class='gd-warn'>判斷小訣竅：看中間那一小段。「すれば」是有它就行，「しても」是有它也不行。</div>",
  "n1-71": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜ずにはすまない」就是中文的<b>「不～說不過去」「不～這件事收不了場」</b>。<span class='gd-jp'>すむ</span>（済む）是「事情了結、過得去」，<span class='gd-jp'>すまない</span>就是「過不去」。整句的意思是：照情理、照現在的情況，不做這件事是交代不了的。</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>道義上該做</span>做錯事、出了包，不道歉、不賠償、不負責，在人情上說不過去。</div><div class='gd-ex-line'>・<span class='gd-jp'>人の車に傷をつけたのだから、弁償せずにはすまない。</span>（既然刮傷了別人的車，不賠是說不過去的）</div><div class='gd-sec'><span class='gd-tag'>情勢逼著做</span>事情鬧大了，不處理就沒辦法收場。</div><div class='gd-ex-line'>・<span class='gd-jp'>ここまで問題が大きくなれば、社長も記者会見をせずにはすまないだろう。</span>（問題都鬧這麼大了，社長恐怕也不得不開記者會吧）</div><div class='gd-sec'>前面常常會先講理由，像是<span class='gd-jp'>〜のだから</span>、<span class='gd-jp'>〜以上</span>、<span class='gd-jp'>〜たら</span>，後面也常常加<span class='gd-jp'>だろう</span>，表示「照這情況看，應該躲不掉了」。</div><div class='gd-h'>怎麼接</div><div class='gd-sec'><b>ずにはすまない</b>：先變成ない形，把「ない」拿掉，再加「ずにはすまない」。<br><span class='gd-pair'><span class='gd-jp'>謝る</span> → <span class='gd-jp'>謝らない</span> → <span class='gd-jp'>謝らずにはすまない</span></span><br><span class='gd-pair'><span class='gd-jp'>払う</span> → <span class='gd-jp'>払わない</span> → <span class='gd-jp'>払わずにはすまない</span></span><br><span class='gd-pair'><span class='gd-jp'>認める</span> → <span class='gd-jp'>認めない</span> → <span class='gd-jp'>認めずにはすまない</span></span><br><b>第三類要特別記</b>：<span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>せずにはすまない</span></span><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来ずにはすまない</span>（こずに）</span></div><div class='gd-sec'><b>ないではすまない</b>：ない形直接加「ではすまない」，不用拿掉任何東西，意思一樣，口氣稍微沒那麼硬。</div><div class='gd-ex-line'>・<span class='gd-jp'>会議を無断で休んだのだから、部長に説明しないではすまない。</span>（會議沒請假就缺席，不跟部長解釋是過不去的）</div><div class='gd-sec'>還有前面接名詞或「〜だけ」等的<span class='gd-jp'>〜ではすまない</span>，意思是「光這樣是了結不了的」：</div><div class='gd-ex-line'>・<span class='gd-jp'>冗談ではすまない。</span>（這不是開玩笑就能了事的）</div><div class='gd-ex-line'>・<span class='gd-jp'>謝るだけではすまない。</span>（光道歉是解決不了的）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・する要變<b>せずに</b>，不是「しずに」。<span class='gd-jp'>説明せずにはすまない</span>才對。<br>・這裡的<span class='gd-jp'>すまない</span>不是「對不起」的意思，是「事情過不去」。<br>・它是書面、正式的說法，新聞、評論、正式場合比較常見。跟朋友聊天講「該道歉了吧」，日本人通常說<span class='gd-jp'>謝らないとまずいよ</span>，或用<span class='gd-jp'>謝らないわけにはいかない</span>。<br>・重點是「外在的情理或情況逼你做」，不是你自己很想做，也不是情緒上忍不住。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>同樣是「道歉」這件事，三個長得很像的說法意思差很多：<br><b>ずにはすまない</b>＝情理上不做說不過去（被情況逼）<br>・<span class='gd-jp'>ミスをしたのは私だから、謝らずにはすまない。</span>（錯是我犯的，不道歉說不過去）<br><b>ずにはいられない</b>＝情緒上忍不住（N2 學過）<br>・<span class='gd-jp'>彼の涙を見て、謝らずにはいられなかった。</span>（看到他的眼淚，我忍不住道歉了）<br><b>ずにはおかない</b>＝一定要做到，不然不罷休（強烈的意志）<br>・<span class='gd-jp'>今度こそ、彼に謝らせずにはおかない。</span>（這次我一定要讓他道歉）</div><div class='gd-warn'>判斷小訣竅：「不做說不過去」是すまない，「忍不住」是いられない，「不做不罷休」是おかない。</div>",
  "n1-73": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「ただ～のみ」就是中文的<b>「唯有～」「就只剩～」</b>，是「だけ」的正式、文言版。最常見的用法是講決心：該做的都做了，眼前只剩一條路，例如<span class='gd-jp'>あとはただ待つのみだ</span>（接下來就只能等了）。語氣很堅定，有種「不想別的，就專心做這件事」的味道。</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>只有這個</span>強調範圍只有這一個，沒有別的。</div><div class='gd-ex-line'>・<span class='gd-jp'>合格したのは、ただ一人のみだった。</span>（及格的只有一個人）</div><div class='gd-sec'><span class='gd-tag'>只剩這件事可做</span>放在句尾變成「～のみだ」，表示其他都不用想了，就是做這件事。演講、比賽前的發言、新聞報導很常見。</div><div class='gd-ex-line'>・<span class='gd-jp'>やるべきことはすべてやった。あとはただ結果を待つのみだ。</span>（該做的都做了，接下來只能等結果）</div><div class='gd-ex-line'>・<span class='gd-jp'>今はただ無事を祈るのみです。</span>（現在只能祈求平安）</div><div class='gd-h'>怎麼接</div><div class='gd-sec'><b>名詞</b>：ただ＋名詞＋のみ　<span class='gd-pair'><span class='gd-jp'>一人</span> → <span class='gd-jp'>ただ一人のみ</span></span><br><b>動詞</b>：ただ＋辭書形＋のみ　<span class='gd-pair'><span class='gd-jp'>前進する</span> → <span class='gd-jp'>ただ前進するのみだ</span></span><br>要講得客氣一點，就把最後的だ換成です：<span class='gd-jp'>祈るのみです</span>。<br>「ただ」可以省略，只用「のみ」意思也成立，加上ただ是為了更強調。</div><div class='gd-h'>最常聽到的樣子</div><div class='gd-sec'><span class='gd-tag'>名詞＋あるのみ</span>講「只剩這件事要做」時，名詞後面常加「ある」，幾乎是固定說法：<span class='gd-jp'>努力あるのみ</span>、<span class='gd-jp'>前進あるのみ</span>、<span class='gd-jp'>練習あるのみ</span>。</div><div class='gd-ex-line'>・<span class='gd-jp'>試合まであと一週間。練習あるのみだ。</span>（離比賽只剩一週，只能拚命練了）</div><div class='gd-sec'><span class='gd-tag'>告示牌</span>在日本街上常看到單獨的「のみ」，意思是「限～」。</div><div class='gd-ex-line'>・<span class='gd-jp'>この席は会員のみご利用いただけます。</span>（這個座位限會員使用）</div><div class='gd-ex-line'>・<span class='gd-jp'>関係者のみ</span>（非相關人員請勿進入）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・它很正式、很有氣勢。跟朋友聊午餐說「ただ食べるのみ」會很像在演戲，平常講話用<span class='gd-jp'>だけ</span>就好：<span class='gd-jp'>あとは待つだけだ</span>。<br>・動詞要用辭書形，不能接ます形：說<span class='gd-jp'>前進するのみです</span>，不能說「前進しますのみ」。<br>・<span class='gd-jp'>のみならず</span>長得很像，意思卻是<b>「不只～」</b>，剛好相反：<span class='gd-jp'>ただ日本のみならず、世界中で人気がある。</span>（不只在日本，在全世界都很受歡迎）。看到のみ後面還有「ならず」，就要切換成「不只」。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'><b>～のみだ</b>＝眼前<b>只有這條路</b>，專心往前：<span class='gd-jp'>ここまで来たら、ただ前進するのみだ。</span>（都走到這一步了，就只有往前衝）<br><b>～まで（のこと）だ</b>＝<b>大不了就～</b>，是先想好的退路，前面常有「だめなら」「失敗したら」：<span class='gd-jp'>だめなら、もう一度挑戦するまでだ。</span>（不行的話，大不了再挑戰一次）</div><div class='gd-warn'>判斷小訣竅：中文可以說「唯有／只能～」就用のみ；中文是「大不了就～」，前面還有「如果不行的話」，就用までだ。</div>",
  "n1-74": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜ないものでもない」就是中文的<b>「也不是不～啦」</b>。像朋友拜託你幫忙搬家，你嘴上說「看你請不請吃飯囉，也不是不能幫」。意思是有可能，但不是很情願，也沒有答應得很乾脆。</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>動詞先變成否定的「ない」，後面直接加<b>ものでもない</b>。<br><span class='gd-pair'><span class='gd-jp'>引き受ける</span> → <span class='gd-jp'>引き受けない</span> → <span class='gd-jp'>引き受けないものでもない</span></span><br><span class='gd-pair'><span class='gd-jp'>許す</span> → <span class='gd-jp'>許さない</span> → <span class='gd-jp'>許さないものでもない</span></span><br><span class='gd-pair'><span class='gd-jp'>間に合う</span> → <span class='gd-jp'>間に合わない</span> → <span class='gd-jp'>間に合わないものでもない</span></span><br>「不」加上「也不是」，兩個否定抵消，變成<b>有點保留的「可以」</b>。</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>附條件答應</span>最常見的用法。前面常有「〜ば」「〜なら」「〜次第では（看～而定）」，先開條件，再說「也不是不行」。</div><div class='gd-ex-line'>・<span class='gd-jp'>条件次第では、引き受けないものでもない。</span>（看條件，也不是不能接）</div><div class='gd-ex-line'>・<span class='gd-jp'>ちゃんと謝るなら、許さないものでもない。</span>（如果好好道歉，也不是不能原諒）</div><div class='gd-sec'><span class='gd-tag'>還有可能</span>判斷一件事不是完全沒希望。</div><div class='gd-ex-line'>・<span class='gd-jp'>あと一週間あれば、間に合わないものでもない。</span>（再多一個禮拜的話，也不是趕不上）</div><div class='gd-sec'><span class='gd-tag'>勉強能理解</span>對別人的想法表示「多少懂」。</div><div class='gd-ex-line'>・<span class='gd-jp'>彼の気持ちも分からないものでもない。</span>（他的心情我也不是不能理解）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・<b>「ない」不能漏掉。</b>寫成<span class='gd-jp'>引き受けるものでもない</span>，意思就變成「也不是該接的事」，剛好反過來。像<span class='gd-jp'>お金で買えるものでもない</span>是「也不是用錢買得到的」，跟這個文法無關。<br>・它只代表「<b>有可能</b>」，不是「一定會」，也不是「很想」。翻成「我願意」「沒問題」就翻過頭了。<br>・語氣很硬，又是書面的說法，常帶一點<b>「勉強答應你」「我在考慮看看」</b>的高姿態。對主管、客人說「手伝わないものでもないです」會很失禮，客氣的時候不要用。<br>・前面接的通常是自己的行動或判斷，像接不接、考不考慮、能不能理解，很少拿來說別人的事。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>意思幾乎一樣的還有<b>ないこともない</b>、<b>ないでもない</b>、<b>なくもない</b>，差別在場合：<br><b>ないものでもない</b>：書面、生硬，常出現在文章、談判、比較正式的發言。<br><span class='gd-jp'>条件が合えば、協力しないものでもない。</span>（條件合的話，也不是不能合作）<br><b>ないこともない／ないでもない</b>：日常對話最常用。<br><span class='gd-jp'>時間があれば、行けないこともないよ。</span>（有時間的話，也不是不能去啦）<br><b>なくもない</b>：更口語、更隨便。<br><span class='gd-jp'>まあ、分からなくもないけど。</span>（嗯，也不是不懂啦）</div><div class='gd-warn'>判斷小訣竅：意思都是「也不是不～」。聊天用「ないこともない」，寫文章、談條件、想端點架子才用「ないものでもない」。</div>",
  "n1-76": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜ではあるまいし」就是中文的<b>「又不是～，（幹嘛…／應該…）」</b>。媽媽看你在哭，說「又不是小孩子，哭什麼哭」，就是這個語氣：先丟出一個<b>明顯不是事實</b>的情況，再用它來念對方、勸對方。</div><div class='gd-h'>它是怎麼來的</div><div class='gd-sec'>拆開看就懂：<span class='gd-jp'>ではあるまい</span>是書面一點的「應該不是～吧」，<span class='gd-jp'>し</span>是「因為～」。合起來就是「又不是～，所以…」。<br>口語幾乎都說<b><span class='gd-jp'>じゃあるまいし</span></b>，<span class='gd-jp'>ではあるまいし</span>比較常出現在文章或正式一點的場合。</div><div class='gd-h'>怎麼接</div><div class='gd-sec'><span class='gd-tag'>名詞</span>直接接：<span class='gd-pair'><span class='gd-jp'>子供</span> → <span class='gd-jp'>子供じゃあるまいし</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>子供じゃあるまいし、自分のことは自分でやりなさい。</span>（又不是小孩，自己的事自己做）</div><div class='gd-ex-line'>・<span class='gd-jp'>神様じゃあるまいし、明日のことなんて分からないよ。</span>（我又不是神，哪知道明天會怎樣）</div><div class='gd-sec'><span class='gd-tag'>動詞</span>中間要先墊一個<b><span class='gd-jp'>の</span>（口語<span class='gd-jp'>ん</span>）或<span class='gd-jp'>わけ</span></b>，不能直接接。<br><span class='gd-pair'><span class='gd-jp'>遊びに行く</span> → <span class='gd-jp'>遊びに行くんじゃあるまいし</span></span><br><span class='gd-pair'><span class='gd-jp'>会えない</span> → <span class='gd-jp'>会えないわけじゃあるまいし</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>遊びに行くんじゃあるまいし、もっとちゃんとした服を着ていきなさい。</span>（又不是去玩，穿正式一點再去）</div><div class='gd-ex-line'>・<span class='gd-jp'>一生会えないわけじゃあるまいし、そんなに泣かないで。</span>（又不是一輩子見不到，別哭成那樣）</div><div class='gd-h'>後面通常接什麼</div><div class='gd-sec'>後半句是你真正想講的話，幾乎都是<b>命令、禁止、勸告、批評或自己的判斷</b>：「別再～」「自己做」「這種事不應該發生」。前半句則常用很誇張、一聽就知道不是的東西，像<span class='gd-jp'>子供</span>、<span class='gd-jp'>神様</span>、<span class='gd-jp'>素人</span>。</div><div class='gd-ex-line'>・<span class='gd-jp'>素人じゃあるまいし、こんなミスは許されないよ。</span>（又不是外行人，這種錯誤說不過去）</div><div class='gd-sec'><span class='gd-tag'>口語倒裝</span>講話時很常把它放到最後補一句。</div><div class='gd-ex-line'>・<span class='gd-jp'>いちいち説明しなくても分かるよ。子供じゃあるまいし。</span>（不用每件事都解釋，我懂啦，我又不是小孩）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・動詞前面一定要有<span class='gd-jp'>の／ん／わけ</span>：是<span class='gd-jp'>死ぬわけじゃあるまいし</span>，不是「死ぬじゃあるまいし」。名詞則反過來，不要加の，不會說「子供のじゃあるまいし」。<br>・前半句必須是<b>大家都知道「明明不是」</b>的事。如果只是單純交代理由，例如「我不是學生，所以要付全票」，用這個就很怪，那種情況用<span class='gd-jp'>〜ではないので</span>就好。<br>・語氣是在<b>念人、吐槽</b>，帶點不耐煩。對主管、客人直接講會很失禮。<br>・它不是「不會～吧」的推測句，重點在後面那句的責備或勸告。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'><b>〜じゃないんだから</b>：意思幾乎一樣，「又不是～嘛」，但更日常、更常聽到，N1 以下的人也會講。<br>・<span class='gd-jp'>子供じゃないんだから、泣かないで。</span>（又不是小孩，別哭了）<br>・<span class='gd-jp'>子供じゃあるまいし、泣かないで。</span>（同上，語氣稍微老派、帶點念人的味道）</div><div class='gd-sec'><b>〜ではあるまいか</b>：只差最後一個字，意思完全不同，是書面語的「該不會是～吧／恐怕是～吧」，用來推測。<br>・<span class='gd-jp'>子供ではあるまいし、一人で行けるだろう。</span>（又不是小孩，一個人去得了吧）<br>・<span class='gd-jp'>彼は何か隠しているのではあるまいか。</span>（他是不是在隱瞞什麼呢）</div><div class='gd-warn'>判斷小訣竅：後面有「し」＋一句念人的話，就是「又不是～」；最後是「か」，就是在猜「該不會是～吧」。</div>",
  "n1-78": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「AあってのB」就是中文的<b>「有A才有B」「B全靠A」</b>。A是B能存在的前提，沒有A，B就不存在。台灣店家常說「客人是我們的衣食父母」，日文就是：<span class='gd-jp'>お客様あっての商売だ。</span>（有客人才有生意）</div><div class='gd-h'>怎麼接</div><div class='gd-sec'><b>名詞＋あっての＋名詞</b>。前面放名詞，後面也一定接名詞。<br>「あって」是「ある（有）」的て形，加上「の」就是「有了～的…」。<br><span class='gd-pair'><span class='gd-jp'>お客様</span> → <span class='gd-jp'>お客様あっての商売</span></span>（有客人才有的生意）</div><div class='gd-h'>最常聽到的樣子</div><div class='gd-sec'><span class='gd-tag'>AあってのBだ</span>講一個道理或價值觀：B是靠A撐起來的。</div><div class='gd-ex-line'>・<span class='gd-jp'>選手はファンあっての存在だ。</span>（選手是因為有球迷才存在的）</div><div class='gd-ex-line'>・<span class='gd-jp'>命あっての物種だ。無理はするな。</span>（人活著才有一切，不要硬撐）</div><div class='gd-sec'><span class='gd-tag'>〜あってのことだ</span>後面的名詞換成「こと」，意思是「這都是靠～才有的」。得獎感言、致謝最常用。</div><div class='gd-ex-line'>・<span class='gd-jp'>合格できたのは、先生のご指導あってのことです。</span>（我能考上，全靠老師的指導）</div><div class='gd-ex-line'>・<span class='gd-jp'>皆さんの応援あっての優勝です。</span>（有大家的加油才有這次冠軍）</div><div class='gd-sec'><span class='gd-tag'>あってこその</span>中間加「こそ」，語氣更強：<span class='gd-jp'>家族あってこその私です。</span>（正因為有家人，才有現在的我）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・後面一定要接名詞（或こと）。不能說「お客様あっての売れる」，要說<span class='gd-jp'>お客様あっての商売</span>。<br>・固定用「あっての」，不要寫成「あるの」。<br>・它不是單純的「因為」。「因為下雨所以取消」不能說「雨あっての中止」，要說<span class='gd-jp'>雨で中止になった</span>。A要是B<b>不可缺少的根本</b>，通常是客人、健康、支持、努力這類正面又重要的東西。<br>・語氣比較正式、帶點感性，多用在演講、訪談、文章。跟朋友聊天直接說<span class='gd-jp'>お客さんがいるから</span>就好。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>同一個意思，可以從正面講，也可以從反面講：<br><b>あっての</b>＝正面說「有A才有B」，後面接名詞：<span class='gd-jp'>お客様あっての商売だ。</span>（有客人才有生意）<br><b>なくしては</b>＝反面說「沒有A就不能B」，後面接否定：<span class='gd-jp'>お客様なくしては商売は成り立たない。</span>（沒有客人，生意就做不起來）<br><b>ばこそ</b>＝「正因為～才…」，說明做某件事的理由，前面接ば形：<span class='gd-jp'>お客様のことを思えばこそ、品質にこだわるのだ。</span>（正因為替客人著想，才講究品質）</div><div class='gd-warn'>判斷小訣竅：講「B是靠A才存在的」用あっての，後面放名詞；講「少了A就辦不到」用なくしては，後面放否定；講「正因為這樣想或這樣做」用ばこそ。</div>",
  "n1-79": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「ともすると／ともすれば」就是中文的<b>「動不動就～」「一不小心就～」「往往容易～」</b>。它講的是一種<b>不太好的傾向</b>：不是每次都這樣，但稍微沒注意就會往那個方向跑。像「人一閒下來就容易滑手機滑到半夜」這種感覺。</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>它是一個<b>獨立的詞</b>，不用接在任何字後面，放在句子開頭，或放在「要講的那件壞事」前面就好。<br>後半句通常搭配表示「容易～」的說法，前後一起出現最自然：<br><span class='gd-tag'>常見搭配</span><span class='gd-jp'>〜がちだ</span>（常常會～）、<span class='gd-jp'>〜やすい</span>（容易～）、<span class='gd-jp'>〜てしまう</span>（不小心就～了）</div><div class='gd-ex-line'>・<span class='gd-jp'>人はともすると、楽なほうへ流れがちだ。</span>（人往往容易往輕鬆的方向走）</div><div class='gd-ex-line'>・<span class='gd-jp'>忙しいと、ともすれば食事を抜いてしまう。</span>（一忙起來，常常一不小心就沒吃飯）</div><div class='gd-ex-line'>・<span class='gd-jp'>一人暮らしだと、ともすると生活が不規則になりやすい。</span>（一個人住的話，生活很容易變得不規律）</div><div class='gd-sec'>「ともすると」和「ともすれば」意思一樣，可以互換，挑順口的用就好。</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・它不是接在別的字後面的文法，不能寫成「忙しいともすると」。要分開放：<span class='gd-jp'>忙しいと、ともすると〜</span>。<br>・它講的是<b>不好的傾向</b>。好習慣不會用它，例如想說「我常常不知不覺就去運動」，不會用ともすると。<br>・它講的是「常有的傾向」，不是某一次發生的事。「昨天一不小心遲到了」只是一次的意外，不用ともすると，直接說<span class='gd-jp'>うっかり遅刻した</span>就好。<br>・語氣偏書面、偏正式，文章、演講、評論裡很常見。跟朋友聊天比較常說<span class='gd-jp'>つい</span>、<span class='gd-jp'>すぐ</span>，例如<span class='gd-jp'>ついスマホを見ちゃう</span>（忍不住就一直看手機）。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'><b>ともすると／ともすれば</b>：獨立放在句中，講<b>容易陷入的壞傾向</b>，後面常配がち、やすい。<br><b>ともなると／ともなれば</b>：前面接名詞（多為身分、立場、時間、程度），也可以接動詞辭書形，意思是<b>「一旦到了某種身分、時期、狀況，就理所當然會～」</b>。<br>同樣講「忙到沒吃飯」，對照看看：</div><div class='gd-ex-line'>・<span class='gd-jp'>忙しいと、ともすると食事を抜きがちだ。</span>（一忙就容易不吃飯：講壞習慣）</div><div class='gd-ex-line'>・<span class='gd-jp'>年末ともなると、食事をする時間もない。</span>（一到年底，連吃飯的時間都沒有：講到了那個時期自然會這樣）</div><div class='gd-sec'>ともなると的其他例子：<span class='gd-jp'>社長ともなると、なかなか休めない。</span>（當到社長，就很難休假）<br><span class='gd-jp'>海外に住むともなると、準備が大変だ。</span>（要是到了住國外這一步，準備起來可辛苦了）</div><div class='gd-warn'>判斷小訣竅：前面有接名詞或動詞、講「到了那個階段就會～」的是ともなると；自己一個詞站著、講「動不動就～（壞事）」的是ともすると。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>同樣講「有不好的傾向」，可以接著看<span class='gd-jp'>〜嫌いがある</span>，它放在句尾：<span class='gd-jp'>彼は物事を悲観的に考える嫌いがある。</span>（他有把事情往悲觀方向想的傾向）。兩個也常一起用：<span class='gd-jp'>人はともすると、自分に甘くなる嫌いがある。</span>（人往往有對自己太寬容的毛病）</div>",
  "n1-82": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜を限りに」就是<b>「就到〜為止，之後就不再〜了」</b>。像中文說「今天是最後一天」「做完這次就收山」，劃一條線：線之前還有，線之後就沒了。</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>前面直接放時間點的名詞，再加「を限りに」：<br><span class='gd-pair'><span class='gd-jp'>今日</span> → <span class='gd-jp'>今日を限りに</span></span><span class='gd-pair'><span class='gd-jp'>今回</span> → <span class='gd-jp'>今回を限りに</span></span><span class='gd-pair'><span class='gd-jp'>本日</span> → <span class='gd-jp'>本日を限りに</span></span><br>最常見的是<span class='gd-jp'>今日・本日・今回・今月・今年度</span>這種「現在這個時間點」的詞。</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>下決心不再做</span>跟過去的自己切割，常常帶點決心。</div><div class='gd-ex-line'>・<span class='gd-jp'>今日を限りに、お酒はやめる。</span>（喝到今天為止，以後不喝了）</div><div class='gd-sec'><span class='gd-tag'>宣布結束</span>店收掉、選手退休、制度廢除，常帶一點感慨。</div><div class='gd-ex-line'>・<span class='gd-jp'>今回の試合を限りに、引退します。</span>（打完這場比賽我就退休）</div><div class='gd-ex-line'>・<span class='gd-jp'>この路線は今年度を限りに廃止される。</span>（這條路線營運到本年度結束後就廢除）</div><div class='gd-sec'><span class='gd-tag'>另一個意思</span>「<span class='gd-jp'>声を限りに</span>」是固定說法，意思是「用盡全力、扯開喉嚨」，跟時間無關，看到要認得。</div><div class='gd-ex-line'>・<span class='gd-jp'>声を限りに助けを呼んだ。</span>（扯開喉嚨拼命呼救）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・它不是「截止期限」。交作業的期限要用までに：<span class='gd-jp'>金曜日までに出してください。</span>（請在星期五前交），不能說「金曜日を限りに出してください」。<br>・後面接的多半是<b>結束、停止、不再做</b>的事，像<span class='gd-jp'>やめる・引退する・閉店する・解散する</span>。如果只是要說「從今天開始努力」，日文通常用<span class='gd-jp'>今日から</span>。<br>・這是偏正式、偏書面的說法。平常跟朋友講，用<span class='gd-jp'>今日でやめる</span>或<span class='gd-jp'>今日限りでやめる</span>就好。<br>・別跟「動詞＋限り」搞混：<span class='gd-jp'>生きている限り</span>是「只要還活著」，意思完全不同。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'><b>をもって</b>也能表示「以〜為結束」，同一個關店公告兩個都能用，但感覺不一樣：<br><span class='gd-jp'>本日をもって閉店いたします。</span>（本店營業至今日止）<br>→ 公事公辦的正式公告，只是通知「在這天結束」。<br><span class='gd-jp'>本日を限りに閉店いたします。</span>（今天是最後一天營業）<br>→ 重點在「就到今天，以後再也沒有了」，比較有感情、有落幕的味道。<br>另外，<b>をもって</b>也能表示<b>開始</b>：<span class='gd-jp'>4月1日をもって新制度を実施します。</span>（自 4 月 1 日起實施新制度）；<b>を限りに</b>只能用在「最後」，不能拿來說開始。</div><div class='gd-warn'>判斷小訣竅：想強調「最後一次、之後不再」用を限りに；正式通知某天開始或結束用をもって。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>意思剛好相反的是「<span class='gd-jp'>〜を皮切りに</span>」＝以〜為開端，接著一個個展開：<span class='gd-jp'>東京公演を皮切りに、全国ツアーが始まる。</span>（從東京場開始，展開全國巡迴）</div>",
  "n1-83": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'><span class='gd-jp'>めく</span>就是中文的<b>「有點～的味道」「透出一股～的氣息」</b>。還沒完全變成那樣，但已經感覺得到了。像二月底某天突然回暖，你會說「有點春天的感覺了」，日文就是<span class='gd-jp'>春めいてきた</span>。</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>季節慢慢轉換</span>最常見的用法，通常配<span class='gd-jp'>〜めいてきた</span>，表示「漸漸有了～的感覺」。</div><div class='gd-ex-line'>・<span class='gd-jp'>一気に春めいてきた。</span>（一下子有春天的感覺了）</div><div class='gd-ex-line'>・<span class='gd-jp'>風が少し秋めいてきた。</span>（風開始有點秋天的味道了）</div><div class='gd-sec'><span class='gd-tag'>形容人或說話方式</span>用<span class='gd-jp'>〜めいた</span>放在名詞前面，表示「帶點～味道的」。</div><div class='gd-ex-line'>・<span class='gd-jp'>彼女はどこか謎めいた人だ。</span>（她是個有點神祕的人）</div><div class='gd-ex-line'>・<span class='gd-jp'>皮肉めいた言い方はやめてよ。</span>（別用那種帶刺的講法啦）</div><div class='gd-ex-line'>・<span class='gd-jp'>言い訳めいたことは言いたくない。</span>（我不想講像在找藉口的話）</div><div class='gd-h'>怎麼接、怎麼變</div><div class='gd-sec'>名詞後面直接加<span class='gd-jp'>めく</span>，整個就變成一個動詞，而且是<b>第一類（五段動詞）</b>，變法跟<span class='gd-jp'>書く</span>一樣。<br>接て、た的時候，く換成い：<br><span class='gd-pair'><span class='gd-jp'>春めく</span> → <span class='gd-jp'>春めいて</span></span> → <span class='gd-pair'><span class='gd-jp'>春めいてきた</span></span><br><span class='gd-pair'><span class='gd-jp'>謎めく</span> → <span class='gd-jp'>謎めいた</span></span> → <span class='gd-pair'><span class='gd-jp'>謎めいた事件</span></span>（神祕的事件）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・<b>不是每個名詞都能接</b>。<span class='gd-jp'>めく</span>只跟一小群固定的詞搭配，常見的有<span class='gd-jp'>春めく</span>、<span class='gd-jp'>秋めく</span>、<span class='gd-jp'>謎めく</span>、<span class='gd-jp'>皮肉めく</span>、<span class='gd-jp'>冗談めく</span>、<span class='gd-jp'>言い訳めく</span>、<span class='gd-jp'>説教めく</span>。像「<span class='gd-jp'>学生めく</span>」「<span class='gd-jp'>先生めく</span>」就不自然，要說<span class='gd-jp'>学生らしい</span>或<span class='gd-jp'>学生っぽい</span>。<br>・放在名詞前面幾乎都用<b>めいた</b>：說<span class='gd-jp'>謎めいた人</span>，不太說謎めく人。<br>・て形是<span class='gd-jp'>めいて</span>，不是めくて，也不是めきて。<br>・<span class='gd-jp'>春めいてきた</span>是「有春天的感覺了」，不等於<span class='gd-jp'>春になった</span>（已經是春天了）。<br>・語感偏書面、偏文學，天氣報導、小說裡很常見。跟朋友隨口聊天，一般用<span class='gd-jp'>っぽい</span>比較多。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>同樣講「春天」：<br><span class='gd-jp'>だんだん春めいてきた。</span>（漸漸透出春天的氣息了）：重點在<b>開始有跡象</b>。<br><span class='gd-jp'>今日は春らしい天気だ。</span>（今天是很有春天樣子的天氣）：重點在<b>很典型、名副其實</b>。<br><span class='gd-jp'>春っぽい服を買った。</span>（買了很春天感的衣服）：<b>口語</b>，隨口說「很像～」。</div><div class='gd-warn'>判斷小訣竅：「開始透出～的氣息、帶點～味道」用めく；「很有～該有的樣子」用らしい；聊天隨口說「很～的感覺」用っぽい。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'><span class='gd-jp'>めく</span>有個兄弟<span class='gd-jp'>めかす</span>，表示「故意弄成～的樣子」：<span class='gd-jp'>冗談めかして本音を言った。</span>（用開玩笑的口氣說出了真心話）</div>",
  "n1-84": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>這組文法就是中文的<b>「足足有～」「多達～之多」</b>。前面放一個數字，說話的人想強調「這數字很大耶」，而且<b>可能還不只這樣</b>。像你看到一個 30 公斤的行李會說「這個足足有 30 公斤欸」，日文就用它。</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>前面一定是<b>數字＋單位</b>（100キロ、1万人、50万円），後面直接接からある／からする／からの。三個怎麼選，看你在講什麼東西。</div><div class='gd-sec'><span class='gd-tag'>からある</span>重量、長度、高度、距離、大小。<br>日文本來就說「重さが<b>ある</b>」「長さが<b>ある</b>」，所以講「有多重、有多長」用ある。</div><div class='gd-ex-line'>・<span class='gd-jp'>30キロからある荷物を一人で運んだ。</span>（一個人搬了足足 30 公斤的行李）</div><div class='gd-ex-line'>・<span class='gd-jp'>2メートルからある魚が釣れた。</span>（釣到一條足足兩公尺長的魚）</div><div class='gd-ex-line'>・<span class='gd-jp'>片道100キロからある道のりを毎日車で通っている。</span>（他每天開車通勤，單程足足一百公里）</div><div class='gd-sec'><span class='gd-tag'>からする</span>價錢。<br>日文講「要價多少」本來就用する：<span class='gd-jp'>この時計は100万円する。</span>（這支錶要一百萬日圓）。所以價錢配からする。</div><div class='gd-ex-line'>・<span class='gd-jp'>一泊10万円からするホテルに泊まった。</span>（住了一晚要價足足十萬日圓的飯店）</div><div class='gd-ex-line'>・<span class='gd-jp'>あのバッグは50万円からするらしい。</span>（聽說那個包包要價高達五十萬日圓）</div><div class='gd-sec'><span class='gd-tag'>からの</span>最常用在人數，後面<b>一定要接名詞</b>（の就是「的」）。錢、債務這類數量也可以用からの＋名詞。</div><div class='gd-ex-line'>・<span class='gd-jp'>会場には1万人からの人が集まった。</span>（會場聚集了多達一萬人）</div><div class='gd-ex-line'>・<span class='gd-jp'>彼には1000万円からの借金がある。</span>（他背了多達一千萬日圓的債）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・只能用在<b>大的數字</b>。<span class='gd-jp'>1キロからある荷物</span>很怪，因為一公斤沒什麼好強調的。<br>・からする只管<b>價錢</b>。重量要說<span class='gd-jp'>100キロからある</span>，不是100キロからする。<br>・からの後面一定要有名詞：<span class='gd-jp'>1万人からの人</span>可以，句子停在「1万人からの。」就不行。<br>・這組文法有點書面、正式，新聞、報導、文章很常見。跟朋友聊天講得出來，但比較口語的說法是用「も」（下面會講）。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'><b>一般的「から」</b>＝<b>從～起跳</b>（價格範圍的最低價）：<br><span class='gd-jp'>この店の時計は1万円からあります。</span>（這家店的錶一萬日圓起跳）<br><b>からする</b>＝<b>足足要～</b>（強調很貴）：<br><span class='gd-jp'>この時計は100万円からする。</span>（這支錶要價足足一百萬日圓）<br>前者是在講「最便宜的從哪裡開始」，後者是在講「這一個東西有夠貴」。</div><div class='gd-sec'><b>數字＋も</b>＝口語的「竟然有～」：<span class='gd-jp'>この荷物、30キロもあるよ。</span>（這行李竟然有 30 公斤耶）<br><b>からある</b>＝比較書面，帶有「至少這麼多、說不定更多」的感覺：<span class='gd-jp'>30キロからある荷物</span>（足足有 30 公斤的行李）</div><div class='gd-warn'>判斷小訣竅：店家寫「～円から」是在報最低價；數字後面接からある／からする／からの，是說話的人在驚嘆「這數字好大」。重量長度用ある、價錢用する、後面要接名詞就用からの。</div>",
  "n1-85": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜ようにも〜ない」就是中文的<b>「想～也～不了」</b>，像「想逃也逃不掉」「想忘也忘不掉」。心裡真的想做，卻被狀況卡住，<b>根本做不到</b>，口氣裡帶著無奈。</div><div class='gd-ex-line'>・<span class='gd-jp'>逃げようにも逃げられない状況だった。</span>（當時是想逃也逃不了的狀況）</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>被外在狀況卡住</span>受傷、沒車、沒有聯絡方式……不是你不想，是條件不允許。</div><div class='gd-ex-line'>・<span class='gd-jp'>終電がなくて、帰ろうにも帰れない。</span>（末班車沒了，想回家也回不去）</div><div class='gd-ex-line'>・<span class='gd-jp'>足をけがしていて、歩こうにも歩けない。</span>（腳受傷了，想走也走不了）</div><div class='gd-sec'><span class='gd-tag'>心裡過不去</span>有時候卡住你的是情緒或回憶。</div><div class='gd-ex-line'>・<span class='gd-jp'>忘れようにも忘れられない思い出だ。</span>（那是想忘也忘不掉的回憶）</div><div class='gd-ex-line'>・<span class='gd-jp'>状況が深刻すぎて、笑おうにも笑えなかった。</span>（情況太嚴重，想笑也笑不出來）</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>動詞的意向形（「〜う／〜よう」，就是「〜吧」那個形）＋にも＋<b>同一個動詞</b>的「做不到」形（可能形的否定）。<br>中間常插一句原因：<span class='gd-jp'>帰ろうにも、終電がなくて帰れない。</span><br>後半也可以不重複動詞，直接講卡住你的原因：</div><div class='gd-ex-line'>・<span class='gd-jp'>電話しようにも、番号が分からない。</span>（想打電話，卻不知道號碼）</div><div class='gd-h'>怎麼變：先看動詞是哪一類</div><div class='gd-sec'><b>第一類（五段動詞）</b>：前半把最後一個音換成同一行的「お」段音，再加「う」；後半把最後一個音換成同一行的「え」段音，再加「ない」。<br><span class='gd-pair'><span class='gd-jp'>書く</span> → く換成こ → <span class='gd-jp'>書こう</span></span><span class='gd-pair'><span class='gd-jp'>書く</span> → く換成け → <span class='gd-jp'>書けない</span></span><br>合起來：<span class='gd-jp'>書こうにも書けない</span><br><span class='gd-pair'><span class='gd-jp'>帰る</span> → <span class='gd-jp'>帰ろうにも帰れない</span></span><br><span class='gd-pair'><span class='gd-jp'>話す</span> → <span class='gd-jp'>話そうにも話せない</span></span><br><span class='gd-pair'><span class='gd-jp'>会う</span> → <span class='gd-jp'>会おうにも会えない</span></span></div><div class='gd-sec'><b>第二類（一段動詞）</b>：前半把「る」拿掉加「よう」；後半把「る」拿掉加「られない」。<br><span class='gd-pair'><span class='gd-jp'>逃げる</span> → <span class='gd-jp'>逃げようにも逃げられない</span></span><br><span class='gd-pair'><span class='gd-jp'>忘れる</span> → <span class='gd-jp'>忘れようにも忘れられない</span></span></div><div class='gd-sec'><b>第三類（只有兩個，直接背）</b>：<br><span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>しようにもできない</span></span>，例：<span class='gd-jp'>予約しようにも予約できない</span><br><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来ようにも来られない</span>（こようにもこられない）</span></div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・前半一定要用意向形：是<span class='gd-jp'>帰ろうにも</span>，不是帰るようにも。它跟 N4 學的「〜ように」（為了～）沒關係，別看到「よう」就接辭書形。<br>・後半要是「<b>做不到</b>」，不是「不做」：寫成帰らない就變成「自己不想回」，跟前面的「想回」打架了。<br>・前提是本人<b>真的想做</b>。懶得做、沒興趣做，不能用這個句型。<br>・第二類的「做不到」，正式文章和考試要寫<span class='gd-jp'>逃げられない</span>；口語常聽到的「逃げれない」寫作時要避免。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>同樣講「逃」，看三種說法的差別：<br><b>ようにも</b>＝想做，但<b>根本做不到</b>：<span class='gd-jp'>逃げようにも、ドアに鍵がかかっていて逃げられない。</span>（想逃，但門鎖住了，逃不了）<br><b>たところで</b>＝就算做了，<b>也沒用</b>：<span class='gd-jp'>今さら逃げたところで、すぐに見つかるだろう。</span>（現在才逃，也很快會被找到）<br><b>ようと／ようが</b>＝<b>不管怎麼做</b>，結果都一樣：<span class='gd-jp'>どこへ逃げようと、必ず見つけ出す。</span>（不管你逃到哪裡，我一定把你找出來）</div><div class='gd-warn'>判斷小訣竅：「想做卻做不到」用ようにも，「做了也白做」用たところで，「不管怎麼做」用ようと／ようが。</div>",
  "n1-86": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜とは言い条」就是中文的<b>「雖說是～，但…」「名義上是～，其實…」</b>。前面先承認一個說法，後面馬上說「實際情況沒那麼簡單」。意思跟「とはいえ」差不多，只是更老派、更像文章裡的寫法，日常講話幾乎不會用。</div><div class='gd-h'>先懂「言い条」這個字</div><div class='gd-sec'><span class='gd-jp'>言い条</span>念<b>いいじょう</b>，原本是「說法、說詞」的意思。所以「Aとは言い条」照字面就是「說是A，那是一種說法」。言下之意是：<b>話是這麼說，但現實是另一回事</b>。</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>名詞直接接：<span class='gd-pair'><span class='gd-jp'>プロ</span> → <span class='gd-jp'>プロとは言い条</span></span><br>動詞、形容詞用普通形（就是沒有ます、です的說法）接：<span class='gd-pair'><span class='gd-jp'>分かっている</span> → <span class='gd-jp'>分かっているとは言い条</span></span><span class='gd-pair'><span class='gd-jp'>安い</span> → <span class='gd-jp'>安いとは言い条</span></span><br>實際看到最多的是<b>名詞直接接</b>。</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>名不符實</span>前面是大家公認的說法或名稱，後面點出現實不是那樣。</div><div class='gd-ex-line'>・<span class='gd-jp'>春とは言い条、朝晩はまだ冷える。</span>（雖說已經是春天，早晚還是很冷）</div><div class='gd-ex-line'>・<span class='gd-jp'>自由とは言い条、実際には多くの制約がある。</span>（名義上說是自由，實際上限制很多）</div><div class='gd-sec'><span class='gd-tag'>道理懂，做不到</span>承認前面那件事沒錯，但結果還是不理想。</div><div class='gd-ex-line'>・<span class='gd-jp'>頭では分かっているとは言い条、なかなか実行に移せない。</span>（雖然腦袋明白，卻遲遲付諸不了行動）</div><div class='gd-ex-line'>・<span class='gd-jp'>プロとは言い条、ミスを犯すこともある。</span>（雖說是專業人士，也難免會出錯）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・念法是<b>いいじょう</b>。「条」念じょう（長音），不要念成「いうじょう」或短短的「じょ」。<br>・它放在<b>句子中間</b>，後面一定還要接一句「但是…」的內容，不能單獨放在句尾就結束。<br>・這是很硬的書面語，用在評論、小說、文章裡。跟朋友聊天說「春とは言い条」會很像在念古書，口語說「<span class='gd-jp'>春だけど</span>」就好。<br>・考試看到它，只要認得「雖說～但…」就夠了，自己寫作時用「とはいえ」比較不會怪。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>三個意思都是「雖說～但…」，差在<b>多正式、多老派</b>。同一個情境比一比：<br><b>とはいうものの</b>：書面、正式場合講話也會用。<br></div><div class='gd-ex-line'>・<span class='gd-jp'>春とはいうものの、まだ寒い。</span>（雖說是春天，還是很冷）</div><div class='gd-sec'><b>とはいえ</b>：書面為主，新聞、文章很常見，正式一點的口語也聽得到。</div><div class='gd-ex-line'>・<span class='gd-jp'>春とはいえ、まだ寒い。</span>（雖說是春天，還是很冷）</div><div class='gd-sec'><b>とは言い条</b>：最古風，現代幾乎只在文章、文學作品裡看得到。</div><div class='gd-ex-line'>・<span class='gd-jp'>春とは言い条、まだ寒い。</span>（雖說是春天，還是很冷）</div><div class='gd-warn'>判斷小訣竅：意思都一樣是「雖說～但…」。越像古書、越文謅謅的就是「とは言い条」；平常寫文章選「とはいえ」最保險。</div>",
  "n1-87": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜かれ〜かれ」就是中文的<b>「遲早」「或多或少」「不管好壞」</b>。它不是可以自由套詞的句型，而是<b>三組固定說法</b>，整組背起來就好。</div><div class='gd-h'>它是怎麼來的</div><div class='gd-sec'>「かれ」是古文的命令形，大概等於「就算～也罷」。<br><span class='gd-jp'>多かれ少なかれ</span>原本的意思接近「多也罷、少也罷」，後來變成「不管多或少，反正都有」。<br>你不用學古文，只要知道：它是兩個<b>意思相反</b>的形容詞排在一起，表示「哪一邊都一樣，結果不會變」。</div><div class='gd-h'>最常聽到的三組</div><div class='gd-sec'><span class='gd-tag'>遅かれ早かれ</span>念「おそかれはやかれ」，＝遲早、早晚。後面通常接「一定會發生」的事，有「躲不掉」的感覺，日常對話也常講。</div><div class='gd-ex-line'>・<span class='gd-jp'>嘘は遅かれ早かればれるよ。</span>（謊話遲早會被拆穿的）</div><div class='gd-ex-line'>・<span class='gd-jp'>遅かれ早かれ、決めなきゃいけないことだ。</span>（這件事早晚都得做決定）</div><div class='gd-sec'><span class='gd-tag'>多かれ少なかれ</span>念「おおかれすくなかれ」，＝或多或少。後面常接「誰でも」「みんな」，表示人人都有，只是程度不同。</div><div class='gd-ex-line'>・<span class='gd-jp'>多かれ少なかれ、誰にでも悩みはある。</span>（每個人或多或少都有煩惱）</div><div class='gd-sec'><span class='gd-tag'>善かれ悪しかれ</span>念「よかれあしかれ」，＝不管是好是壞。比前兩組正式，多用在文章、評論。</div><div class='gd-ex-line'>・<span class='gd-jp'>善かれ悪しかれ、スマホは私たちの生活を大きく変えた。</span>（不管是好是壞，手機都大大改變了我們的生活）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・<b>不能自己造</b>：看到「形容詞＋かれ」就想套<span class='gd-jp'>高い</span>、<span class='gd-jp'>大きい</span>，這樣不行。實際上就是這三組。<br>・是<b>悪しかれ</b>，不是「悪かれ」。這裡用的是古文的「悪し」，不是現代的「悪い」。<br>・順序固定：講<span class='gd-jp'>遅かれ早かれ</span>、<span class='gd-jp'>多かれ少なかれ</span>，不要前後顛倒。<br>・單獨的<span class='gd-jp'>よかれと思って</span>是另一個說法，意思是「出於好意、以為這樣對對方好」，跟「不管好壞」無關。<br>　<span class='gd-jp'>よかれと思って言ったのに、怒られた。</span>（我是好意才說的，結果被罵了）</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>同樣是「不管A還是B」，<span class='gd-jp'>〜にせよ〜にせよ</span>和<span class='gd-jp'>〜であれ〜であれ</span>可以自由換詞，<span class='gd-jp'>〜かれ〜かれ</span>不行。</div><div class='gd-ex-line'>・<span class='gd-jp'>行くにせよ行かないにせよ、早めに連絡してね。</span>（不管去不去，都早點跟我說）</div><div class='gd-ex-line'>・<span class='gd-jp'>雨であれ雪であれ、試合は行われる。</span>（不管下雨還是下雪，比賽都照常舉行）</div><div class='gd-ex-line'>・<span class='gd-jp'>遅かれ早かれ、ばれるよ。</span>（遲早會被發現的）</div><div class='gd-sec'>反過來，「遲早」也不會說成<span class='gd-jp'>遅いにせよ早いにせよ</span>。這樣文法上沒錯，但聽起來像在討論「慢或快」兩種情況，不是「遲早」這個固定講法。日本人就是講<span class='gd-jp'>遅かれ早かれ</span>。<br>另外注意：<span class='gd-jp'>であれ</span>前面接名詞或な形容詞，<b>不接い形容詞</b>，所以「遅いであれ」本身就是錯的。</div><div class='gd-warn'>判斷小訣竅：想講「遲早／或多或少／不管好壞」，直接用かれ的三組；其他「不管A還是B」，用にせよ或であれ。</div>",
  "n1-88": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜始末だ」就是中文的<b>「搞到最後，居然還～」「落得～的下場」</b>。先講一連串不像話的事，最後丟出一個更糟的結局，口氣裡帶著<b>傻眼、受不了、數落</b>的感覺。像是你跟朋友抱怨：「他遲到就算了，東西也忘了帶，結果咧？最後還被主管罵。」</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>數落別人</span>最典型的用法。講某個人一路越來越離譜，最後到了誇張的地步。</div><div class='gd-ex-line'>・<span class='gd-jp'>息子は毎晩ゲームばかりして、ついには学校を休む始末だ。</span>（兒子每天晚上都在打電動，最後居然搞到連學校都不去了）</div><div class='gd-ex-line'>・<span class='gd-jp'>彼は何度注意しても聞かず、最近は返事もしない始末だ。</span>（他怎麼講都不聽，最近甚至連回話都不回了）</div><div class='gd-sec'><span class='gd-tag'>自嘲</span>講自己也可以，帶著「我真是夠了」的自我吐槽。</div><div class='gd-ex-line'>・<span class='gd-jp'>寝坊して駅まで走ったのに、財布を家に忘れる始末だ。</span>（睡過頭一路衝到車站，結果還把錢包忘在家裡）</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>動詞辭書形＋始末だ：<span class='gd-pair'><span class='gd-jp'>休む</span> → <span class='gd-jp'>休む始末だ</span></span><br>動詞ない形＋始末だ：<span class='gd-pair'><span class='gd-jp'>しない</span> → <span class='gd-jp'>返事もしない始末だ</span></span><br>指示詞＋始末だ：<span class='gd-jp'>この始末だ</span>、<span class='gd-jp'>あの始末だ</span>（「搞成這副德性」）</div><div class='gd-ex-line'>・<span class='gd-jp'>あれほど言ったのに、この始末だ。</span>（我都講成那樣了，結果還是搞成這樣）</div><div class='gd-h'>最常聽到的樣子</div><div class='gd-sec'>前面常搭配「到最後」這類的詞，把「一路越來越糟」的感覺鋪出來：<span class='gd-jp'>ついには</span>、<span class='gd-jp'>とうとう</span>、<span class='gd-jp'>最後には</span>、<span class='gd-jp'>挙句の果てには</span>。</div><div class='gd-ex-line'>・<span class='gd-jp'>借金を重ね、挙句の果てには夜逃げする始末だ。</span>（債越欠越多，到最後落得連夜跑路）</div><div class='gd-sec'>講過去的事時，前面一樣用辭書形，句尾可以用<span class='gd-jp'>始末だった</span>。</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・前面用<b>辭書形或ない形</b>，不要接た形：是<span class='gd-jp'>叱られる始末だ</span>，不是叱られた始末だ。<br>・<b>只能用在壞結果</b>。「努力讀書，最後考上了」不能用始末だ。<br>・要有<b>前面的鋪陳</b>。只丟一句「他遲到的始末だ」很怪，要先交代前面怎麼一步步變糟。<br>・口氣是在<b>數落、抱怨</b>，當著主管或客人的面這樣講他們，非常不客氣。比較常出現在抱怨、文章、評論裡。<br>・單獨的<span class='gd-jp'>始末</span>還有「收拾、處理」的意思，像<span class='gd-jp'>後始末</span>（善後）、<span class='gd-jp'>始末書</span>（悔過書），跟這個句型是兩回事。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>同樣講「最後變成～」，還有 N2 學過的「末に」「羽目になる」，差在<b>結果好不好、在講誰、說話的人什麼心情</b>。<br><b>末に</b>＝經過一番過程後的結論，<b>中性</b>，好結果也行：<br><span class='gd-jp'>何度も話し合った末に、ゲームは一日一時間と決めた。</span>（討論了好幾次，最後決定一天只玩一小時）<br><b>羽目になる</b>＝<b>自己</b>被迫落得做某件麻煩事，帶著後悔：<br><span class='gd-jp'>息子のゲームの課金を、私が払う羽目になった。</span>（兒子遊戲課的金，最後變成我得來付）<br><b>始末だ</b>＝說話的人<b>傻眼、數落</b>某人「居然搞到這種地步」：<br><span class='gd-jp'>息子はゲームに夢中で、ついには学校を休む始末だ。</span>（兒子迷電動，最後居然連學校都不去了）</div><div class='gd-warn'>判斷小訣竅：中性的「最後決定～」用末に；「害我不得不～」用羽目になる；想翻白眼說「搞到最後居然還～」就用始末だ。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>常跟「〜あげく」一起出現：<span class='gd-jp'>さんざん迷ったあげく、何も買わずに帰ってくる始末だ。</span>（猶豫了老半天，最後居然什麼都沒買就回來了）</div>",
  "n1-90": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜にかこつけて」就是中文的<b>「藉～之名」「拿～當藉口」</b>。表面上是為了 A，其實心裡真正想做的是 B。像是說「我去出差」，結果大半時間都在逛街吃美食，這種「掛羊頭賣狗肉」的感覺就是它。</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>名詞＋にかこつけて，後面接真正想做的事。<br><span class='gd-pair'><span class='gd-jp'>出張</span> → <span class='gd-jp'>出張にかこつけて</span></span>（藉出差之名）<br><span class='gd-pair'><span class='gd-jp'>仕事</span> → <span class='gd-jp'>仕事にかこつけて</span></span>（拿工作當藉口）<br>前面放的是「說得出口的正當理由」，後面才是「其實想做的事」。</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>吐槽別人</span>最常見的用法。看不慣某人拿正當理由當幌子，帶點批評。</div><div class='gd-ex-line'>・<span class='gd-jp'>部長は視察にかこつけて、毎年ハワイに行っている。</span>（部長每年都藉視察之名跑去夏威夷）</div><div class='gd-ex-line'>・<span class='gd-jp'>彼は仕事にかこつけて、毎晩飲みに行っている。</span>（他拿工作當藉口，每天晚上都跑去喝酒）</div><div class='gd-sec'><span class='gd-tag'>自嘲</span>講自己也可以，等於自己承認「其實我是想做那件事啦」，口氣有點不好意思、有點好笑。</div><div class='gd-ex-line'>・<span class='gd-jp'>子どもの誕生日にかこつけて、自分が食べたいケーキを買った。</span>（藉孩子生日之名，買了我自己想吃的蛋糕）</div><div class='gd-ex-line'>・<span class='gd-jp'>雨にかこつけて、ジムをサボった。</span>（拿下雨當藉口，翹掉了健身房）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・助詞是<b>に</b>，不是を。意思很像的日常說法「〜を口実に」才用を，兩個不要混在一起，寫成「出張をかこつけて」是錯的。<br>・它一定帶<b>「表面理由跟真正目的不一樣」</b>的味道。如果你真的是去出差，只是順便看看風景，用它就會變成在說自己「假出差、真玩樂」。<br>・因為帶批評或自嘲的口氣，不適合在正式場合拿來說明自己的行程。例如跟主管報告時說「出張にかこつけて…」，等於自己承認在摸魚。<br>・平常大多寫成平假名。漢字寫作「託けて」，不太常看到，認得就好。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>同一個情境：出差時去了京都觀光。<br><b>がてら</b>＝<b>順便</b>，兩件事都是真的，光明正大：<br><span class='gd-jp'>出張がてら、京都を観光した。</span>（出差順便在京都觀光）<br><b>かたがた</b>＝也是「順便、兼」，但比較正式，常用在拜訪、致謝這類場合：<br><span class='gd-jp'>お礼かたがた、先生のお宅に伺った。</span>（去老師家拜訪，順便表達謝意）<br><b>にかこつけて</b>＝前面的理由只是<b>幌子</b>，真正目的是後面那件事：<br><span class='gd-jp'>出張にかこつけて、京都を観光した。</span>（藉出差之名，其實是去京都玩）</div><div class='gd-warn'>判斷小訣竅：兩件事都是真心要做的，用「がてら」，正式場合用「かたがた」；前面的理由只是藉口、後面才是真正想做的，就用「にかこつけて」。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>日常對話更常聽到「〜を口実に」，意思幾乎一樣，口氣比較直接：<span class='gd-jp'>風邪を口実に、会社を休んだ。</span>（拿感冒當藉口，跟公司請假）</div>",
  "n1-92": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「AとBが相まって」就是<b>「A 跟 B 兩個因素湊在一起，效果加倍」</b>。像中文說「天時加上地利」「累加上沒睡飽」：單看一個還好，兩個一疊，結果就特別明顯。好的壞的都能用，常出現在新聞、評論、文章裡。</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>前面接<b>名詞</b>。常見的有三種樣子：<br><span class='gd-tag'>AはBと相まって</span>主角 A 跟另一個因素 B 結合。</div><div class='gd-ex-line'>・<span class='gd-jp'>彼の才能は努力と相まって、大きな成果を生んだ。</span>（他的才能加上努力，創造了很大的成果）</div><div class='gd-sec'><span class='gd-tag'>AとBが相まって</span>兩個因素並排放，一起造成後面的結果。</div><div class='gd-ex-line'>・<span class='gd-jp'>この店は料理の味と雰囲気の良さが相まって、いつも予約でいっぱいだ。</span>（這家店料理好吃，氣氛又好，所以總是訂滿）</div><div class='gd-sec'><span class='gd-tag'>Bも相まって</span>新聞最常見。用「も」表示「本來就有其他原因，<b>再加上</b>B」。</div><div class='gd-ex-line'>・<span class='gd-jp'>円安も相まって、外国人観光客が急増している。</span>（再加上日圓貶值，外國觀光客暴增）</div><div class='gd-sec'>前面如果是一整句話，要先加「こと」變成名詞：<br><span class='gd-pair'><span class='gd-jp'>駅から近い</span> → <span class='gd-jp'>駅から近いことも相まって</span></span>（再加上離車站近）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・念<b>あいまって</b>，不是「そうまって」。<br>・一定要有<b>兩個以上的因素</b>。只有一個原因時不能用：下雨害比賽取消，就直接說<span class='gd-jp'>雨で試合が中止になった</span>，不能說「雨と相まって中止になった」。<br>・不是只能用在好事，壞事一樣可以用：<span class='gd-jp'>寝不足と疲れが相まって、熱を出してしまった。</span>（睡眠不足加上疲勞，結果發燒了）所以別把它想成中文的「相輔相成」，「相輔相成」只用在好事上。<br>・這是偏正式、偏書面的說法。跟朋友聊天時，說<span class='gd-jp'>〜もあって</span>、<span class='gd-jp'>〜も重なって</span>比較自然。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'><b>に加えて</b>＝單純「除了 A，還有 B」，只是把事情一件一件列出來：<br><span class='gd-jp'>円安に加えて、物価も上がっている。</span>（除了日圓貶值，物價也在上漲）<br><b>と相まって</b>＝兩個因素<b>一起起作用</b>，造成某個結果：<br><span class='gd-jp'>円安と物価高が相まって、生活が苦しくなっている。</span>（日圓貶值加上物價高漲，生活變得很辛苦）</div><div class='gd-sec'><b>とあって</b>（只差一個字，很容易看錯）＝「因為是～這種特別的情況，所以…」，原因只有一個：<br><span class='gd-jp'>連休とあって、どこも混んでいる。</span>（因為是連假，到處都人擠人）<br><b>と相まって</b>＝兩個原因疊在一起：<br><span class='gd-jp'>連休と好天が相まって、どこも混んでいる。</span>（連假加上好天氣，到處都人擠人）</div><div class='gd-warn'>判斷小訣竅：只是「還有～」用に加えて；「因為是～」用とあって；「兩個因素一疊，效果加倍」才用と相まって。</div>"
});
(window.GRAMMAR_DETAIL_LV = window.GRAMMAR_DETAIL_LV || {}).n1 = true;
